}

private func csParseDouble(_ s: String?) -> Double? {
    guard let s = s else { return nil }
    let t = s.Trim()
    if t.isEmpty { return nil }
    if t == "NaN" { return Double.nan }
    if t == "Infinity" || t == "∞" { return Double.infinity }
    if t == "-Infinity" || t == "-∞" { return -Double.infinity }
