        return String(self[a..<b])
    }

    private func csIndexOf(_ s: String, _ start: Int, _ cmp: StringComparison, _ backwards: Bool) -> Int {
        if s.isEmpty { return backwards ? Swift.max(0, Length - 1) : Swift.max(0, Swift.min(start, Length)) }
