    // --- Split (on Unicode scalars, so "\r\n" splits on '\n' like C#) ---
    private func csSplit(_ seps: [Unicode.Scalar], _ opt: StringSplitOptions) -> [String] {
        let sepSet = seps.isEmpty ? nil : Set(seps)
