final class ColorBlend {
    var Colors: [Color] = []
    var Positions: [Double] = []
    init() {}
    init(_ n: Int) { Colors = Array(repeating: DeskPalsColor.Black, count: n); Positions = Array(repeating: 0, count: n) }
}
