    var key: Color? = nil
    init() {}
    func SetColorMatrix(_ m: ColorMatrix) { alpha = m.Matrix33 }
    func SetColorKey(_ lo: Color, _ hi: Color) { key = lo }
    func SetWrapMode(_ m: WrapMode) {}
