        p.Say("g_evening", "Eh-oh～晚上了，辛苦了"); p.Say("g_day", "Eh-oh! 拉拉來玩球囉！"); p.Say("g_d", "太陽寶寶下山了…你怎麼還在？")
        p.Say("s_birthday", "生日快樂！拉拉唱歌給你聽 🎂 啦啦～", "今天你最大！大抱抱！")
        p.Say("s_cny", "新年快樂！恭喜恭喜 🧧", "紅包…拉拉可以拿嗎？")
