}

// ===== 30_pet_a.swift =====
// 30_pet_a.swift — port of DeskPals.cs lines 1572–2696 (Pet partial #1: owns `final class Pet`)

final class Pet {
    var P: Pal!
    var w: World!
    var S = 0, SW = 0, SH = 0
    var k: Double = 0
    var rnd: Random!
    var Form: PetForm! = nil
    var Menu: ContextMenuStrip! = nil
    var Bub: BubbleForm! = nil

    var Out = false              // 在桌面上（含出櫃、回櫃的動畫）
    var InScene = false          // 正在演串場戲（由 World 控制）
    var x: Double = 0, y: Double = 0, vx: Double = 0, vy: Double = 0, t: Double = 0, anim: Double = 0, sense: Double = 0, z: Double = 0
    var dir = 1
    var state = "air"
    var sleepMode = false
    var sc: Double = 1, gt: Double = 0, knock: Double = 0     // 敲螢幕：放大倍率、計時、敲的晃動
    var afterGlass = ""

    // Spidey：絲的錨點／擺盪／倒吊／爬牆／噴絲
    var ax: Double = 0, ay: Double = 0, ropeL: Double = 0, th: Double = 0, om: Double = 0, targetL: Double = 0; var hangPhase = 0
    var wallSide = 0, climbDir = 0
    var shootT: Double = 0; var nextAct = ""; var zipH: IntPtr = 0; var zipRight = false
    var reelT: Double = 0, reelX: Double = 0, reelY: Double = 0
    var supH: IntPtr = 0; var supL = 0, supR = 0, supWinL = 0
    var goClimb = false
    var seekX: Double = 0

    var bubble = ""; var Bt: Double = 0; var bubbleAlert = false
    var dragging = false, dragSaid = false; var dragStart = Point(0, 0); var grabDx: Double = 0, grabDy: Double = 0, dragMoved: Double = 0, lastMx: Double = 0, lastMy: Double = 0, lastMt: Double = 0, dvx: Double = 0, dvy: Double = 0
    var hearts = List<Arr<Double>>()
    var sparks = List<Arr<Double>>()
    var notes = List<Arr<Double>>()   // 音符、驚嘆號等小圖（x 偏移, 年齡, 種類）
    var clickTimes = List<Double>()
    var flakes = List<Arr<Double>>()
    var dizzyOnLand = false, rolling = false
    var jokeT: Double = 0, tripT: Double = 0, capeT: Double = 0     // 人魚漢頓：笑話後追問、跌倒、披風
    var fetching = false
    var hoverCd: Double = 0, seekCd: Double = 20, lateCd: Double = 120, stuckRepeat: Double = 0
    var stuckLine: String? = nil

    // 公仔櫃動畫
    var flyT: Double = 0, flyDur: Double = 0, fx0: Double = 0, fy0: Double = 0, fx1: Double = 0, fy1: Double = 0, flyArc: Double = 0
    var shelfPs = 0                    // 進櫃子時縮到的大小
    var afterLand = ""                 // 落地後要做的事（wave／sniff／evil…）
    var ShelfFx: Double = 0            // 回櫃子後在格子裡的特效（Spidey 織網、小波轉圈…）0→1

    var bubblePri = 0                  // 通知的泡泡（>0）不會被閒聊蓋掉

    // 好感度
    var xp = 0; var lastPatDay = ""
    var patsToday = 0; var patsDate = ""
    var saveXpCd: Double = 0; var ballXp = 0

    var nearMiss = false
    var gotoSpeed: Double = 1
    var hideX: Double = 0
    var who = "Claude"

    // ---- from 31_pet_b.swift ----
    var poseKind = ""           // pose 狀態畫哪個姿勢（homerun／hero／photo／grin）
    var batT = 0.0; var batHit = false       // 小波揮棒
    var scooterLost = false               // 小波的滑板車被史迪仔騎走了（串場）
    var RidingStolen = false       // 史迪仔正在騎別人的滑板車（串場）
    var crawlH: IntPtr = 0; var ceilY = 0.0, ceilL = 0.0, ceilR = 0.0 // 史迪仔爬牆／天花板
    var caped = false
    var headers = 0
    // ---- 天線寶寶 ----
    var hatLost = false                   // 迪西：帽子借給丁丁戴了（串場）
    var WearHat = false            // 戴著迪西的帽子（串場）
    var ballLost = false                  // 拉拉：球不見了（滾進丁丁的魔法袋、踢給小波）
    var RidingPo = false           // 丁丁騎小波的滑板車（串場）
    var HoldToast = false          // 吐司時間：手上拿著吐司（串場）
    var lentScooter = false               // 小波：滑板車借出去了（串場結束一定還回來）
    var bagItem = ""            // 魔法袋這次拿出來的東西
    var sT = 0.0, lastLandVy = 0.0          // 專屬動作計時、落地前的速度
    var juggles = 0
    var lastArmsUp = false
    var bagQuiet = false
    // ---- from 32_pet_draw.swift ----
    var frameBmp: Bitmap! = nil
    // ---- from 42_world_c.swift ----
    var bubbleHint: String! = nil

    init(_ w: World, _ p: Pal, _ S: Int, _ seed: Int) {
        self.w = w; P = p; self.S = S
        k = Double(S) / 3.0
        SW = 12 * S; SH = 16 * S
        rnd = Random(seed)
        LoadBond()
    }
}

extension Pet {
    func EnsureForms() {
        if Form != nil { return }
        Form = PetForm(self)
        Menu = ContextMenuStrip()
        Menu.Opening = { [unowned self] in self.w.FillMenu(self, self.Menu) }
        w.HookMenu(Menu)
        Bub = BubbleForm(P.Accent)
    }

    func HideForms() {
        if Form != nil && W.Shown(Form) { Form.Hide() }
        if Bub != nil && W.Shown(Bub) { Bub.Hide() }
    }

    func CloseForms() {
        if Form != nil { Form.Close(); Bub.Close() }
    }

    var Night: Bool { return w.Night }
    func Grounded() -> Bool {
        switch state {
        case "walk", "idle", "sleep", "hug", "seek", "dizzy", "fetch", "dance", "kick", "wave", "pose", "bat", "catch", "header", "capetrip", "elvis", "chomp", "think", "hide", "nudge", "spin", "goto",
             "plop", "twirl", "hattoss", "juggle", "bagdig":
            return true
        default:
            return false
        }
    }
    func Free() -> Bool { return Out && !InScene && !dragging && Grounded() && state != "sleep" && state != "hug" && !(Bt > 0 && bubblePri > 0) }
    func SetState(_ s: String, _ dur: Double) { state = s; t = dur }
    func Say(_ s: String?, _ sec: Double) { Say(s, sec, false) }
    func Say(_ s: String?, _ sec: Double, _ alert: Bool) { if string.IsNullOrEmpty(s) { return }; bubble = s!; Bt = sec; bubbleAlert = alert; bubbleHint = nil; bubblePri = 0 }
    func Pick(_ a: [String]) -> String { return a[rnd.Next(a.count)] }
    func R(_ a: Double, _ b: Double) -> Double { return a + rnd.NextDouble() * (b - a) }
    static func Clamp(_ v: Double, _ lo: Double, _ hi: Double) -> Double { return v < lo ? lo : (v > hi ? hi : v) }
    static func Ease(_ v: Double) -> Double { let v = Clamp(v, 0, 1); return v * v * (3 - 2 * v) }
    func Clamp(_ v: Double, _ lo: Double, _ hi: Double) -> Double { return Pet.Clamp(v, lo, hi) }
    func Ease(_ v: Double) -> Double { return Pet.Ease(v) }
    var Cx: Double { return x + Double(SW) / 2.0 }
    func Is(_ id: String) -> Bool { return P.Id == id }

    // 台詞：夜晚優先用 key_d；{n}{who}{tool}{u} 代換
    func L(_ key: String, _ kv: String...) -> String {
        var a: [String] = []
        if Night && P.Lines.TryGetValue(key + "_d", &a) { }
        else if !P.Lines.TryGetValue(key, &a) { App.Log("missing line " + P.Id + "." + key); return "" }
        var s = Pick(a)
        var i = 0
        while i + 1 < kv.count { s = s.Replace("{" + kv[i] + "}", kv[i + 1]); i += 2 }
        return s
    }

    func Jump(_ jvx: Double, _ jvy: Double) { vx = jvx; vy = jvy; supH = IntPtr.Zero; SetState("air", 0) }
    func Hop() { Jump(Double(dir) * 60 * k, -260 * k) }
    func GoSleep() { z = 0; SetState("sleep", 1e9) }
    func WakeIfSleep() { sleepMode = false; if state == "sleep" { SetState("walk", 2) } }
    func AddHeart() { if hearts.Count < 8 { hearts.Add(Arr<Double>([R(-12, 12) * k, 0])) } }
    func Mark(_ kind: Int) { if notes.Count < 12 { notes.Add(Arr<Double>([R(-10, 10) * k, 0, Double(kind)])) } } // 0 音符 1 驚嘆號 2 問號 3 Zz 4 汗滴 5 泡泡

    func Burst(_ n: Int) {
        let cx = Cx, cy = y + Double(SH) * 0.35
        var i = 0
        while i < n {
            let a = rnd.NextDouble() * Math.PI * 2, sp = R(120, 260) * k
            let svy: Double = Math.Sin(a) * sp - 120 * k
            sparks.Add(Arr<Double>([cx, cy, Math.Cos(a) * sp, svy, 0]))
            i += 1
        }
    }

    // ---------- 好感度（每個角色各自一份）----------
    static let LV: [Int] = [0, 0, 15, 50, 120, 250, 500]
    static let UNLOCK: [String] = ["", "", "黃圍巾", "小毛帽", "愛心眼鏡", "金色胸章", "小皇冠"]
    func BondFile() -> String { return Path.Combine(World.DataDir, "bond-" + P.Id + ".txt") }
    func PatsFile() -> String { return Path.Combine(World.DataDir, "pats-" + P.Id + ".txt") }
    func LoadBond() {
        if let txt = try? File.ReadAllText(BondFile()) {
            let a = txt.Trim().Split(" ")
            if a.count > 0 { _ = int.TryParse(a[0], &xp) }
            if a.count > 1 { lastPatDay = a[1] }
        }
        if let txt = try? File.ReadAllText(PatsFile()) {
            let a = txt.Trim().Split(" ")
            if a.count == 2 && a[0] == DateTime.Now.ToString("yyyy-MM-dd") { patsDate = a[0]; _ = int.TryParse(a[1], &patsToday) }
        }
    }
    func SaveBond() { _ = try? Directory.CreateDirectory(World.DataDir); _ = try? File.WriteAllText(BondFile(), xp.ToString() + " " + lastPatDay) }
    func BumpPats() {
        let today = DateTime.Now.ToString("yyyy-MM-dd")
        if today != patsDate { patsDate = today; patsToday = 0 }
        patsToday += 1
        _ = try? Directory.CreateDirectory(World.DataDir); _ = try? File.WriteAllText(PatsFile(), patsDate + " " + patsToday.ToString())
    }
    func Level() -> Int { var lv = 1; var i = 2; while i < Pet.LV.count { if xp >= Pet.LV[i] { lv = i }; i += 1 }; return lv }
    func AddXp(_ n: Int) {
        let before = Level()
        xp += n; SaveBond()
        let now = Level()
        if now > before {
            Hug(L("levelup", "n", now.ToString(), "u", Pet.UNLOCK[now]), 4)
            AddHeart(); AddHeart(); AddHeart(); Burst(14)
        }
    }
    func DaysSincePat() -> Int {
        var d = DateTime.MinValue
        if !DateTime.TryParse(lastPatDay, &d) { return 0 }
        return CInt((DateTime.Now.Date - d.Date).TotalDays)
    }
    func ShowBond() {
        let lv = Level()
        let got = List<String>()
        var i = 2
        while i <= lv { got.Add(Pet.UNLOCK[i]); i += 1 }
        let next = lv < 6 ? "（" + xp.ToString() + "/" + Pet.LV[lv + 1].ToString() + "）" : "（" + xp.ToString() + "，滿級！）"
        let tail = got.Count > 0 ? "　已解鎖：" + string.Join("、", got.ToArray()) : "　多摸摸我就會升級喔"
        Say(P.Name + " 好感度 Lv" + lv.ToString() + next + tail, 4.5)
        AddHeart()
    }

    // 被點了一下（通知優先，沒有通知就是摸摸）
    func Clicked() {
        if w.NoticeClicked(self) { return }
        Pat()
    }

    // ---------- 點他（沒拖動）----------
    func Pat() {
        let now = w.Now
        clickTimes.Add(now)
        clickTimes.RemoveAll { c in now - c > 1.3 }
        let combo = clickTimes.Count
        BumpPats()
        w.Count("pats")
        lastPatDay = DateTime.Now.ToString("yyyy-MM-dd")
        if patsToday <= 30 { AddXp(1) } else { SaveBond() }
        Burst(combo >= 3 ? 10 : 6)
        if w.quietOn {
            // 安靜中：小小回應就好
            AddHeart()
            Say(Pick(["♥", "（小聲）嗯～", "噓…♥"]), 1.0)
            return
        }
        if state == "sleep" {
            WakeIfSleep()
            Hug(L("wake"), 2.4)
            return
        }
        if combo >= 5 {
            if Grounded() { SetState("dizzy", 1.6) } else { dizzyOnLand = true }
            Say(L("dizzy"), 2)
            return
        }
        if combo >= 3 { PatCombo(); return }
        if patsToday % 10 == 0 {
            Hug(L("pat10", "n", patsToday.ToString()), 3)
            AddHeart(); AddHeart(); AddHeart()
            return
        }
        let line = !Night && Level() >= 4 && rnd.NextDouble() < 0.4 ? L("pats_hi") : L("pats")
        if Is("hangyodon") && !Night && P.Lines["pats"].contains(line) { jokeT = 2.6 }
        if Grounded() { Hug(line, 2.6) }
        else { Say(line, 2.2); AddHeart() }
    }

    // 連點三下：每個角色不一樣
    func PatCombo() {
        AddHeart()
        switch P.Id {
        case "po":   // 咯咯笑＋原地轉一圈「再來一次！」
            Say(L("tickle"), 1.8)
            if Grounded() && state != "dizzy" { SetState("spin", 0.9); Jump(0, -340 * k); rolling = true }
        case "stitch": // 笑到捲成球滾來滾去
            Say(L("tickle"), 1.8)
            if Grounded() && state != "dizzy" { rolling = true; Jump(Double(dir) * R(120, 220) * k, -240 * k) }
        case "hangyodon": // 扮鬼臉（鬥雞眼＋嘟嘴）
            if Grounded() && state != "dizzy" { poseKind = "silly"; SetState("pose", 1.8) }
            Say(L("tickle"), 1.8)
        case "tinky":  // 跌坐在地上「哎喲！」
            Say(L("tickle"), 1.8)
            if Grounded() && state != "dizzy" { Plop(nil) }
        case "dipsy":  // 帽子不准摸：把帽子丟起來接住，或酷酷地跳一段
            Say(L("tickle"), 1.8)
            if Grounded() && state != "dizzy" { if rnd.NextDouble() < 0.5 { HatToss(true) } else { SetState("dance", 1.8) } }
        case "laalaa": // 啦啦啦～轉圈圈
            Say(L("tickle"), 1.8)
            if Grounded() && state != "dizzy" { SetState("twirl", 1.3) }
        default:
            Say(L("tickle"), 1.6)
            if Grounded() && state != "dizzy" { Jump(Double(dir) * 40 * k, -330 * k) }
        }
    }

    func Hug(_ text: String, _ sec: Double) {
        if Grounded() { SetState("hug", sec) }
        Say(text, sec)
        AddHeart(); AddHeart()
    }

    // ---------- 滑鼠：停在身上 → 抱抱；停在附近 → 跑過去 ----------
    func Watch(_ dt: Double) {
        if stuckLine != nil { stuckRepeat -= dt; if stuckRepeat <= 0 { Say(stuckLine, 6, true); stuckLine = nil } }
        seekCd -= dt; hoverCd -= dt; lateCd -= dt; saveXpCd -= dt
        if !Grounded() || state == "hug" || sleepMode || state == "sleep" || InScene || Quiet { return }
        let c = Cursor.Position
        let cx = Cx, still = w.CursorStill
        let cX = Double(c.X), cY = Double(c.Y)
        let onMe = cX >= x && cX <= x + Double(SW) && cY >= y && cY <= y + Double(SH)
        if onMe && still > 1.2 && hoverCd <= 0 { hoverCd = 12; Hug(L("hover"), 2.4); return }
        let nearY: Bool = cY > y - 40 * k && cY < y + Double(SH) + 8
        let nearX: Bool = Math.Abs(cX - cx) < 380 * k && Math.Abs(cX - cx) > 8
        if !fetching && state != "seek" && seekCd <= 0 && still > 2.5 && !onMe && nearY && nearX {
            seekX = cX; seekCd = R(45, 100)
            if Is("stitch") && rnd.NextDouble() < 0.4 { SetState("seek", 8); afterLand = "nudge"; Say("嘻嘻嘻…", 1.2) }
            else { SetState("seek", 8); Say(L("seek"), 1.2) }
        }
    }

    // ================= 每一格 =================
    func Tick(_ dt: Double) {
        if !Out { return }
        if !(dragging && DragUpdate(w.Now, dt)) { Watch(dt); Step(dt) }
        Render()
    }

    func Step(_ dt: Double) {
        anim += dt; t -= dt
        if Bt > 0 { Bt -= dt }
        if sense > 0 { sense -= dt }
        if jokeT > 0 { jokeT -= dt; if jokeT <= 0 { Say("好笑嗎？好笑嗎？", 1.8); if Grounded() { Jump(0, -180 * k) } } }
        if tripT > 0 { tripT -= dt }
        var i = hearts.Count - 1
        while i >= 0 { hearts[i][1] += dt; if hearts[i][1] > 1.6 { hearts.RemoveAt(i) }; i -= 1 }
        i = notes.Count - 1
        while i >= 0 { notes[i][1] += dt; if notes[i][1] > 1.8 { notes.RemoveAt(i) }; i -= 1 }
        i = sparks.Count - 1
        while i >= 0 {
            let sp = sparks[i]
            sp[3] += 420 * k * dt; sp[0] += sp[2] * dt; sp[1] += sp[3] * dt; sp[4] += dt
            if sp[4] > 0.75 { sparks.RemoveAt(i) }
            i -= 1
        }
        if w.SeasonNow == "xmas" && rnd.NextDouble() < dt * 3 {
            let fxx: Double = Cx + R(-70, 70) * k
            let fyy: Double = y - R(30, 90) * k
            flakes.Add(Arr<Double>([fxx, fyy, R(-12, 12) * k, 0]))
        }
        i = flakes.Count - 1
        while i >= 0 {
            let f = flakes[i]
            f[1] += 38 * k * dt
            let drift: Double = f[2] + Math.Sin(f[3] * 3) * 10 * k
            f[0] += drift * dt; f[3] += dt
            if f[3] > 2.2 { flakes.RemoveAt(i) }
            i -= 1
        }
        FollowFast()
        let wa = w.WA(Cx, y + Double(SH) / 2.0)
        if StepSpecial(dt, wa) { return }   // 角色專屬狀態
        switch state {
        case "walk":
            if sleepMode { GoSleep(); break }
            if MoveOnGround(dt, P.Speed * k) { break }
            if t < 0 { Decide(wa) }
        case "seek": Seek(dt)
        case "idle":
            if !InScene { let cp = Cursor.Position; if Math.Abs(Double(cp.X) - Cx) > 20 { dir = Double(cp.X) > Cx ? 1 : -1 } }
            if sleepMode { GoSleep() }
            else if t < 0 && !InScene { SetState("walk", R(3, 6)) }
        case "fetch": Fetch(dt)
        case "dance", "kick", "pose", "wave", "think":
            if t < 0 && !InScene { SetState("idle", R(1, 2)); DoAfter() }
        case "dizzy":
            if Math.Floor(anim * 8) != Math.Floor((anim - dt) * 8) { dir = -dir }
            if t < 0 { SetState("idle", 1); Say(L("dizzy_ok"), 1.4) }
        case "hug":
            if rnd.NextDouble() < dt * 2.5 { AddHeart() }
            if t < 0 && !InScene { SetState("walk", R(2, 4)) }
        case "sleep": z += dt; if t < 0 { SetState("walk", 3) }
        case "air": Air(dt)
        case "glass": Glass(dt)
        case "stowfly": StowFly(dt)
        case "enter": Enter(dt)
        case "exit": Exit(dt)
        case "hide": HideBehind(dt)
        case "goto": GoTo(dt)
        case "fling": Fling(dt)
        default: break
        }
    }

    func DoAfter() {
        let a = afterLand; afterLand = ""
        if a == "trip" { tripT = 1.1; SetState("think", 1.1); Say(Pick(["哎呀…（跌倒）", "嗚…英雄也會跌倒的", "我、我沒事！"]), 1.8) }
    }

    // 回傳 true＝離開地面或換狀態了
    @discardableResult
    func MoveOnGround(_ dt: Double, _ speed: Double) -> Bool {
        let nx: Double = x + Double(dir) * speed * dt
        let ncx: Double = nx + Double(SW) / 2.0, midY: Double = y + Double(SH) / 2.0
        if supH != IntPtr.Zero {
            if ncx < Double(supL) || ncx > Double(supR) {
                if state == "walk" { let e = EdgeOfWindow(ncx > Double(supR)); if e == 2 { return true }; if e == 1 { return false } }
                x = nx
                Jump(Double(dir) * speed * 1.4, -140 * k)
                return true
            }
            x = nx
            return false
        }
        let lead: Double = dir > 0 ? nx + Double(SW) - 1 : nx
        if !w.Inside(lead, midY) {
            if state == "walk" && EdgeOfScreen() { return true }
            dir = -dir
            return false
        }
        let floorY = Double(w.WA(ncx, midY).Bottom - SH)
        if floorY > y + 2 { x = nx; Jump(Double(dir) * speed, 0); return true }
        if floorY < y - 2 { dir = -dir; return false }
        x = nx; y = floorY
        return false
    }

    func Seek(_ dt: Double) {
        let c = Cursor.Position
        let cX = Double(c.X), cY = Double(c.Y)
        if Math.Abs(cX - seekX) > 4 {
            if cY > y - 60 * k && cY < y + Double(SH) + 20 { seekX = cX }
            else { SetState("walk", 2); afterLand = ""; Say(L("seek_lost"), 1.4); return }
        }
        if Math.Abs(seekX - Cx) < 6 {
            if afterLand == "nudge" { afterLand = ""; SetState("nudge", 1.6); Say(Pick(["ih-ih-ih!（推推）", "嘻嘻，推一下～", "這個是史迪仔的！"]), 1.8); return }
            Hug(L("seek_got"), 3); return
        }
        dir = seekX > Cx ? 1 : -1
        let spd: Double = Is("hangyodon") || Is("tinky") ? 60 : 95
        if MoveOnGround(dt, spd * k) { return }
        let ncx = Cx
        if (dir > 0 && ncx > seekX) || (dir < 0 && ncx < seekX) { x = seekX - Double(SW) / 2.0 }
        if t < 0 { SetState("walk", 2) }
    }

    // 拋物線跳到某一點（腳落在 footY）
    func BallisticTo(_ tx: Double, _ footY: Double) {
        let cx = Cx, foot: Double = y + Double(SH), g: Double = 900 * k
        let top = w.WA(cx, y)
        var apex: Double = Math.Max(Math.Min(foot, footY) - R(60, 130) * k, Double(top.Top + SH + 2))
        if apex >= foot { apex = foot - 10 }
        if apex >= footY { apex = footY - 10 }
        let vy0: Double = -Math.Sqrt(2 * g * (foot - apex))
        let tt: Double = -vy0 / g + Math.Sqrt(2 * (footY - apex) / g)
        let vx0: Double = (tx - cx) / tt
        dir = vx0 >= 0 ? 1 : -1
        Jump(vx0, vy0)
    }

    // 挑一個附近的平台（視窗頂端或螢幕底）：回傳 {x, 頂端y, 是哪個視窗}
    func PickPlatform(_ minDx: Double, _ maxDx: Double) -> [Double]? {
        let cx = Cx, foot: Double = y + Double(SH)
        let opts = List<[Double]>()
        for p in w.Plats {
            if p.H == supH && Math.Abs(Double(p.Top) - foot) < 2 { continue }
            let span: Double = Double(Math.Max(0, p.Right - p.Left - SW))
            let tx: Double = Double(p.Left) + Double(SW) / 2.0 + rnd.NextDouble() * span
            let dx: Double = tx - cx, dy: Double = Double(p.Top) - foot
            if Math.Abs(dx) < minDx || Math.Abs(dx) > maxDx || dy < -600 * k { continue }
            opts.Add([tx, Double(p.Top)])
        }
        if supH != IntPtr.Zero {
            let wa = w.WA(cx, y)
            opts.Add([Clamp(cx + R(-400, 400) * k, Double(wa.Left + SW), Double(wa.Right - SW)), Double(wa.Bottom)])
        }
        if opts.Count == 0 { return nil }
        return opts[rnd.Next(opts.Count)]
    }

    @discardableResult
    func JumpToPlatform() -> Bool {
        if !Grounded() { return false }
        guard let o = PickPlatform(40 * k, 900 * k) else { return false }
        BallisticTo(o[0], o[1])
        if Is("po") { Say(L("jump"), 0.9) }
        else if rnd.NextDouble() < 0.3 { Say(L("jump"), 0.8) }
        return true
    }

    func Air(_ dt: Double) {
        let g: Double = 900 * k, prevFoot: Double = y + Double(SH)
        vy += g * dt; x += vx * dt; y += vy * dt
        var cx = Cx
        let midY: Double = y + Double(SH) / 2.0
        let wa = w.WA(cx, midY)
        if !w.Inside(x, midY) && x < Double(wa.Left) { x = Double(wa.Left); vx = -vx * 0.5 }
        if !w.Inside(x + Double(SW) - 1, midY) && x + Double(SW) > Double(wa.Right) { x = Double(wa.Right - SW); vx = -vx * 0.5 }
        cx = Cx
        if y < Double(wa.Top) { y = Double(wa.Top); if vy < 0 { vy = 0 } }
        if Math.Abs(vx) > 1 { dir = vx > 0 ? 1 : -1 }
        if vy > 1100 * k && (Is("po") || Is("stitch") || Is("laalaa")) { rolling = true } // 摔很快 → 滾
        if vy <= 0 { return }
        var best = Double(wa.Bottom); var bp: Plat? = nil
        for p in w.Plats {
            let pTop = Double(p.Top)
            if cx >= Double(p.Left) && cx <= Double(p.Right) && prevFoot <= pTop + 1 && y + Double(SH) >= pTop && pTop < best { best = pTop; bp = p }
        }
        if y + Double(SH) >= best {
            y = best - Double(SH)
            let landVx = vx
            lastLandVy = vy
            vx = 0; vy = 0
            if let bp = bp { SetSupport(bp) } else { supH = IntPtr.Zero }
            let wasRolling = rolling; rolling = false
            if nearMiss { nearMiss = false; Say(MissLine(), 1.8) }
            if Landed(wasRolling, landVx) { return }
            if sleepMode { GoSleep() }
            else if dizzyOnLand { dizzyOnLand = false; SetState("dizzy", 1.6) }
            else if fetching && w.BallOn { SetState("fetch", 15) }
            else if afterLand != "" { LandAction() }
            else if InScene && w.TubbyLineup { SetState("idle", 30) }   // 天線寶寶串場：跳一下落地就站好，不要走掉
            else { SetState("walk", R(2, 5)) }
        }
    }

    func SetSupport(_ p: Plat) { supH = p.H; supL = p.Left; supR = p.Right; supWinL = p.WinLeft }

    // 站著的那個視窗被拖動 → 跟著走
    func FollowFast() {
        if supH == IntPtr.Zero || !Grounded() { return }
        var r = W.RECT()
        if !W.IsWindowVisible(supH) || W.IsIconic(supH) || !W.Rect(supH, &r) { Jump(0, 0); Say(Is("hangyodon") ? "哇！地板游走了！" : "哇！地板不見了", 1.2); return }
        let dl = r.L - supWinL
        if dl != 0 { x += Double(dl); supL += dl; supR += dl; supWinL = r.L }
        y = Double(r.T - SH)
    }

    // World 掃描完視窗後：站的那段被蓋住 → 掉下來
    func CheckSupport() {
        if supH == IntPtr.Zero || !Grounded() { return }
        var best: Plat? = nil
        for p in w.Plats { if p.H == supH && Cx >= Double(p.Left - 2) && Cx <= Double(p.Right + 2) { best = p; break } }
        if let best = best { supL = best.Left; supR = best.Right } else { Jump(0, 0) }
    }

    // ---------- 第四面牆 ----------
    // 放大敲玻璃很搶眼，所以有全域冷卻（World.ZoomAllowed）；不能放大時改成原尺寸的小動作
    func Knock(_ text: String, _ kind: String) {
        if Out && Grounded() && state != "glass" && w.ZoomAllowed(kind) { StartGlass(text); return }
        if kind == "ambient" { Tap(text); return }
        NoZoom(text, kind == "high" || kind == "meeting" ? 6 : 3.5)
    }

    // 原尺寸：在玻璃上輕輕敲一下（小漣漪）
    func Tap(_ text: String) {
        if Out && Grounded() { poseKind = "tap"; SetState("pose", 1.5); gt = 0 }
        Say(text, 2.6)
    }

    // 不放大：朝滑鼠跳一下＋泡泡
    func NoZoom(_ text: String, _ sec: Double) {
        if Out && Grounded() {
            let dx: Double = Double(Cursor.Position.X) - Cx
            dir = dx >= 0 ? 1 : -1
            if Math.Abs(dx) > 40 * k && Math.Abs(dx) < 500 * k && supH == IntPtr.Zero { Jump(Clamp(dx * 0.8, -320 * k, 320 * k), -300 * k) }
            else { Jump(0, -280 * k) }
        }
        Say(text, sec)
    }

    // ---------- 第四面牆：放大敲螢幕 ----------
    func StartGlass(_ text: String) {
        if !Grounded() || !Out { Say(text, 2.5); return }
        let wa = w.WA(Cx, y + Double(SH) / 2.0)
        if y + Double(SH) - 3.2 * Double(SH) < Double(wa.Top) { Say(text, 2.5); return }
        afterGlass = text; gt = 0; sc = 1; knock = 0
        SetState("glass", 99)
    }

    func Glass(_ dt: Double) {
        let prev = gt
        gt += dt
        let cp = Cursor.Position
        dir = Double(cp.X) >= Cx ? 1 : -1
        if gt < 0.5 { sc = 1 + 2 * Ease(gt / 0.5) }
        else if gt < 3.4 {
            sc = 3
            if prev < 0.55 && gt >= 0.55 { if bubble == afterGlass && Bt > 0 { Bt = Math.Max(Bt, 2.8) } else { Say(afterGlass, 2.8) } }
            if Math.Floor(gt * 2.2) != Math.Floor(prev * 2.2) { knock = 0.12 }
        }
        else if gt < 3.9 { sc = 3 - 2 * Ease((gt - 3.4) / 0.5) }
        else { sc = 1; SetState("idle", 1.2) }
        if knock > 0 { knock -= dt }
    }

    // ---------- 拖曳 ----------
    func MouseDown(_ e: MouseEventArgs) {
        // 有通知在等你點：一按下去就算（就算他在走路、在敲玻璃）
        if e.Button == MouseButtons.Left && w.NoticeClicked(self) { dragging = false; return }
        if e.Button != MouseButtons.Left || state == "glass" || state == "peek" || state == "stowfly" || state == "enter" || state == "exit" || state == "fling" { return }
        let p = Cursor.Position
        let pX = Double(p.X), pY = Double(p.Y)
        let left: Double = x - 6 - Double(9 * S), right: Double = x + Double(SW) + 6 + Double(9 * S)
        let top: Double = y - 6 - Double((P.TopRows + 3) * S), bottom: Double = y + Double(SH) + 6
        if pX < left || pX > right || pY < top || pY > bottom { return }
        dragging = true; dragSaid = false; dragStart = p; dragMoved = 0
        grabDx = pX - x; grabDy = pY - y
        lastMx = pX; lastMy = pY; lastMt = w.Now; dvx = 0; dvy = 0
    }

    func MouseUp(_ e: MouseEventArgs) {
        if e.Button == MouseButtons.Left && dragging { EndDrag() }
        else if e.Button == MouseButtons.Right && Menu != nil { w.FillMenu(self, Menu); w.ShowMenu(Menu) }
    }

    var Dragging: Bool { return dragging && state == "drag" }

    func DragUpdate(_ now: Double, _ dt: Double) -> Bool {
        if (Control.MouseButtons & MouseButtons.Left) == MouseButtons.None { EndDrag(); return false }
        let p = Cursor.Position
        let pX = Double(p.X), pY = Double(p.Y)
        let mdt = now - lastMt
        if mdt > 0.001 {
            let ivx: Double = (pX - lastMx) / mdt, ivy: Double = (pY - lastMy) / mdt
            dvx = dvx * 0.5 + 0.5 * ivx; dvy = dvy * 0.5 + 0.5 * ivy
        }
        lastMx = pX; lastMy = pY; lastMt = now
        dragMoved = Math.Max(dragMoved, Double(Math.Abs(p.X - dragStart.X) + Math.Abs(p.Y - dragStart.Y)))
        if dragMoved <= 6 { return false }
        if state != "drag" { state = "drag"; supH = IntPtr.Zero; sleepMode = false; sc = 1; if InScene { w.AbortScene() } }
        x = pX - grabDx; y = pY - grabDy
        anim += dt
        if Bt > 0 { Bt -= dt }
        if !dragSaid { dragSaid = true; Say(L("drag"), 1.5) }
        return true
    }

    func EndDrag() {
        dragging = false
        if state != "drag" { Clicked(); return }
        let lim: Double = 2200 * k
        Throw(Clamp(dvx, -lim, lim), Clamp(dvy, -lim, lim))
    }

    // ================= 丟回櫃子（像投籃）=================

    // 測試用：在 (px,py) 放手、給一個速度
    func SimThrow(_ px: Double, _ py: Double, _ tvx: Double, _ tvy: Double) {
        if !Out { return }
        dragging = false
        x = px - Double(SW) / 2.0; y = py - Double(SH) / 2.0
        Throw(tvx, tvy)
    }

    func Throw(_ tvx: Double, _ tvy: Double) {
        let zone = w.ShelfZone(SW, SH)
        let cx = Cx, cy: Double = y + Double(SH) / 2.0, speed: Double = Math.Abs(tvx) + Math.Abs(tvy)
        nearMiss = false
        // 在櫃子附近放手：直接收進去（有甩的話算投進）
        if zone.Contains(CInt(cx), CInt(cy)) {
            if speed > 700 * k { StartFling(tvx * 0.5, tvy * 0.5) } else { StowToShelf(true) }
            return
        }
        // 模擬飛行路線：有穿過櫃子（加大範圍）就被吸進去
        var px = cx, py = cy, pvx = tvx, pvy = tvy
        let g: Double = 900 * k, step: Double = 1 / 60.0
        var best = Double.greatestFiniteMagnitude
        var hit = false
        let zL = Double(zone.Left), zR = Double(zone.Right), zT = Double(zone.Top), zB = Double(zone.Bottom)
        var i = 0
        while i < 240 {
            pvy += g * step; px += pvx * step; py += pvy * step
            if zone.Contains(CInt(px), CInt(py)) { hit = true; break }
            let dx: Double = Math.Max(0, Math.Max(zL - px, px - zR)), dy: Double = Math.Max(0, Math.Max(zT - py, py - zB))
            best = Math.Min(best, Math.Sqrt(dx * dx + dy * dy))
            if !w.Inside(px, Math.Min(py, cy)) && !w.Inside(px, py) { break }   // 飛出所有螢幕
            i += 1
        }
        if hit && speed > 300 * k { StartFling(tvx, tvy); return }
        nearMiss = speed > 600 * k && best < Double(SW) * 2.5
        Jump(tvx, tvy)
        if speed > 900 * k {
            Say(L("throw"), 0.9)
            if Is("po") || Is("stitch") || Is("laalaa") { rolling = true }
        }
    }

    // 照丟出去的速度飛，越飛越被自己的格子吸過去
    func StartFling(_ tvx: Double, _ tvy: Double) {
        var tfx: Double = 0, tfy: Double = 0; var ps = 0
        w.ShelfFoot(self, &tfx, &tfy, &ps)
        shelfPs = ps
        fx1 = tfx - Double(SW) / 2.0; fy1 = tfy - Double(SH)
        vx = tvx; vy = tvy; flyT = 0
        supH = IntPtr.Zero; sc = 1; fetching = false; InScene = false
        rolling = Is("po") || Is("stitch") || Is("laalaa")
        SetState("fling", 99)
    }

    func Fling(_ dt: Double) {
        flyT += dt
        let f: Double = Math.Min(1, flyT / 0.7)
        let ax2: Double = (fx1 - x) * 26 * f * f - vx * 9.5 * f
        let ay2a: Double = (fy1 - y) * 26 * f * f - vy * 9.5 * f
        let ay2: Double = ay2a + 900 * k * (1 - f)
        vx += ax2 * dt; vy += ay2 * dt; x += vx * dt; y += vy * dt
        if Math.Abs(vx) > 5 { dir = vx > 0 ? 1 : -1 }
        let ddx: Double = fx1 - x, ddy: Double = fy1 - y
        let d: Double = Math.Sqrt(ddx * ddx + ddy * ddy)
        if (d < 10 * k && flyT > 0.25) || flyT > 2.2 {
            x = fx1; y = fy1; rolling = false
            GoalCheer()
            gt = 0; SetState("enter", 99)
        }
    }

    func GoalCheer() {
        let line: String
        switch P.Id {
        case "po": line = "進球！🏀 再來一次！"
        case "stitch": line = "嘻嘻嘻～進球！🏀"
        case "hangyodon": line = "英雄……降落成功 🏀"
        case "tinky": line = "進球！🏀 丁丁回家家～"
        case "dipsy": line = "進球。🏀 帽子還在，酷。"
        case "laalaa": line = "進球！🏀 啦啦啦～"
        default: line = "進球！🏀 Thwip!"
        }
        Say(line, 2.4)
        Burst(14)
        w.GoalCheer(self)
    }

    // 別人投進了：小小歡呼
    func Cheer() {
        if !Out || InScene { return }
        let line: String
        switch P.Id {
        case "po": line = "Eh-oh! 進了！"
        case "stitch": line = "ih-ih! 嘻嘻嘻"
        case "hangyodon": line = "好、好厲害！"
        case "tinky": line = "好棒棒！大抱抱！"
        case "dipsy": line = "酷！"
        case "laalaa": line = "啦啦～進了！"
        default: line = "好球！"
        }
        Say(line, 1.4)
        Mark(0)
        if Grounded() && state != "sleep" { Jump(0, -220 * k) }
    }

    func MissLine() -> String {
        switch P.Id {
        case "po": return "差一點點！再來一次！"
        case "stitch": return "ih! 沒進！嘻嘻"
        case "hangyodon": return "偏、偏了…英雄也會失手"
        case "tinky": return "哎喲，差一點點…"
        case "dipsy": return "沒進…但帽子很帥"
        case "laalaa": return "差一點！再來一次！"
        default: break
        }
        return "差一點！再一次？"
    }

    // ================= 公仔櫃：回櫃子／出來 =================
    // 回櫃子：飛到自己那格（每個角色飛法不同），到了縮小、櫃子接手畫
    func StowToShelf(_ say: Bool) {
        if !Out { return }
        var tfx: Double = 0, tfy: Double = 0; var ps = 0
        w.ShelfFoot(self, &tfx, &tfy, &ps)
        shelfPs = ps
        if say { Say(L("shelf_in"), 2.2) }
        fetching = false; sc = 1; rolling = false; InScene = false
        fx0 = x; fy0 = y; fx1 = tfx - Double(SW) / 2.0; fy1 = tfy - Double(SH)
        let ddx: Double = fx1 - fx0, ddy: Double = fy1 - fy0
        let d: Double = Math.Sqrt(ddx * ddx + ddy * ddy)
        let flySpeed: Double = Is("hangyodon") ? 560 * k : 900 * k
        flyDur = Clamp(d / flySpeed, 0.35, 1.6)
        flyArc = Math.Min(160 * k, 40 * k + d * 0.25)
        flyT = 0; supH = IntPtr.Zero
        SetState("stowfly", 99)
    }

    func StowFly(_ dt: Double) {
        flyT += dt
        let f: Double = Math.Min(1, flyT / flyDur), e: Double = Is("hangyodon") ? Ease(f) : f
        if Is("hangyodon") && rnd.NextDouble() < 0.25 { Mark(5) }
        x = fx0 + (fx1 - fx0) * e
        let arc: Double = Math.Sin(Math.PI * f) * flyArc
        y = fy0 + (fy1 - fy0) * e - arc
        dir = fx1 >= fx0 ? 1 : -1
        if f >= 1 { x = fx1; y = fy1; gt = 0; SetState("enter", 99) }
    }

    func Enter(_ dt: Double) {
        gt += dt
        let target: Double = Double(shelfPs) / Double(S)
        sc = 1 + (target - 1) * Ease(gt / 0.35)
        if gt >= 0.35 { sc = 1; Out = false; HideForms(); state = "shelf"; ShelfFx = 0; w.PetStowed(self) }
    }

    // 從格子裡出來：先在格子裡變大，再跳到桌面
    func ComeOut(_ say: Bool) {
        EnsureForms()
        var tfx: Double = 0, tfy: Double = 0; var ps = 0
        w.ShelfFoot(self, &tfx, &tfy, &ps)
        shelfPs = ps
        x = tfx - Double(SW) / 2.0; y = tfy - Double(SH)
        sc = Double(ps) / Double(S); gt = 0
        Out = true; InScene = false; dragging = false; sleepMode = false
        SetState("exit", 99)
        if say { Say(L("shelf_out"), 1.8) }
    }

    func Exit(_ dt: Double) {
        gt += dt
        let from: Double = Double(shelfPs) / Double(S)
        sc = from + (1 - from) * Ease(gt / 0.3)
        if gt < 0.3 { return }
        sc = 1
        let wa = w.WA(Cx, y + Double(SH))
        let tx: Double = Clamp(Cx - R(140, 360) * k, Double(wa.Left + SW), Double(wa.Right - SW))
        if Is("hangyodon") { StartSwim(tx, Double(wa.Bottom), false); return }
        BallisticTo(tx, Double(wa.Bottom))
        if Is("stitch") { rolling = true }
        if Is("tinky") && rnd.NextDouble() < 0.3 { afterLand = "plop" }          // 丁丁跳出來常常跌坐
        else if Is("laalaa") && rnd.NextDouble() < 0.4 { afterLand = "twirl" }   // 拉拉落地轉一圈
        else if Is("dipsy") && rnd.NextDouble() < 0.4 { afterLand = "hattip" }   // 迪西落地扶帽子
    }

    // ---------- 走到指定位置（串場、大合照用）----------
    func GoTo(_ dt: Double) {
        if Math.Abs(seekX - Cx) < 4 { x = seekX - Double(SW) / 2.0; SetState("idle", InScene ? 30 : 1); return }
        dir = seekX > Cx ? 1 : -1
        if MoveOnGround(dt, Math.Max(P.Speed, 60) * k * gotoSpeed) { return }
        if (dir > 0 && Cx > seekX) || (dir < 0 && Cx < seekX) { x = seekX - Double(SW) / 2.0 }
        if t < 0 { SetState("idle", InScene ? 30 : 1) }
    }

    // ---------- 躲到別人後面（小波怕錯誤）----------
    func HideBehindPet(_ other: Pet) {
        if !Grounded() { return }
        let side: Double = other.Cx > Cx ? 1 : -1
        hideX = other.Cx + side * Double(SW) * 0.45
        SetState("hide", 4)
    }
    func HideBehind(_ dt: Double) {
        if Math.Abs(hideX - Cx) > 4 { dir = hideX > Cx ? 1 : -1; if MoveOnGround(dt, 110 * k) { return } }
        if t < 0 { SetState("idle", 1) }
    }

    // ================= 球 =================
    func BallStarted() {
        if !Out || InScene { return }
        fetching = true
        WakeIfSleep()
        if Grounded() && state != "hug" { SetState("fetch", 15) }
    }

    func Fetch(_ dt: Double) {
        if !w.BallOn || !fetching { fetching = false; SetState("idle", 1); return }
        if w.Holder != nil { SetState("idle", 0.5); return }
        let r: Double = w.BallR(), dxb: Double = w.Bx - Cx, foot: Double = y + Double(SH)
        let resting = w.Bvy == 0 && Math.Abs(w.Bvx) < 30 * k
        let sameLevel = Math.Abs(w.By + r - foot) < 40 * k
        if resting && !sameLevel { BallisticTo(w.Bx, w.By + r); return }
        let base: Double = P.Tubby ? (Is("tinky") ? 90 : (Is("laalaa") ? 150 : 125)) : (Is("hangyodon") ? 70 : (Is("stitch") ? 170 : (Is("po") ? 150 : 125)))
        let sp: Double = base * k
        if Math.Abs(dxb) > 6 { dir = dxb > 0 ? 1 : -1; if MoveOnGround(dt, sp) { return } }
        else if w.By < y && w.Bvy > 0 && w.By > y - 160 * k { Jump(0, -380 * k); return }
        if t < 0 { fetching = false; SetState("idle", 1); Say(L("ball_far"), 1.6) }
    }

    // 球碰到他（World 判斷）：回傳 true＝處理掉了
    @discardableResult
    func TouchBall() -> Bool {
        if !fetching || state == "drag" || !Out { return false }
        fetching = false
        if ballXp < 20 { ballXp += 2; AddXp(2) }
        Burst(6)
        switch P.Id {
        case "po": PoBall(); return true
        case "stitch": StitchBall(); return true
        case "hangyodon": HangyodonBall(); return true
        case "tinky": TinkyBall(); return true
        case "dipsy": DipsyBall(); return true
        case "laalaa": LaaLaaBall(); return true
        default: break
        }
        // Spidey：踢回滑鼠的方向（多人時用絲接住）
        if w.OutCount() > 1 && rnd.NextDouble() < 0.6 { WebCatch(); return true }
        Say(L("ball_catch"), 1.8)
        KickBallToCursor(1.0)
        if Grounded() { SetState("kick", 0.5) }
        return true
    }

    func KickBallToCursor(_ power: Double) {
        let c = Cursor.Position
        let kvx: Double = (Double(c.X) - w.Bx) * 1.1 * power
        w.Bvx = Clamp(kvx, -900 * k, 900 * k)
        w.Bvy = -R(450, 650) * k * power
        w.By = Math.Min(w.By, y - 4 * k)
        w.BallIdle = 0; w.CatchCd = 1.0
    }

    // ================= 外部事件 =================
    func OnSave(_ lead: Bool) {
        if saveXpCd <= 0 { saveXpCd = 120; AddXp(1) }
        WakeIfSleep()
        if lead { Say(L("save"), 2) }
        if Grounded() && (lead || rnd.NextDouble() < 0.3) { Jump(0, -300 * k) }
    }

    func OnErrors(_ n: Int, _ prev: Int, _ hideFrom: Pet?) {
        WakeIfSleep()
        if n > prev {
            sense = Is("spidey") ? 2.8 : 0
            let line = L("errors", "n", n.ToString())
            if Is("hangyodon") && Grounded() { capeT = 0; SetState("capetrip", 2.6) }
            else if Is("stitch") && Grounded() { Jump(0, -360 * k); Mark(1) }
            else if Is("po") && hideFrom != nil && Grounded() { HideBehindPet(hideFrom!) }
            else if Is("tinky") && Grounded() { Plop(nil) }
            else if Is("dipsy") && Grounded() { poseKind = "hatdown"; SetState("pose", 2.6) }
            else if Is("laalaa") && hideFrom != nil && Grounded() { HideBehindPet(hideFrom!) }
            else if state == "walk" { SetState("idle", 3) }
            Say(line, 3, true)
        }
        else if n == 0 { AddXp(2); Hug(L("errors_ok"), 2.6) }
    }

    func OnTyping() {
        if !Grounded() || state == "hug" || state == "sleep" || InScene || Quiet { return }
        if Is("stitch") { SetState("elvis", 4) }
        else if Is("laalaa") { SetState("dance", 4); Mark(0); Mark(0) }
        else { SetState("dance", 4) }
        Say(L("typing"), 2.5)
    }

    func React() {
        if !Out || InScene { return }
        WakeIfSleep()
        if Grounded() { Jump(0, -240 * k) }
        Mark(1)
        Say(L("react"), 1.4)
    }

    // 卡住提醒（文字已組好）
    func Alert(_ text: String) {
        WakeIfSleep()
        if Is("spidey") { sense = 2.8 }
        Knock(text, "high")
        Say(text, 5, true)
        bubblePri = 2
        stuckLine = text; stuckRepeat = 3.5
    }
    func ClearAlert() { stuckLine = nil }

    func SystemIdle(_ idle: Bool) {
        if idle { sleepMode = true; if Out && Grounded() && state != "hug" && state != "glass" { GoSleep() } }
        else {
            let was = state == "sleep"
            WakeIfSleep()
            if was && Out { Knock(L("welcome"), "ambient") }
        }
    }

    func Rest(_ restMin: Double) {
        WakeIfSleep()
        Hug(L("rest", "n", restMin.ToString()), 8)
    }

    func NightChanged(_ d: Bool) {
        if !Out { return }
        if d { if Is("spidey") { sense = 2.5 }; NoZoom(L("night_on"), 3.5) }
        else { Say(L("night_off"), 3) }
    }

    func Greeting() -> String {
        let sl = SeasonLine()
        if sl != nil && w.SeasonNow != "friday" { return sl! }
        if Night { return L("g_d") }
        let h = DateTime.Now.Hour
        if h >= 23 || h < 5 { return L("g_late") }
        if h < 11 { return L("g_morning") }
        if h < 14 { return L("g_noon") }
        if h >= 18 { return L("g_evening") }
        return L("g_day")
    }

    func SeasonLine() -> String? {
        if w.SeasonNow == "" { return nil }
        let s = L("s_" + w.SeasonNow)
        return s == "" ? nil : s
    }

    func LateLine() -> String? {
        let h = DateTime.Now.Hour
        if Night { return h >= 21 || h < 5 ? L("late_dd") : L("late_d") }
        if h >= 23 || h < 5 { return L("late23") }
        if h == 12 { return L("late12") }
        if h == 15 { return L("late15") }
        return nil
    }

    func AppLine(_ h: IntPtr) -> String {
        var name = ""
        // mac: Windows 用 Process.GetProcessById(pid).ProcessName；這裡用 NSRunningApplication，
        // 再把常見 App 的 bundle id 對應回 Windows 的行程名（code／chrome／excel…）
        var pid = 0
        _ = W.GetWindowThreadProcessId(h, &pid)
        if pid > 0, let app = NSRunningApplication(processIdentifier: pid_t(pid)) {
            let bid = (app.bundleIdentifier ?? "").lowercased()
            if bid.hasPrefix("com.microsoft.vscode") || bid.hasPrefix("com.visualstudio.code") { name = "code" }
            else if bid.hasPrefix("com.google.chrome") { name = "chrome" }
            else if bid.hasPrefix("com.microsoft.edgemac") { name = "msedge" }
            else if bid.hasPrefix("org.mozilla.firefox") { name = "firefox" }
            else if bid == "com.apple.safari" || bid.hasPrefix("company.thebrowser") { name = "chrome" }   // mac: Safari／Arc 當瀏覽器
            else if bid == "com.microsoft.excel" { name = "excel" }
            else if bid == "com.microsoft.powerpoint" { name = "powerpnt" }
            else if bid == "com.microsoft.word" { name = "winword" }
            else if bid.hasPrefix("com.microsoft.teams") { name = "teams" }
            else if bid == "com.tinyspeck.slackmacgap" { name = "slack" }
            else if bid == "jp.naver.line.mac" { name = "line" }
            else if bid == "com.apple.finder" { name = "explorer" }
            else { name = (app.localizedName ?? "").lowercased() }
        }
        let chat = name.Contains("teams") || name == "slack" || name == "line"
        if Night {
            if name == "code" { return L("app_code_d") }
            if chat { return L("app_chat_d") }
            if name == "excel" || name == "powerpnt" || name == "winword" { return L("app_office_d") }
            return L("app_other_d")
        }
        if name == "chrome" || name == "msedge" || name == "firefox" { return L("app_browser") }
        if name == "code" { return L("app_code") }
        if name == "excel" { return L("app_excel") }
        if name == "powerpnt" { return L("app_ppt") }
        if name == "winword" { return L("app_word") }
        if chat { return L("app_chat") }
        if name == "explorer" { return L("app_files") }
        return L("app_other")
    }

    // ---------- 選單／指令 ----------
    func Act(_ a: String) {
        if a != "sleep" { WakeIfSleep() }
        if !Out && a != "bond" && a != "hi" { Say(Pick(["我在櫃子裡，先放我出去～", "點一下櫃子裡的我，我就出來囉"]), 1.8); return }
        switch a {
        case "hi":
            if Out && Grounded() {
                if Is("po") { SetState("wave", 1.6) }
                else if Is("hangyodon") { poseKind = "hero"; SetState("pose", 1.4) }
                else if Is("dipsy") { poseKind = "hattip"; SetState("pose", 1.6) }
                else if P.Tubby { SetState("wave", 1.6) }
                else { Jump(0, -260 * k) }
            }
            Say(L("hi"), 2.4)
        case "hug": Hug(L("hugs"), 2.4)
        case "pat": Pat()
        case "bond": ShowBond()
        case "knock": Knock(L("knock"), "user")
        case "jump": if !JumpToPlatform() { Say(L("nojump"), 1.6) }
        case "sleep": if Grounded() { GoSleep(); t = 8; Say(L("sleep"), 1.2) }
        case "sig": Signature()
        case "celebrate": Celebrate("", true)
        default: ActSpecial(a)
        }
    }

    // 慶祝（上版 tag／Codex、Claude 做完）：每個角色自己的方式
    func Celebrate(_ env: String, _ lead: Bool) {
        if Quiet && w.quietOn { return }
        WakeIfSleep()
        if !Out { if lead { Say(env == "prod" ? L("tag_prod") : (env == "dev" ? L("tag_dev") : L("tag")), 4) }; return }
        let line = Night ? L("tag") : (env == "prod" ? L("tag_prod") : (env == "dev" ? L("tag_dev") : L("tag")))
        CelebrateWith(line, lead)
        AddXp(lead ? 5 : 2)
    }

    func CelebrateWith(_ line: String, _ lead: Bool) {
        switch P.Id {
        case "po": HomeRun(line, lead)
        case "stitch": if Grounded() { SetState("elvis", 4.5) }; Say(line, 4); for _ in 0..<3 { Mark(0) }
        case "hangyodon": if Grounded() { poseKind = "hero"; SetState("pose", 3.4) }; Say(line, 4); for _ in 0..<6 { Mark(5) }; Burst(6)
        case "tinky": if Grounded() { TinkyBag("star", true) }; Say(line, 4); Burst(10)
        case "dipsy": if Grounded() { HatToss(true) }; Say(line, 4); Burst(8)
        case "laalaa": if Grounded() { SetState("twirl", 2.4) }; Say(line, 4); for _ in 0..<4 { Mark(0) }; Burst(8)
        default:
            if lead { w.Fireworks(w.WA(Cx, y + Double(SH) / 2.0), 10, -1) }
            if Grounded() { SetState("dance", 3.5) }
            Say(line, 4); Burst(10)
        }
        AddHeart(); AddHeart()
    }

    // Codex／Claude 做完：Spidey 敲玻璃；小波全壘打；其他人照自己的慶祝
    func Done(_ src: String, _ lead: Bool) {
        WakeIfSleep()
        who = src
        let text = L("done", "who", src)
        if !lead { React(); return }
        if !Out { Say(text, 4); return }
        if Is("spidey") { NoZoom(text, 4); Burst(8) }
        else { CelebrateWith(text, true) }
        AddXp(1)
    }

    func Wait(_ src: String) {
        WakeIfSleep()
        let text = L("wait", "who", src)
        NoZoom(text, 3)
    }

    func Unstuck(_ src: String) {
        stuckLine = nil
        Say(L("unstuck", "who", src), 2)
    }

    func LateTick() {
        if lateCd > 0 || !Out || !Free() || Quiet { return }
        guard let l = LateLine() else { return }
        lateCd = Night ? 240 : 600
        Say(l, 3.5); SetState("idle", 3.5)
    }
}

// ===== 31_pet_b.swift =====
// C# 2697–3980：Pet partials — 角色專屬狀態、Spidey／小波／史迪仔／人魚漢頓的招牌動作、天線寶寶
import Foundation


extension Pet {
    // 角色專屬狀態：回傳 true＝處理掉了
    func StepSpecial(_ dt: Double, _ wa: Rectangle) -> Bool {
        if HoldToast && rnd.NextDouble() < dt * 2.5 && notes.Count < 10 { notes.Add(Arr<Double>([R(-8, 8) * k, 0, 7])) }   // 吐司屑屑
        if P.Tubby && TubbyStep(dt) { return true }
        switch state {
        case "plop":
            sT += dt
            if t < 0 { SetState("idle", InScene ? 30 : 1) }
            return true
        // ---- Spidey ----
        case "swing": Swing(dt, wa); return true
        case "hang": Hang(dt, wa); return true
        case "climb": Climb(dt, wa); return true
        case "shoot": Shoot(dt); return true
        case "zip": Zip(dt); return true
        case "peek": Peek(dt, wa); return true
        case "webcatch":
            if t < 0 { w.ReleaseBall(Cx, y, 0, 0); KickBallToCursor(1.0); SetState("kick", 0.4) }
            return true
        case "sling": if t < 0 { SetState("idle", 1) }; return true
        // ---- 小波 ----
        case "spin":
            if t < 0 { SetState("idle", 1); Say(Pick(["再來一次！", "再來一次！嘻嘻"]), 1.4) }
            return true
        case "bat": Bat(dt); return true
        case "catch":
            if t < 0 { SetState("throw", 0.35) }
            return true
        case "throw":
            if t < 0.15 && w.Holder === self { w.ReleaseBall(Cx + Double(dir) * 6 * k, y + 6 * k, 0, 0); KickBallToCursor(1.0) }
            if t < 0 { SetState("idle", 1) }
            return true
        // ---- 史迪仔 ----
        case "wall": Wall(dt, wa); return true
        case "ceil": Ceil(dt); return true
        case "curl": Curl(dt); return true
        case "nudge": if t < 0 { SetState("idle", 1) }; return true
        case "chomp": Chomp(dt); return true
        case "elvis":
            if rnd.NextDouble() < dt * 3 { Mark(0) }
            if t < 0 { SetState("idle", 1); if !InScene { Say(Pick(["Thank you very much ♪", "嘻嘻嘻 ♪"]), 1.6) } }
            return true
        // ---- 人魚漢頓 ----
        case "swim": Swim(dt); return true
        case "header": if t < 0 { SetState(fetching ? "fetch" : "idle", fetching ? 15 : 1) }; return true
        case "capetrip":
            capeT += dt
            if capeT >= 1.4 && capeT - dt < 1.4 { tripT = 1.1; Say(Pick(["哎呀…（跌倒）", "嗚…英雄也會跌倒的", "我、我沒事！"]), 1.8) }
            if t < 0 { SetState("idle", 1) }
            return true
        default: break
        }
        return false
    }

    // 走到視窗邊緣：0＝照預設跳下去、1＝回頭、2＝換狀態了
    func EdgeOfWindow(_ right: Bool) -> Int {
        switch P.Id {
        case "spidey":
            if !goClimb && rnd.NextDouble() < 0.55 { dir = -dir; if rnd.NextDouble() < 0.3 { SpinWeb(supH, right) }; return 1 }
            return 0
        case "po":
            if rnd.NextDouble() < 0.4 { dir = -dir; return 1 }
            do {
                if let o = PickPlatform(60 * k, 700 * k), (o[0] > Cx) == (dir > 0) { BallisticTo(o[0], o[1]); Say(L("jump"), 0.9); return 2 }
            }
            x += Double(dir) * 4 * k; Jump(Double(dir) * P.Speed * k * 1.7, -280 * k); Say(L("jump"), 0.8)   // 小跳台飛出去
            return 2
        case "stitch":
            do {
                var wi: WinInfo! = nil
                if (goClimb || rnd.NextDouble() < 0.4) && w.Cands.ContainsKey(supH) { wi = w.Cands[supH] }
                if wi != nil && Math.Abs((right ? supR : supL) - (right ? wi.R : wi.L)) < 14
                    && wi.B < w.WA(Cx, y).Bottom - SH - 10
                { StartWallDown(wi, right); return 2 }
                if rnd.NextDouble() < 0.5 { dir = -dir; return 1 }
                return 0
            }
        case "hangyodon":
            if rnd.NextDouble() < 0.55 { dir = -dir; return 1 }
            do {
                if let o = PickPlatform(60 * k, 900 * k) { Say(L("jump"), 1.4); StartSwim(o[0], o[1], false); return 2 }
            }
            dir = -dir; return 1
        case "tinky":
            // 丁丁走路很小心：多半回頭；跳下去常常跌坐
            if rnd.NextDouble() < 0.7 { dir = -dir; if rnd.NextDouble() < 0.3 { Say("小心小心…", 1.2) }; return 1 }
            x += Double(dir) * 4 * k; Jump(Double(dir) * P.Speed * k * 2, -200 * k); afterLand = "plop"; Say("哎…", 0.8)
            return 2
        case "dipsy":
            if rnd.NextDouble() < 0.4 { dir = -dir; return 1 }
            x += Double(dir) * 4 * k; Jump(Double(dir) * 130 * k, -320 * k); afterLand = rnd.NextDouble() < 0.5 ? "hattip" : ""; Say("嘿！", 0.8)
            return 2
        case "laalaa":
            if rnd.NextDouble() < 0.35 { dir = -dir; return 1 }
            do {
                if let o = PickPlatform(60 * k, 700 * k), (o[0] > Cx) == (dir > 0) { BallisticTo(o[0], o[1]); afterLand = "twirl"; Say(L("jump"), 0.9); return 2 }
            }
            x += Double(dir) * 4 * k; Jump(Double(dir) * 150 * k, -360 * k); afterLand = "twirl"; Say(L("jump"), 0.8)
            return 2
        default: break
        }
        return 0
    }

    // 走到螢幕邊：true＝換狀態了（false＝回頭）
    func EdgeOfScreen() -> Bool {
        switch P.Id {
        case "spidey": if goClimb || rnd.NextDouble() < 0.35 { StartClimb(dir); return true }; return false
        case "stitch": if goClimb || rnd.NextDouble() < 0.3 { StartWallUp(dir); return true }; return false
        case "po": dir = -dir; Jump(Double(dir) * 60 * k, -220 * k); Say("嘟嘟～迴轉！", 0.9); return true
        default: break
        }
        return false
    }

    // 落地時的特別反應：true＝處理掉了
    func Landed(_ wasRolling: Bool, _ landVx: Double) -> Bool {
        if Is("stitch") && wasRolling { vx = landVx * 0.8; if Math.Abs(vx) < 60 * k { vx = Double(dir) * 120 * k }; SetState("curl", R(0.8, 1.4)); return true }
        if Is("po") && wasRolling && state != "spin" { SetState("dizzy", 0.8); Say(Pick(["轉圈圈～", "再來一次！"]), 1.2); return true }
        if Is("po") && state == "spin" { SetState("spin", 0.4); return true }
        if Is("tinky") && lastLandVy > 650 * k && state != "plop" { afterLand = ""; Plop(Pick(["哎喲！", "哎喲…屁股好痛", "哎喲！（跌坐）"])); return true }
        if Is("laalaa") && wasRolling { afterLand = ""; SetState("twirl", 0.9); Say(Pick(["轉圈圈～", "再來一次！"]), 1.2); return true }
        return false
    }

    func LandAction() {
        let a = afterLand; afterLand = ""
        switch a {
        case "wave": SetState("wave", 1.8); Say("Eh-oh!", 1.6)
        case "sniff": poseKind = "grin"; SetState("pose", 1.6); Mark(2); Say(Pick(["（聞聞）ih?", "嘻嘻，這個好玩", "ih-ih! 史迪仔的！"]), 1.6)
        case "bubbles": SetState("idle", 1.6); for _ in 0..<4 { Mark(5) }
        case "plop": Plop(Pick(["哎喲！", "哎喲！（跌坐）"]))
        case "hattip": poseKind = "hattip"; SetState("pose", 1.6); Say(Pick(["Eh-oh.", "嘿。", "（扶帽子）酷。"]), 1.4)
        case "twirl": SetState("twirl", 1.2); Say(Pick(["啦啦啦～", "轉圈圈～"]), 1.4)
        default: SetState("idle", R(1, 2))
        }
    }

    func Decide(_ wa: Rectangle) {
        goClimb = false
        if Bt > 0 && bubblePri > 0 { SetState("idle", R(1, 2)); return }   // 通知還在講：先別亂跑亂聊
        if fetching && w.BallOn { SetState("fetch", 15); return }
        let r = rnd.NextDouble(), cx = Cx
        if w.LunchState == "nap" && !Quiet { GoSleep(); t = 60; return }               // 吃飽睡午覺
        if HoldingFood() && !Quiet && r < 0.3 { SetState("idle", R(2, 4)); Say(LunchLine("talk"), 2.4); return }
        if Quiet {
            // 專注中：安靜發呆、偶爾慢慢走兩步
            if r < 0.75 { SetState("idle", R(5, 10)) } else { dir = rnd.NextDouble() < 0.5 ? -1 : 1; SetState("walk", R(1, 2.5)) }
            return
        }
        if w.OutCount() > 1 && rnd.NextDouble() < 0.12 && VisitFriend() { return }
        let lateOk: () -> Bool = { self.lateCd <= 0 && self.LateLine() != nil }
        switch P.Id {
        case "spidey":
            if r < 0.20 { SetState("idle", R(1.5, 4)) }
            else if r < 0.48 { if !JumpToPlatform() { Hop() } }
            else if r < 0.62 { if !ShootTo("swing") { Hop() } }
            else if r < 0.70 { _ = ShootTo("hang") }
            else if r < 0.75 { goClimb = true; dir = cx < Double(wa.Left + wa.Right) / 2.0 ? -1 : 1; SetState("walk", 30) }
            else if r < 0.80 { Hug(L("hugs"), 2.2) }
            else if r < (Night ? 0.84 : 0.815) { Knock(L("knock"), "ambient") }
            else if r < 0.86 && lateOk() { LateTick() }
            else if r < 0.90 && SeasonLine() != nil { Say(SeasonLine() ?? "", 3); SetState("idle", 3) }
            else { dir = rnd.NextDouble() < 0.5 ? -1 : 1; SetState("walk", R(3, 6)) }
        case "po":
            if r < 0.16 { SetState("idle", R(1.5, 3.5)) }
            else if r < 0.44 { dir = rnd.NextDouble() < 0.5 ? -1 : 1; SetState("walk", R(3, 7)); if rnd.NextDouble() < 0.25 { Say(Pick(["嘟嘟～", "騎車車～", "咻咻～"]), 1) } }
            else if r < 0.60 { if !JumpToPlatform() { Hop() } }
            else if r < 0.66 { SetState("wave", 1.6); Say(L("talk"), 2.2) }
            else if r < 0.71 { Hug(L("hugs"), 2.2) }
            else if r < (Night ? 0.76 : 0.74) { Knock(L("knock"), "ambient") }
            else if r < 0.79 { StartBat(false); Say("揮棒練習！嘿！", 1.2) }
            else if r < 0.83 && lateOk() { LateTick() }
            else if r < 0.87 && SeasonLine() != nil { Say(SeasonLine() ?? "", 3); SetState("idle", 3) }
            else if r < 0.92 { SetState("idle", 2.5); Say(L("talk"), 2.4) }
            else { dir = -dir; SetState("walk", R(3, 6)) }
        case "stitch":
            if r < 0.14 { SetState("idle", R(1.2, 3)) }
            else if r < 0.42 { dir = rnd.NextDouble() < 0.5 ? -1 : 1; SetState("walk", R(2, 5)) }
            else if r < 0.56 { if !JumpToPlatform() { Hop() } }
            else if r < 0.64 { Signature() }
            else if r < 0.70 { poseKind = "grin"; SetState("pose", 1.8); Say(Pick(["嘻嘻嘻…", "ih-ih-ih!", "（壞笑）"]), 1.6) }
            else if r < 0.74 { Hug(L("hugs"), 2.2) }
            else if r < (Night ? 0.80 : 0.78) { Knock(L("knock"), "ambient") }
            else if r < 0.82 { SetState("elvis", 3.5); Say(Night ? "♪ 呼啊～" : "♪ Aloha～", 1.6) }
            else if r < 0.85 && lateOk() { LateTick() }
            else if r < 0.88 && SeasonLine() != nil { Say(SeasonLine() ?? "", 3); SetState("idle", 3) }
            else if r < 0.93 { SetState("idle", 2); Say(L("talk"), 2.4) }
            else { dir = -dir; SetState("walk", R(2, 4)) }
        case "hangyodon":
            if r < 0.20 { SetState("idle", R(2, 4)); if rnd.NextDouble() < 0.4 { for _ in 0..<3 { Mark(5) } } }
            else if r < 0.46 { dir = rnd.NextDouble() < 0.5 ? -1 : 1; SetState("walk", R(3, 6)) }
            else if r < 0.58 { if let o = PickPlatform(60 * k, 900 * k) { StartSwim(o[0], o[1], false); Say(L("jump"), 1.2) } else { Hop() } }
            else if r < 0.64 { SetState("idle", 2.8); Say(L("pats"), 2.4); jokeT = 2.6 }
            else if r < 0.69 { Hug(L("hugs"), 2.2) }
            else if r < (Night ? 0.75 : 0.73) { Knock(L("knock"), "ambient") }
            else if r < 0.77 { poseKind = "hero"; SetState("pose", 1.8); Say(Pick(["總有一天我會當上英雄！", "（擺英雄姿勢）帥嗎？", "英雄漢頓…還在練習中"]), 2) }
            else if r < 0.80 { GoSleep(); t = R(5, 9); Say(L("sleep"), 1.4) }
            else if r < 0.84 && lateOk() { LateTick() }
            else if r < 0.87 && SeasonLine() != nil { Say(SeasonLine() ?? "", 3); SetState("idle", 3) }
            else if r < 0.93 { SetState("idle", 2.5); Say(L("talk"), 2.6) }
            else { dir = -dir; SetState("walk", R(3, 6)) }
        case "tinky":   // 慢慢走、提著魔法袋、偶爾跌坐、喜歡跳舞
            if r < 0.22 { SetState("idle", R(2, 4.5)) }
            else if r < 0.48 { dir = rnd.NextDouble() < 0.5 ? -1 : 1; SetState("walk", R(3, 7)); if rnd.NextDouble() < 0.2 { Say(Pick(["慢慢走～", "提著袋袋去散步～"]), 1.2) } }
            else if r < 0.54 { if !JumpToPlatform() { Hop() } }
            else if r < 0.63 { TinkyBag(nil, false) }
            else if r < 0.68 { SetState("dance", 3.2); Say(Pick(["丁丁跳舞～", "嘿～轉一圈～", "跳舞時間！"]), 1.6) }
            else if r < 0.72 { Plop(Pick(["哎喲！", "哎喲…（又跌倒了）"])) }
            else if r < 0.77 { Hug(L("hugs"), 2.2) }
            else if r < (Night ? 0.82 : 0.80) { Knock(L("knock"), "ambient") }
            else if r < 0.84 && lateOk() { LateTick() }
            else if r < 0.87 && SeasonLine() != nil { Say(SeasonLine() ?? "", 3); SetState("idle", 3) }
            else if r < 0.93 { SetState("idle", 2.5); Say(L("talk"), 2.4) }
            else { dir = -dir; SetState("walk", R(3, 6)) }
        case "dipsy":   // 酷酷的、跟著節奏走、帽子是他的招牌
            if r < 0.18 { SetState("idle", R(1.5, 3.5)) }
            else if r < 0.42 { dir = rnd.NextDouble() < 0.5 ? -1 : 1; SetState("walk", R(3, 6)) }
            else if r < 0.52 { if !JumpToPlatform() { Hop() } }
            else if r < 0.58 { poseKind = "hattip"; SetState("pose", 1.8); Say(L("talk"), 2.2) }
            else if r < 0.63 { HatToss(false) }
            else if r < 0.67 { poseKind = "hatwave"; SetState("pose", 2.2); Say(Pick(["（摘帽子揮一揮）Eh-oh!", "嘿～（揮帽子）"]), 1.8) }
            else if r < 0.73 { SetState("dance", 3.4); Say(Pick(["嘿～嘿～", "跟著節奏～", "迪西的舞步，酷。"]), 1.8) }
            else if r < 0.77 { Hug(L("hugs"), 2.2) }
            else if r < (Night ? 0.82 : 0.80) { Knock(L("knock"), "ambient") }
            else if r < 0.84 && lateOk() { LateTick() }
            else if r < 0.87 && SeasonLine() != nil { Say(SeasonLine() ?? "", 3); SetState("idle", 3) }
            else if r < 0.93 { SetState("idle", 2.5); Say(L("talk"), 2.4) }
            else { dir = -dir; SetState("walk", R(3, 6)) }
        case "laalaa":  // 蹦蹦跳跳、帶著球、愛唱歌轉圈圈
            if r < 0.14 { SetState("idle", R(1.2, 3)) }
            else if r < 0.40 { dir = rnd.NextDouble() < 0.5 ? -1 : 1; SetState("walk", R(3, 6)); if rnd.NextDouble() < 0.25 { Say(Pick(["啦～啦～", "蹦蹦跳～", "踢球球～"]), 1) } }
            else if r < 0.52 { if !JumpToPlatform() { Hop() } }
            else if r < 0.60 { Juggle() }
            else if r < 0.66 { SetState("twirl", 1.6); Say(Pick(["轉圈圈～", "啦啦啦～轉～"]), 1.4) }
            else if r < 0.72 { poseKind = "sing"; SetState("pose", 3.2); Say(Pick(["啦啦啦～♪", "啦～啦啦～啦～♪", "拉拉唱歌給你聽～♪"]), 2.6) }
            else if r < 0.76 { Hug(L("hugs"), 2.2) }
            else if r < (Night ? 0.81 : 0.79) { Knock(L("knock"), "ambient") }
            else if r < 0.83 && lateOk() { LateTick() }
            else if r < 0.86 && SeasonLine() != nil { Say(SeasonLine() ?? "", 3); SetState("idle", 3) }
            else if r < 0.93 { SetState("idle", 2.5); Say(L("talk"), 2.4) }
            else { dir = -dir; SetState("walk", R(3, 6)) }
        default:
            if r < 0.3 { SetState("idle", R(1.5, 4)) }
            else if r < 0.6 { if !JumpToPlatform() { Hop() } }
            else { dir = rnd.NextDouble() < 0.5 ? -1 : 1; SetState("walk", R(3, 6)) }
        }
    }

    // 去找另一隻（讓串場有機會發生）
    func VisitFriend() -> Bool {
        guard let o = w.RandomOther(self), o.Grounded(), o.state != "sleep" else { return false }
        let tx = o.Cx + Double(o.Cx > Cx ? -1 : 1) * Double(SW) * 1.1, foot = o.y + Double(o.SH)
        if o.supH == supH && Math.Abs(foot - (y + Double(SH))) < 3 {
            seekX = tx; dir = tx > Cx ? 1 : -1; SetState("walk", Math.Min(8, Math.Abs(tx - Cx) / (P.Speed * k) + 0.3))
            return true
        }
        if Math.Abs(tx - Cx) > 1000 * k { return false }
        if Is("hangyodon") { StartSwim(tx, foot, false) }
        else if Is("spidey") && rnd.NextDouble() < 0.5 { BallisticTo(tx, foot); Say("Thwip!", 0.8) }
        else { BallisticTo(tx, foot); if Is("po") { Say(L("jump"), 0.8) } }
        return true
    }

    // 右鍵選單的招牌動作
    func Signature() {
        if !Out { return }
        switch P.Id {
        case "spidey": if !ShootTo("swing") { Say("這裡太低了，甩不起來", 1.6) }
        case "po": if !JumpToPlatform() { Jump(Double(dir) * 200 * k, -520 * k); Say("咻～～", 1) } else { Say("咻～～再來一次！", 1.4) }
        case "stitch":
            if !Grounded() { break }
            goClimb = true
            if supH == IntPtr.Zero { let wa = w.WA(Cx, y); dir = Cx < Double(wa.Left + wa.Right) / 2.0 ? -1 : 1 }
            else { dir = Cx - Double(supL) < Double(supR) - Cx ? -1 : 1 }
            SetState("walk", 30); Say("ih-ih-ih! 爬牆！", 1.4)
        case "hangyodon":
            do {
                // 招牌：披上紅披風飛！（英雄夢）
                let o = PickPlatform(80 * k, 1100 * k)
                var tx: Double, ty: Double
                if let o = o { tx = o[0]; ty = o[1] }
                else {
                    let wa = w.WA(Cx, y + Double(SH) / 2.0)
                    tx = Pet.Clamp(Cx + (rnd.NextDouble() < 0.5 ? -1.0 : 1.0) * R(280, 520) * k, Double(wa.Left + SW), Double(wa.Right - SW))
                    ty = y + Double(SH)
                }
                StartSwim(tx, ty, true)
                flyArc = Math.Max(flyArc, 150 * k)
                Say(Pick(["英雄漢頓，出發！", "看我的披風！咻～", "這次一定要帥帥地飛！"]), 1.8)
            }
        case "tinky": TinkyBag(nil, false)
        case "dipsy": HatToss(false)
        case "laalaa": Juggle()
        default: break
        }
    }

    func ActSpecial(_ a: String) {
        switch a {
        case "swing": if Is("spidey") { if !ShootTo("swing") { Say("這裡太低了，甩不起來", 1.6) } } else { Signature() }
        case "hang": if Is("spidey") { if !ShootTo("hang") { Say("上面沒地方黏", 1.6) } }
        case "climb":
            if Is("spidey") && Grounded() { goClimb = true; let wa = w.WA(Cx, y); dir = Cx < Double(wa.Left + wa.Right) / 2.0 ? -1 : 1; SetState("walk", 30) }
            else if Is("stitch") { Signature() }
        case "ride": if Grounded() { dir = rnd.NextDouble() < 0.5 ? -1 : 1; SetState("walk", R(6, 10)); Say("騎車車兜風囉～嘟嘟！", 1.6) }
        case "bat": if Grounded() { StartBat(false); Say("揮棒！嘿！", 1.2) }
        case "uke": if Grounded() { SetState("elvis", 4); Say("♪ Aloha～", 1.6) }
        case "cape": Signature()
        case "joke": if Grounded() { SetState("idle", 2.8) }; Say(L("pats"), 2.4); jokeT = 2.6
        case "bubble": SetState("idle", 1.6); for _ in 0..<5 { Mark(5) }; Say("噗嚕噗嚕～", 1.2)
        // ---- 天線寶寶 ----
        case "bag": TinkyBag(nil, false)
        case "dance":
            if Grounded() { SetState("dance", 3.5); Say(Is("dipsy") ? "嘿～嘿～（帽子跟著晃）" : (Is("laalaa") ? "啦啦啦～跳舞！" : "丁丁跳舞～轉一圈～"), 1.8) }
        case "plop": if Grounded() { Plop("哎喲！") }
        case "hatwave": if Grounded() && Is("dipsy") && !hatLost { poseKind = "hatwave"; SetState("pose", 2.2); Say("Eh-oh!（揮帽子）", 1.8) }
        case "hattoss": HatToss(false)
        case "juggle": Juggle()
        case "sing": if Grounded() { poseKind = "sing"; SetState("pose", 3.2); Say("啦啦啦～啦啦～♪", 2.6) }
        case "twirl": if Grounded() { SetState("twirl", 1.6); Say("轉圈圈～啦啦啦！", 1.6) }
        default: break
        }
    }

    // 新視窗跳出來
    func ReactNewWindow(_ win: WinInfo) {
        if !Grounded() || sleepMode || state == "hug" || InScene || fetching { return }
        switch P.Id {
        case "spidey": if !ZipToWindow(win, L("newwin")) { Say("有新視窗！👀", 1.5) }
        default:
            let after: String = Is("po") || Is("tinky") ? "wave" : (Is("hangyodon") ? "bubbles" : (Is("dipsy") ? "hattip" : (Is("laalaa") ? "twirl" : "sniff")))
            if !GoToWindow(win, L("newwin"), after) { Say(L("newwin"), 1.5) }
        }
    }

    // 你切到哪個視窗，他常常跟過去
    @discardableResult
    func FollowWindow(_ win: WinInfo, _ text: String) -> Bool {
        if !Grounded() || sleepMode || state == "hug" || InScene || fetching { return false }
        if Is("spidey") { return ZipToWindow(win, text) }
        return GoToWindow(win, text, "")
    }

    func GoToWindow(_ win: WinInfo, _ text: String, _ after: String) -> Bool {
        var tx = 0.0, top = 0.0
        if !PlatEnd(win, &tx, &top) { return false }
        if supH == win.H { Say(text, 2); if after != "" { afterLand = after; LandAction() }; return true }
        Say(text, 2)
        afterLand = after
        if Is("hangyodon") { StartSwim(tx, top, false) }
        else { BallisticTo(tx, top) }
        return true
    }

    func PlatEnd(_ win: WinInfo, _ tx: inout Double, _ top: inout Double) -> Bool {
        tx = 0; top = 0
        var bestD = Double.greatestFiniteMagnitude; var found = false
        for p in w.Plats {
            if p.H != win.H { continue }
            let half = Double(SW) / 2.0
            let ends: [Double] = [Double(p.Left) + half + 2, Double(p.Right) - half - 2]
            for e in ends { let d = Math.Abs(e - Cx); if d < bestD { bestD = d; tx = e; top = Double(p.Top); found = true } }
        }
        return found && bestD < 1400 * k
    }

    // ================= Spidey：噴絲 =================
    func FindAnchor(_ vertical: Bool) -> [Double]? {
        let cx = Cx, hy = y
        let wa = w.WA(cx, y + Double(SH) / 2.0)
        let opts = List<[Double]>()
        for wi in w.Cands.Values {
            if Double(wi.B) > hy - 70 * k || wi.B < wa.Top + 10 { continue }
            var px: Double
            if vertical { if cx < Double(wi.L + 6) || cx > Double(wi.R - 6) { continue }; px = cx }
            else {
                px = Pet.Clamp(cx + Double(dir) * R(60, 220) * k, Double(wi.L + 6), Double(wi.R - 6))
                if Math.Abs(px - cx) > 300 * k { continue }
            }
            if !w.PointVisible(wi, px, Double(wi.B - 2)) { continue }
            opts.Add([px, Double(wi.B)])
        }
        if opts.Count > 0 && rnd.NextDouble() < 0.85 { return opts[rnd.Next(opts.Count)] }
        let dist = hy - Double(wa.Top)
        if dist < 90 * k { return nil }
        if vertical { return [cx, Double(wa.Top)] }
        return [Pet.Clamp(cx + Double(dir) * Math.Min(dist * 0.6, 260 * k), Double(wa.Left + 10), Double(wa.Right - 10)), Double(wa.Top)]
    }

    @discardableResult
    func ShootTo(_ mode: String) -> Bool {
        if !Grounded() { return false }
        guard let a = FindAnchor(mode == "hang") else { return false }
        ax = a[0]; ay = a[1]
        dir = ax >= Cx ? 1 : -1
        nextAct = mode; shootT = 0
        SetState("shoot", 1)
        Say("Thwip!", 0.8)
        return true
    }

    func Shoot(_ dt: Double) {
        shootT += dt
        if shootT < 0.18 { return }
        supH = IntPtr.Zero
        if nextAct == "swing" {
            let hx = Cx, hy = y
            let swa = w.WA(hx, y + Double(SH) / 2.0)
            let maxL = Double(swa.Bottom - SH) - ay - 24 * k
            let ddx = hx - ax, ddy = hy - ay
            ropeL = Math.Min(Math.Sqrt(ddx * ddx + ddy * ddy), maxL)
            if ropeL < 36 * k { Jump(Double(dir) * 60 * k, -300 * k); return }
            th = asin(Pet.Clamp((hx - ax) / ropeL, -0.95, 0.95))
            if Math.Abs(th) < 0.5 { th = 0.9 * (hx < ax ? -1.0 : 1.0) }
            om = 0
            reelT = 0.18; reelX = x; reelY = y
            SetState("swing", 3.2)
        }
        else if nextAct == "hang" {
            let wa = w.WA(ax, y + Double(SH) / 2.0)
            targetL = Math.Max(10.0, Math.Min(Double(wa.Height) * R(0.15, 0.4), Double(wa.Bottom - SH - 10) - ay))
            hangPhase = 0; ropeL = 0
            SetState("hang", 99)
        }
        else { SetState("zip", 3) }
    }

    func Swing(_ dt: Double, _ wa: Rectangle) {
        let acc: Double = (900 * k / ropeL) * Math.Sin(th) * dt
        om = (om - acc) * 0.997
        th += om * dt
        let hx = ax + ropeL * Math.Sin(th), hy = ay + ropeL * Math.Cos(th), floorY = Double(wa.Bottom - SH)
        x = hx - Double(SW) / 2.0; y = Math.Min(hy, floorY)
        if reelT > 0 {
            let f = Pet.Ease(1 - reelT / 0.18)
            x = reelX + (x - reelX) * f; y = reelY + (y - reelY) * f
            reelT -= dt
        }
        let vxs = ropeL * Math.Cos(th) * om
        if Math.Abs(vxs) > 5 { dir = vxs > 0 ? 1 : -1 }
        if t < 0 || hy > floorY + 1 { Jump(vxs * 0.8, -ropeL * Math.Sin(th) * om * 0.8); if rnd.NextDouble() < 0.4 { Say("呀呼～", 0.9) } }
    }

    func Hang(_ dt: Double, _ wa: Rectangle) {
        x = ax - Double(SW) / 2.0
        if hangPhase == 0 {
            y -= 700 * k * dt
            if y <= ay + 4 { y = ay + 4; hangPhase = 1; ropeL = 0; t = 5; Say("倒吊看世界～", 2) }
            return
        }
        ropeL = Math.Min(targetL, ropeL + 160 * k * dt)
        y = ay + 4 + ropeL + Math.Sin(anim * 2.4) * 4 * k
        if t < 0 { Jump(0, 0) }
    }

    func Zip(_ dt: Double) {
        let tx = ax - Double(SW) / 2.0, ty = ay - Double(SH)
        let dx = tx - x, dy = ty - y, d = Math.Sqrt(dx * dx + dy * dy), sp = 1100 * k * dt
        if dx != 0 { dir = dx > 0 ? 1 : -1 }
        if d > sp && t > 0 { x += dx / d * sp; y += dy / d * sp; return }
        x = tx; y = ty
        for p in w.Plats {
            if p.H == zipH && ax >= Double(p.Left - 2) && ax <= Double(p.Right + 2) && Math.Abs(Double(p.Top) - ay) < 3 {
                SetSupport(p)
                SetState("idle", 1.6)
                w.AddWeb(zipH, zipRight)
                Say("黏好了！", 1.4)
                return
            }
        }
        Jump(0, 0)
    }

    func Peek(_ dt: Double, _ wa: Rectangle) {
        let prev = gt
        gt += dt
        dir = -wallSide
        let hideXp = wallSide < 0 ? Double(wa.Left) - Double(SW) * 0.55 : Double(wa.Right) - Double(SW) * 0.45
        let inX = Double(wallSide < 0 ? wa.Left : wa.Right - SW)
        x = gt < 0.4 ? inX + (hideXp - inX) * Pet.Ease(gt / 0.4) : hideXp
        if prev <= 0.4 && gt > 0.4 { Say("躲貓貓～", 1.2) }
        if t < 0 { x = inX; Say("找到我了嗎？嘿嘿", 1.6); climbDir = 1; SetState("climb", 99) }
    }

    func ZipToWindow(_ win: WinInfo, _ text: String) -> Bool {
        if !Grounded() || sleepMode || state == "hug" || fetching { return false }
        var tx = 0.0, top = 0.0
        if !PlatEnd(win, &tx, &top) { return false }
        if supH == win.H { Say(text, 2); return true }
        ax = tx; ay = top; zipH = win.H; zipRight = tx > Double(win.L + win.R) / 2.0
        dir = ax >= Cx ? 1 : -1
        nextAct = "zip"; shootT = 0
        SetState("shoot", 1)
        Say(text, 2)
        return true
    }

    func StartClimb(_ side: Int) {
        wallSide = side; climbDir = -1; dir = side; goClimb = false; supH = IntPtr.Zero
        SetState("climb", R(2, 7))
    }

    func Climb(_ dt: Double, _ wa: Rectangle) {
        x = Double(wallSide < 0 ? wa.Left : wa.Right - SW)
        if climbDir < 0 {
            y -= 50 * k * dt
            if y <= Double(wa.Top + 4) || t < 0 {
                y = Math.Max(y, Double(wa.Top + 4))
                if InScene { t = 1; return }
                let cr = rnd.NextDouble()
                if cr < 0.45 { Jump(Double(-wallSide) * R(200, 350) * k, -R(150, 300) * k); Say("喝！", 0.8) }
                else if cr < 0.75 { gt = 0; SetState("peek", R(2.5, 4)) }
                else { climbDir = 1 }
            }
        }
        else {
            y += 70 * k * dt
            if y >= Double(wa.Bottom - SH) { y = Double(wa.Bottom - SH); dir = -wallSide; SetState("walk", R(2, 5)) }
        }
    }

    func SpinWeb(_ h: IntPtr, _ right: Bool) {
        if !w.Cands.ContainsKey(h) { return }
        let wi: WinInfo = w.Cands[h]
        let edge = right ? supR : supL, corner = right ? wi.R : wi.L
        if Math.Abs(edge - corner) > 12 { return }
        w.AddWeb(h, right)
        SetState("idle", 1.4)
        Say("在這裡織個網～", 1.6)
    }

    // 多人接球：用絲把球黏住再踢回去
    func WebCatch() {
        w.HoldBall(self)
        ax = w.Bx; ay = w.By; shootT = 1
        dir = ax >= Cx ? 1 : -1
        SetState("webcatch", 0.6)
        Say(Pick(["Thwip! 接住了！", "用絲接球！", "好球！Thwip!"]), 1.4)
        w.Umpire("好球！")
    }

    // 串場：把小波甩上去
    func SlingAt(_ o: Pet) {
        ax = o.Cx; ay = o.y + 6 * k; shootT = 1; dir = ax >= Cx ? 1 : -1
        SetState("sling", 1.0)
    }

    // ================= 小波：滑板車、棒球 =================
    func OnScooter() -> Bool {
        if !Is("po") || scooterLost { return false }
        if state == "fling" { return !rolling }
        if state == "walk" || state == "seek" || state == "fetch" || state == "hide" || state == "goto" { return true }
        if (state == "air" && !rolling) || state == "stowfly" { return true }
        return state == "idle" && t > 0 && (anim % 7) > 3.5
    }

    func StartBat(_ hitBall: Bool) {
        batT = 0; batHit = !hitBall
        SetState("bat", 1.1)
    }

    func Bat(_ dt: Double) {
        let prev = batT
        batT += dt
        if !batHit && prev < 0.22 && batT >= 0.22 && w.Holder === self {
            batHit = true
            let homer = rnd.NextDouble() < 0.45
            let bvx: Double = Double(dir) * (homer ? R(1300, 1700) : R(650, 950)) * k
            let bvy: Double = -(homer ? R(950, 1200) : R(450, 650)) * k
            w.ReleaseBall(Cx + Double(dir) * 14 * k, y + 8 * k, bvx, bvy)
            w.CatchCd = 1.2
            Burst(8)
            if homer {
                Say("全壘打！", 2.2)
                w.Fireworks(w.WA(Cx, y), 3, CInt(Cx + Double(dir) * 260 * k))
                w.Umpire("全壘打！")
                AddXp(1)
            }
            else { Say(Pick(["安打！", "打到了！再來一次！"]), 1.6); w.Umpire("好球！") }
        }
        if t < 0 { SetState("idle", 1) }
    }

    func PoBall() {
        let group = w.OutCount() > 1
        w.HoldBall(self)
        if rnd.NextDouble() < (group ? 0.6 : 0.3) { StartBat(true); Say("看我的！", 0.8); return }
        SetState("catch", 0.6)
        Say(L("ball_catch"), 1.8)
        w.Umpire("好球！")
    }

    // 全壘打慶祝（Codex／Claude 做完、上版）
    func HomeRun(_ line: String, _ lead: Bool) {
        if Grounded() { poseKind = "homerun"; SetState("pose", 3.4) }
        if lead { w.Fireworks(w.WA(Cx, y), 6, CInt(Cx)) }
        Say(line, 4); Burst(12)
    }

    // ================= 史迪仔：爬牆、天花板、咬球 =================
    func StartWallUp(_ side: Int) {
        wallSide = side; climbDir = -1; dir = side; goClimb = false; supH = IntPtr.Zero; crawlH = IntPtr.Zero
        SetState("wall", 99)
    }

    func StartWallDown(_ wi: WinInfo, _ right: Bool) {
        crawlH = wi.H; wallSide = right ? -1 : 1; climbDir = 1; goClimb = false; supH = IntPtr.Zero
        x = Double(right ? wi.R : wi.L - SW)
        ceilY = Double(wi.B); ceilL = Double(wi.L); ceilR = Double(wi.R - SW)
        SetState("wall", 99)
        Say("ih-ih! 爬下去～", 1.2)
    }

    func Wall(_ dt: Double, _ wa: Rectangle) {
        if crawlH == IntPtr.Zero {
            // 螢幕邊：往上爬到頂，然後倒掛在天花板上走
            x = Double(wallSide < 0 ? wa.Left : wa.Right - SW)
            y -= 130 * k * dt
            if y <= Double(wa.Top + 2) {
                y = Double(wa.Top); ceilY = Double(wa.Top); ceilL = Double(wa.Left); ceilR = Double(wa.Right - SW)
                dir = -wallSide; SetState("ceil", R(1.5, 3.5)); Say("倒立走路！嘻嘻嘻", 1.4)
            }
            return
        }
        // 視窗側邊：往下爬到視窗底，然後倒掛在視窗底下走
        var r = W.RECT()
        if !W.IsWindowVisible(crawlH) || !W.Rect(crawlH, &r) { Jump(0, 0); rolling = true; return }
        x = Double(wallSide < 0 ? r.R : r.L - SW)
        ceilY = Double(r.B); ceilL = Double(r.L); ceilR = Double(r.R - SW)
        y += 120 * k * dt
        if y >= ceilY - Double(SH) * 0.3 {
            y = ceilY; x = wallSide < 0 ? ceilR : ceilL
            dir = wallSide < 0 ? -1 : 1; SetState("ceil", R(1.5, 3))
        }
    }

    func Ceil(_ dt: Double) {
        if crawlH != IntPtr.Zero {
            var r = W.RECT()
            if !W.IsWindowVisible(crawlH) || !W.Rect(crawlH, &r) { Jump(0, 0); rolling = true; return }
            ceilY = Double(r.B); ceilL = Double(r.L); ceilR = Double(r.R - SW)
        }
        y = ceilY
        x += Double(dir) * 110 * k * dt
        if x < ceilL { x = ceilL; dir = 1 }
        if x > ceilR { x = ceilR; dir = -1 }
        if t < 0 { crawlH = IntPtr.Zero; Jump(0, 60 * k); rolling = true; Say(Pick(["跳！嗚哇～", "ih-ih-ih!", "放手！嘻嘻嘻"]), 1) }
    }

    func Curl(_ dt: Double) {
        x += vx * dt; vx *= Math.Pow(0.25, dt)
        rolling = true
        let nx = x
        let midY = y + Double(SH) / 2.0
        if !w.Inside(nx, midY) || !w.Inside(nx + Double(SW), midY) { vx = -vx }
        if supH != IntPtr.Zero && (Cx < Double(supL) || Cx > Double(supR)) { Jump(vx, -60 * k); return }
        if t < 0 { rolling = false; SetState("idle", 1); if rnd.NextDouble() < 0.5 { Say("嘻嘻嘻～", 1) } }
    }

    func StitchBall() {
        let group = w.OutCount() > 1
        w.HoldBall(self)
        if rnd.NextDouble() < (group ? 0.7 : 0.35) {
            SetState("chomp", group ? R(2, 3) : 1.2)
            Say(group ? "嘻嘻嘻！球是史迪仔的！" : Pick(["（咬）嘻嘻嘻", "ih-ih! 史迪仔的！", "（咬咬）好吃"]), 1.8)
            if group { w.Umpire("出局！…吧？") }
            return
        }
        SetState("catch", 0.5)
        Say(L("ball_catch"), 1.6)
        w.Umpire("好球！")
    }

    func Chomp(_ dt: Double) {
        if w.OutCount() > 1 {
            // 叼著球逃跑
            if let o = w.Nearest(self) { dir = o.Cx > Cx ? -1 : 1 }
            if MoveOnGround(dt, 160 * k) { return }
        }
        if t < 0 {
            if w.Holder === self { w.ReleaseBall(Cx + Double(dir) * 6 * k, y + 8 * k, 0, 0); KickBallToCursor(0.8) }
            Say(Pick(["噗！還你～", "呸！嘻嘻嘻"]), 1.2)
            SetState("idle", 1)
        }
    }

    // ================= 人魚漢頓：在空中「游泳」（波浪路線＋泡泡）、披風飛行、頂球 =================
    func StartSwim(_ tx: Double, _ footY: Double, _ cape: Bool) {
        fx0 = x; fy0 = y; fx1 = tx - Double(SW) / 2.0; fy1 = footY - Double(SH)
        let ddx = fx1 - fx0, ddy = fy1 - fy0
        let d = Math.Sqrt(ddx * ddx + ddy * ddy)
        flyDur = Pet.Clamp(d / ((cape ? 520 : 300) * k), 0.9, 4)
        flyArc = 30 * k + Math.Min(140 * k, d * 0.18)
        flyT = 0; supH = IntPtr.Zero; caped = cape
        dir = fx1 >= fx0 ? 1 : -1
        SetState("swim", 99)
    }

    func Swim(_ dt: Double) {
        flyT += dt
        let f = Math.Min(1, flyT / flyDur), e = Pet.Ease(f)
        let arc: Double = Math.Sin(Math.PI * f) * flyArc
        let wave: Double = caped ? 0 : Math.Sin(flyT * 7) * 9 * k * Math.Sin(Math.PI * f)
        x = fx0 + (fx1 - fx0) * e
        y = fy0 + (fy1 - fy0) * e - arc + wave
        if rnd.NextDouble() < dt * (caped ? 4 : 9) { Mark(5) }
        if f < 1 { return }
        x = fx1; y = fy1
        supH = IntPtr.Zero
        for p in w.Plats { if Cx >= Double(p.Left) && Cx <= Double(p.Right) && Math.Abs(Double(p.Top) - (y + Double(SH))) < 3 { SetSupport(p); break } }
        if supH == IntPtr.Zero {
            let wa = w.WA(Cx, y + Double(SH) / 2.0)
            if Math.Abs(Double(wa.Bottom) - (y + Double(SH))) > 3 { caped = false; Jump(0, 0); return }
        }
        let wasCape = caped; caped = false
        if afterLand != "" { LandAction() }
        else if wasCape { poseKind = "hero"; SetState("pose", 1.4); Say(Pick(["（落地）帥嗎？帥嗎？", "英雄著陸！…有點晃"]), 1.6) }
        else { SetState("idle", 1.2) }
    }

    // 像海豹一樣用頭頂球；偶爾連頂幾下
    func HangyodonBall() {
        SetState("header", 0.45)
        w.By = y - 2 * k; w.Bx = Cx
        headers += 1
        if headers < 3 && rnd.NextDouble() < 0.45 {
            w.Bvx = R(-60, 60) * k; w.Bvy = -R(520, 620) * k; w.CatchCd = 0.5
            fetching = true
            Say(Pick(["嘿咻！", "頂！頂！", "海豹式～"]), 0.9)
            return
        }
        headers = 0
        let c = Cursor.Position
        w.Bvx = Pet.Clamp((Double(c.X) - w.Bx) * 0.9, -800 * k, 800 * k); w.Bvy = -R(600, 760) * k; w.CatchCd = 1.0; w.BallIdle = 0
        Say(L("ball_catch"), 1.6)
        w.Umpire("好球！")
    }

    // 裁判喊聲（多人打棒球時由人魚漢頓喊）
    func Call(_ s: String) {
        if !Out || InScene { return }
        Say(s, 1.6)
        if Grounded() && state != "header" { poseKind = Is("dipsy") ? "hattip" : "hero"; SetState("pose", 0.9) }
    }

    // 串場用：直接設狀態／姿勢
    func ScenePose(_ kind: String, _ dur: Double) {
        if !Grounded() && kind != "fly" { return }
        switch kind {
        case "hero": poseKind = "hero"; SetState("pose", dur); Burst(6)
        case "photo": poseKind = "photo"; SetState("pose", dur)
        case "grin": poseKind = "grin"; SetState("pose", dur)
        case "silly": poseKind = "silly"; SetState("pose", dur)
        case "cape": poseKind = "hero"; SetState("pose", dur); for _ in 0..<3 { Mark(5) }
        case "wave": SetState("wave", dur)
        case "hug": SetState("hug", dur); AddHeart(); AddHeart()
        case "elvis": SetState("elvis", dur)
        case "hop": Jump(0, -260 * k)
        case "idle": SetState("idle", dur)
        case "dizzy": SetState("dizzy", dur)
        case "lick": poseKind = "lick"; SetState("pose", dur)
        // ---- 天線寶寶 ----
        case "plop": SetState("plop", dur); sT = 0; Burst(4); Mark(4)
        case "hattip", "hatwave", "hatdown", "sing": poseKind = kind; SetState("pose", dur)
        case "twirl", "dance", "kick", "catch", "spin": SetState(kind, dur)
        case "juggle": juggles = 0; sT = 0; SetState("juggle", dur)
        case "hattoss": sT = 0; SetState("hattoss", dur)
        case "bat": StartBat(false)
        default: if kind.StartsWith("bag") { TinkyBag(kind.Length > 4 ? kind.Substring(4) : "", true, dur) }
        }
    }
    func FaceTo(_ o: Pet) { dir = o.Cx > Cx ? 1 : -1 }
    func WalkTo(_ tx: Double, _ dur: Double) { seekX = tx; dir = tx > Cx ? 1 : -1; gotoSpeed = 1.5; SetState("goto", Math.Max(dur, 8)) }
    func RaceTo(_ tx: Double) { seekX = tx; dir = tx > Cx ? 1 : -1; gotoSpeed = Is("po") || Is("stitch") ? 1.4 : 1.1; SetState("goto", 10) }
    // 走到／跳到另一隻旁邊（串場前先湊在一起）；回傳大概要幾秒
    @discardableResult
    func ComeNear(_ o: Pet) -> Double {
        let mul: Double = P.Tubby || o.P.Tubby ? 2.0 : 1.35   // 天線寶寶比較寬（16 格＋道具）
        var tx = o.Cx + (Cx > o.Cx ? 1.0 : -1.0) * Double(o.SW) * mul
        let wa = w.WA(o.Cx, o.Foot - 4)
        tx = Pet.Clamp(tx, Double(wa.Left + SW), Double(wa.Right - SW))
        if supH == o.supH && Math.Abs(Foot - o.Foot) < 3 {
            let d = Math.Abs(tx - Cx)
            if d < Double(SW) * 0.6 { return 0 }
            if d < 700 * k { WalkTo(tx, 10); return Math.Min(6, d / (Math.Max(P.Speed, 60.0) * k * 1.5) + 0.3) }
        }
        if Is("hangyodon") { StartSwim(tx, o.Foot, false); return flyDur + 0.4 }
        BallisticTo(tx, o.Foot); return 1.6
    }
    func JumpTo(_ tx: Double, _ footY: Double) { BallisticTo(tx, footY) }
    func LoseScooter(_ lost: Bool) { scooterLost = lost }
    func ClimbRace(_ side: Int) { if Is("spidey") { StartClimb(side) } else if Is("stitch") { StartWallUp(side) } }
    var Foot: Double { return y + Double(SH) }
    var OnFloor: Bool { return supH == IntPtr.Zero }
}

// ================= 天線寶寶：丁丁（魔法袋）、迪西（乳牛紋帽子）、拉拉（大橘球）=================
extension Pet {
    var HasTv: Bool { return Is("po") || P.Tubby }

    static let TOAST: [String] = [".2222.", "211112", "2k11k2", "211112", "21kk12", ".2222."]
    static let STAR5: [String] = ["..y..", ".yyy.", "yyyyy", ".yyy.", ".y.y."]

    // 串場要用的小開關
    func LendHat(_ lent: Bool) { hatLost = lent }
    func LoseBall(_ lost: Bool) { ballLost = lost }
    func LendScooter(_ lent: Bool) { lentScooter = lent; LoseScooter(lent) }
    func ResetSceneProps() {
        if lentScooter { lentScooter = false; LoseScooter(false) }
        hatLost = false; WearHat = false; ballLost = false; RidingPo = false; HoldToast = false
        if state == "bagdig" { bagItem = "" }
    }
    // 頭頂（帽子中間）的螢幕座標：串場丟帽子、丟球用
    func HatPoint() -> PointF { return PointF(Cx, Foot - Double(SH) + Double((P.HeadTop - 3) * S)) }
    func HandPoint() -> PointF { return PointF(Cx + Double(dir * 5 * S), Foot - Double(SH) + Double((P.BodyTop + 2) * S)) }
    func FootPoint() -> PointF { return PointF(Cx + Double(dir * 4 * S), Foot - Double(3 * S)) }
    func BagPoint() -> PointF { return PointF(Cx + Double(dir * 9 * S), Foot - Double(SH) + Double((P.BodyTop + 3) * S)) }   // 打開的袋口（提在身體旁邊）
    func ClearCrumbs() { _ = notes.RemoveAll { n in n[2] == 7 } }

    func HatOnHead() -> Bool { return Is("dipsy") && !hatLost && state != "hattoss" && !(state == "pose" && poseKind == "hatwave") }

    // 丁丁：跌坐在地上「哎喲！」（小波在大家一起跌倒的串場也會）
    func Plop(_ text: String?) {
        SetState("plop", 1.5); sT = 0
        Burst(4); Mark(4)
        if let text = text { Say(text, 1.4) }
    }

    // 丁丁的魔法袋：打開、翻一翻、拿出東西（catch＝剛接住的球）
    func TinkyBag(_ item: String?, _ quiet: Bool) { TinkyBag(item, quiet, 2.4) }
    func TinkyBag(_ item: String?, _ quiet: Bool, _ dur: Double) {
        if !Is("tinky") || !Grounded() { return }
        var item = item
        if item == nil {
            let items: [String] = ["toast", "heart", "star", "toast", "ball"]
            item = items[rnd.Next(items.count)]
            let ll = w.Get("laalaa")
            if item == "ball" && (ll == nil || !ll!.Out) { item = "heart" }
        }
        bagItem = item ?? ""; bagQuiet = quiet; sT = 0
        SetState("bagdig", Math.Max(1.4, dur))
        if !quiet { Say(Pick(["魔法袋裡有什麼呢？", "丁丁找一找…", "（翻翻袋子）嗯…"]), 1.2) }
    }

    func BagReveal() {
        switch bagItem {
        case "catch":
            if w.Holder === self { w.ReleaseBall(Cx + Double(dir) * 8 * k, y + 6 * k, 0, 0); KickBallToCursor(0.9) }
            if !bagQuiet { Say(Pick(["找到了！還你～", "從魔法袋拿出來囉！"]), 1.6) }
        case "toast": if !bagQuiet { Say(Pick(["是吐司！", "吐司！要吃嗎？"]), 1.6) }
        case "heart": AddHeart(); AddHeart(); if !bagQuiet { Say("是愛心！送給你 ♥", 1.8) }
        case "star": Burst(10); if !bagQuiet { Say("是星星！✨", 1.6) }
        case "ball": if !bagQuiet { Say("咦？拉拉的球怎麼在這裡？", 2) }
        default: break
        }
    }

    // 迪西：帽子丟上去轉一圈、接回頭上
    func HatToss(_ quiet: Bool) {
        if !Is("dipsy") || !Grounded() || hatLost { return }
        sT = 0; SetState("hattoss", 1.6)
        if !quiet { Say(Pick(["看我的帽子！", "帽子戲法！", "嘿～"]), 1.2) }
    }

    // 拉拉：顛球（球在腳和頭頂之間跳）
    func Juggle() {
        if !Is("laalaa") || !Grounded() || ballLost { return }
        juggles = 0; sT = 0
        SetState("juggle", R(2.6, 3.6))
        Say(Pick(["看我的球！啦～", "顛球！1、2、3～", "球球跳跳～"]), 1.2)
    }
    func JugglePhase() -> Double { return (sT * 1.5) % 1.0 }

    func TubbyStep(_ dt: Double) -> Bool {
        if state == "pose" && poseKind == "sing" && rnd.NextDouble() < dt * 3 { Mark(0) }
        if state == "dance" && Is("laalaa") && rnd.NextDouble() < dt * 2 { Mark(0) }
        switch state {
        case "twirl":
            sT += dt
            if Math.Floor(anim * 9) != Math.Floor((anim - dt) * 9) { dir = -dir }
            if rnd.NextDouble() < dt * 3 { Mark(0) }
            if t < 0 { SetState("idle", InScene ? 30 : 1); if !InScene && Is("laalaa") && rnd.NextDouble() < 0.5 { Say("啦啦啦～", 1.2) } }
            return true
        case "hattoss":
            do {
                let prev = sT; sT += dt
                if prev < 1.25 && sT >= 1.25 { Burst(6); if !InScene { Say(Pick(["帥！", "接到了。酷。", "嘿～"]), 1.4) } }
                if t < 0 { SetState("idle", InScene ? 30 : 1) }
            }
            return true
        case "juggle":
            do {
                let prev = JugglePhase(); sT += dt
                if JugglePhase() < prev { juggles += 1; Mark(0); if !InScene { Say(String(juggles) + "！", 0.6) } }
                if t < 0 { SetState("idle", InScene ? 30 : 1); if !InScene { Say(juggles >= 3 ? "啦～！" + String(juggles) + " 下！" : "再來一次！", 1.4) } }
            }
            return true
        case "bagdig":
            do {
                let prev = sT; sT += dt
                if prev < 0.9 && sT >= 0.9 { BagReveal() }
                if t < 0 { if bagItem == "catch" && w.Holder === self { BagReveal() }; bagItem = ""; SetState("idle", InScene ? 30 : 1) }
            }
            return true
        default: break
        }
        return false
    }

    // ---------- 球（大家的球；小波在的話是棒球）----------
    func TinkyBall() {
        w.HoldBall(self)
        TinkyBag("catch", true, 1.8)
        if state != "bagdig" { w.ReleaseBall(Cx, y, 0, 0); KickBallToCursor(0.9) }   // 在空中接到：直接丟回去
        Say(L("ball_catch"), 1.6)
        w.Umpire("好球！")
    }

    // 迪西：用帽子頂球（偶爾連頂幾下）
    func DipsyBall() {
        SetState("header", 0.45)
        w.By = y + Double(SH) - Double(16 * S) + Double((P.HeadTop - 7) * S); w.Bx = Cx
        headers += 1
        if headers < 3 && rnd.NextDouble() < 0.4 {
            w.Bvx = R(-60, 60) * k; w.Bvy = -R(520, 620) * k; w.CatchCd = 0.5
            fetching = true
            Say(Pick(["帽子頂！", "嘿！再一下", "酷～"]), 0.9)
            return
        }
        headers = 0
        let c = Cursor.Position
        w.Bvx = Pet.Clamp((Double(c.X) - w.Bx) * 0.9, -800 * k, 800 * k); w.Bvy = -R(600, 760) * k; w.CatchCd = 1.0; w.BallIdle = 0
        Say(L("ball_catch"), 1.6)
    }

    // 拉拉：用腳踢（偶爾先顛幾下）
    func LaaLaaBall() {
        SetState("kick", 0.45)
        w.By = y + Double(SH) - w.BallR() - 2 * k; w.Bx = Cx + Double(dir) * 4 * k
        headers += 1
        if headers < 3 && rnd.NextDouble() < 0.45 {
            w.Bvx = R(-40, 40) * k; w.Bvy = -R(480, 600) * k; w.CatchCd = 0.5
            fetching = true
            Say(Pick(["1、2…", "啦～顛球！", "嘿咻！"]), 0.9)
            return
        }
        headers = 0
        let c = Cursor.Position
        w.Bvx = Pet.Clamp((Double(c.X) - w.Bx) * 1.1, -950 * k, 950 * k); w.Bvy = -R(500, 700) * k; w.CatchCd = 1.0; w.BallIdle = 0
        Say(L("ball_catch"), 1.6)
        w.Umpire("好球！")
    }

    // ---------- 畫 ----------
    func FrameTubby() -> Fr {
        let hug = state == "hug", sleep = state == "sleep", plop = state == "plop"
        let nightIdle = Night && state == "idle" && !InScene && !HoldingFood()
        let sit = sleep || plop || (Is("laalaa") && nightIdle)
        let yawn = Night && state == "idle" && (anim % 6) < 1.4
        var face: String?
        let posePhotoSingWave = state == "pose" && (poseKind == "photo" || poseKind == "sing" || poseKind == "hatwave")
        let happyA = hug || state == "twirl" || state == "juggle" || (state == "dance" && Step2(2))
        let happyB = (state == "bagdig" && sT > 0.9) || posePhotoSingWave
        if plop { face = sT < 0.55 ? "OUCH" : "HAPPY" }
        else if sleep || yawn || (Is("dipsy") && nightIdle) || (state == "pose" && poseKind == "hatdown") { face = "SLEEPY" }
        else if happyA || happyB { face = "HAPPY" }
        else if state == "dizzy" { face = "DIZZY" }
        else if state == "glass" { face = "SQUISH" }
        else { face = nil }
        var armsUp = state == "glass" || state == "catch" || state == "drag" || state == "air" || state == "fling"
        armsUp = armsUp || state == "kick" || state == "header" || (state == "throw" && t > 0.15)
        armsUp = armsUp || (state == "wave" && Step2(4)) || (state == "dance" && Step2(4)) || state == "twirl"
        armsUp = armsUp || (state == "hattoss" && (sT < 0.3 || (sT > 1.1 && sT < 1.5)))
        let poseArms = poseKind == "photo" || poseKind == "hatwave" || poseKind == "hattip" || (poseKind == "sing" && Step2(3))
        armsUp = armsUp || (state == "pose" && poseArms)
        armsUp = armsUp || (state == "bagdig" && sT > 0.9 && sT < 1.7)
        if RidingPo { armsUp = state == "air" || state == "drag" }
        lastArmsUp = armsUp
        let bodyName = hug || (nightIdle && !Is("dipsy")) ? "ARMS_HUG" : (armsUp ? "ARMS_UP" : "BODY")
        var legs: String
        let ride = RidingPo && !rolling
        if ride { legs = "LEGS_RIDE" }
        else if sit { legs = "LEGS_SIT" }
        else {
            let moving = state == "walk" || state == "seek" || state == "fetch" || state == "hide" || state == "goto"
            let rate: Double = Is("tinky") ? 5 : (Is("laalaa") ? 9 : 7)
            var step = (moving && Step2(rate)) || (state == "dance" && Step2(4))
            step = step || (state == "juggle" && JugglePhase() < 0.2) || (state == "kick" && t > 0.15)
            legs = step ? "LEGS_B" : "LEGS_A"
        }
        let f = F(Pal.Stack(HeadRows(face), A(bodyName), A(legs)))
        if ride { f.Top = -4; f.AccDy = -4 }
        else if sit { f.AccDy = A("LEGS_A").count - A("LEGS_SIT").count }
        f.Tummy = !hug
        if rolling { f.Rot = CInt(Math.Floor(anim * 14)) % 4; f.Acc = false; f.Tummy = false }
        return f
    }

    func TubbyBob() -> Double {
        if state == "dance" || state == "elvis" { return Math.Abs(Math.Sin(anim * (Is("dipsy") ? 6 : 8))) * 6 * k }
        let moving = state == "walk" || state == "goto" || state == "seek" || state == "fetch"
        if moving && !RidingPo {
            if Is("laalaa") { return Math.Abs(Math.Sin(anim * 7)) * 5 * k }      // 蹦蹦跳跳
            if Is("dipsy") { return Math.Abs(Math.Sin(anim * 5)) * 2.5 * k }     // 跟著節奏
        }
        if Is("dipsy") && state == "idle" && !Night { return (Math.Floor(anim * 2) % 2) * k }   // 點頭打拍子
        return 0
    }

    // 拉拉的球現在在哪裡：none／floor（腳邊）／dribble（往前帶）／juggle／hold（抱著）／raised（舉高高）
    func BallSpot(_ f: Fr) -> String {
        if !Is("laalaa") || ballLost || w.BallOn || f.Rot != 0 || f.Fy { return "none" }
        if w.Lunch && HoldingFood() && state != "sleep" { return "none" }
        if state == "juggle" { return "juggle" }
        if state == "pose" && poseKind == "photo" { return "raised" }
        if Night && state == "idle" && !InScene { return "hold" }
        if state == "air" || state == "fling" || state == "drag" || state == "stowfly" { return "hold" }
        if state == "walk" || state == "goto" || state == "seek" || state == "hide" { return "dribble" }
        return "floor"
    }

    // 丁丁的袋子在哪裡：floor（放地上）／hand（提著）／up（舉起來）／hug（抱著）／open（打開翻找）
    func BagSpot(_ f: Fr) -> String {
        if !Is("tinky") || f.Rot != 0 || f.Fy { return "none" }
        if state == "bagdig" { return "open" }
        if state == "hug" || state == "sleep" || state == "plop" || RidingPo || HoldToast || (w.Lunch && HoldingFood()) { return "floor" }
        if Night && state == "idle" && !InScene { return "hug" }
        return lastArmsUp ? "up" : "hand"
    }

    func DrawTubbyBehind(_ g: Graphics, _ f: Fr, _ bx: Int, _ by: Int, _ ps: Int, _ fx: Bool) {
        if RidingPo && !rolling {
            if let po = Pal.Get("po") { DrawPixPal(g, po, po.Art["SCOOTER"], bx + (fx ? 12 - (-1) - 14 : -1) * ps, by + 7 * ps, ps, fx) }
        }
        if BagSpot(f) == "floor" { DrawAt(g, A("BAG"), HoldToast || w.Lunch ? -8.5 : 12.5, 9, bx, by, ps, fx, false, true) }   // 手上拿吃的：袋子放另一邊
        if BallSpot(f) == "floor" { DrawAt(g, A("BALL"), 12, 9, bx, by, ps, fx, false, true) }
    }

    func DrawTubbyFront(_ g: Graphics, _ f: Fr, _ bx: Int, _ by: Int, _ ps: Int, _ fx: Bool) {
        if f.Rot != 0 || f.Fy { return }
        let dy = f.AccDy
        // 迪西的帽子
        if Is("dipsy") && !hatLost {
            let hat = A("HAT")
            var row = Double(P.HeadTop - 6 + dy), col = -2.0
            if state == "hattoss" && sT < 1.25 {
                let ff = Pet.Clamp(sT / 1.25, 0, 1)
                row -= Math.Sin(Math.PI * ff) * 11
                let side = Math.Floor(sT * 10) % 2 == 1                       // 轉呀轉：正面、側面輪流
                let flipNow = fx != (Math.Floor(sT * 5) % 2 == 1)
                DrawAt(g, side ? A("HAT_HAND") : hat, side ? 2 : col, row, bx, by, ps, flipNow, false, true)
            }
            else if state == "pose" && poseKind == "hatwave" {
                DrawAt(g, A("HAT_HAND"), 11.0 + (Step2(4) ? 1.0 : 0.0), Double(P.BodyTop - 8 + dy), bx, by, ps, fx, false, true)
            }
            else {
                if state == "pose" && poseKind == "hattip" { row -= 2; col += 1 }
                else if state == "header" { row -= 1 }
                else if (state == "pose" && poseKind == "hatdown") || state == "sleep" || (Night && state == "idle" && !InScene) { row += 3 }   // 帽子拉低蓋住眼睛
                DrawAt(g, hat, col, row, bx, by, ps, fx, false, true)
            }
        }
        // 借戴迪西的帽子（串場）
        if WearHat { DrawAt(g, A("HAT"), -2, Double(P.HeadTop - 6 + dy), bx, by, ps, fx, false, true) }
        // 丁丁的魔法袋
        switch BagSpot(f) {
        case "hand": DrawAt(g, A("BAG"), 12 + (state == "walk" && Step2(5) ? 0.5 : 0), Double(P.BodyTop + 1 + dy), bx, by, ps, fx, false, true)
        case "up": DrawAt(g, A("BAG"), 12.5, Double(P.BodyTop - 5 + dy), bx, by, ps, fx, false, true)
        case "hug": DrawAt(g, A("BAG"), 2, Double(P.BodyTop + 2 + dy), bx, by, ps, fx, false, true)
        case "open":
            do {
                // 袋子打開提在身體旁邊，東西從袋口冒出來（不擋到臉）
                let bagRow = Double(P.BodyTop + 2 + dy)
                if let item = BagItemArt(), sT > 0.9 {
                    let rise = Pet.Clamp((sT - 0.9) / 0.35, 0, 1) * Double(item.count + 2)
                    if !(bagItem == "catch" && w.Holder !== self && sT > 1.3) {
                        DrawAt(g, item, 15 - Double(item[0].count) / 2.0, bagRow + 2 - rise, bx, by, ps, fx, false, true)
                    }
                }
                DrawAt(g, A("BAG_OPEN"), 11, bagRow, bx, by, ps, fx, false, true)
            }
        default: break
        }
        // 拉拉的球
        let ball = A("BALL")
        switch BallSpot(f) {
        case "juggle":
            do {
                let h = Math.Sin(Math.PI * JugglePhase()) * 12
                DrawAt(g, ball, 10, 9 - h, bx, by, ps, fx, false, true)   // 在身體前側顛，不擋臉
            }
        case "dribble": DrawAt(g, ball, 11.5, 9 - Math.Abs(Math.Sin(anim * 8)) * 2, bx, by, ps, fx, false, true)
        case "hold": DrawAt(g, ball, 2, Double(P.BodyTop + 2 + dy), bx, by, ps, fx, false, true)
        case "raised": DrawAt(g, ball, 2, Double(P.HeadTop - 8 + dy), bx, by, ps, fx, false, true)
        default: break
        }
    }

    func BagItemArt() -> [String]? {
        switch bagItem {
        case "toast": return Pet.TOAST
        case "heart": return Pet.HEART
        case "star": return Pet.STAR5
        case "ball": return A("BALL")
        case "catch": return w.BallKind == "baseball" ? Pet.BALLART : (w.BallKind == "tubby" ? A("BALL") : Pet.TBALL)
        default: break
        }
        return nil
    }

    // ---------- 櫃子裡：丁丁翻魔法袋、迪西抬帽子打拍子、拉拉拍球；晚上抱著自己的東西睡 ----------
    // mac: head 在 C# 是共用參考、ReplaceFace 會改它；這裡複製一份再用 inout 改（呼叫端之後不再用 head）
    func DrawTubbyShelf(_ g: Graphics, _ head: [String], _ fx: Int, _ bx: Int, _ by: Int, _ ps: Int, _ flip: Bool, _ tt: Double, _ blink: Bool) {
        var head = head
        var by = by
        var body = "BODY", legs = "LEGS_A"
        var normalFace = true, sit = false
        var groove = 0
        if Is("tinky") {
            if Night { body = "ARMS_HUG"; if (tt % 5) < 3 { ReplaceFace(&head, "SLEEPY"); normalFace = false } }
            else if (tt % 8) < 2.4 && !w.Lunch && (tt % 8) > 0.9 { ReplaceFace(&head, "HAPPY"); normalFace = false }
            else if blink { ReplaceFace(&head, "SLEEPY"); normalFace = false }
        }
        else if Is("dipsy") {
            if Night { ReplaceFace(&head, "SLEEPY"); normalFace = false }
            else {
                groove = Math.Floor(tt * 2.2) % 2 == 0 ? 0 : 1
                if (tt % 5) < 0.9 { ReplaceFace(&head, "HAPPY"); normalFace = false }
                else if blink { ReplaceFace(&head, "SLEEPY"); normalFace = false }
            }
        }
        else {
            if Night { sit = true; body = "ARMS_HUG"; legs = "LEGS_SIT"; if (tt % 6) < 4 { ReplaceFace(&head, "SLEEPY"); normalFace = false } }
            else if Math.Abs(Math.Sin(tt * 3.2)) > 0.8 { ReplaceFace(&head, "HAPPY"); normalFace = false }
            else if blink { ReplaceFace(&head, "SLEEPY"); normalFace = false }
        }
        by += groove
        let dy = sit ? A("LEGS_A").count - A("LEGS_SIT").count : 0
        let rows = Pal.Stack(head, A(body), A(legs))
        if Is("tinky") && w.Lunch { DrawAt(g, A("BAG"), 9.5, 9, bx, by, ps, flip, false, true) }
        DrawPix(g, rows, bx - (rows[0].count - 12) / 2 * ps, by + (16 - rows.count) * ps, ps, flip, false, true)
        DrawAccessories(g, bx, by, ps, flip, dy, normalFace)
        DrawStatusIcon(g, TummyStatus(), bx + 6 * ps, by + CInt((P.TummyRow + Double(dy)) * Double(ps)), Math.Max(1, ps / 2), true)
        if Is("tinky") && !w.Lunch {
            if Night { DrawAt(g, A("BAG"), 2, Double(P.BodyTop + 2), bx, by, ps, flip, false, true) }
            else if (tt % 8) < 2.4 {
                let ph = tt % 8
                let items: [[String]] = [Pet.TOAST, Pet.HEART, Pet.STAR5]
                let item = items[CInt(Math.Floor(tt / 8)) % 3]
                if ph > 0.9 {
                    let rise = Pet.Clamp((ph - 0.9) / 0.35, 0, 1) * Double(item.count + 2)
                    DrawAt(g, item, 13.5 - Double(item[0].count) / 2.0, Double(P.BodyTop + 5) - rise, bx, by, ps, flip, false, true)
                }
                DrawAt(g, A("BAG_OPEN"), 9.5, Double(P.BodyTop + 3), bx, by, ps, flip, false, true)
            }
            else { DrawAt(g, A("BAG"), 9, Double(P.BodyTop + 3), bx, by, ps, flip, false, true) }
        }
        if Is("dipsy") { DrawAt(g, A("HAT"), -2, Double(P.HeadTop - 6 + (Night ? 3 : ((tt % 5) < 0.9 ? -1 : 0))), bx, by, ps, flip, false, true) }
        if Is("laalaa") && Night { DrawAt(g, A("BALL"), 2, Double(P.BodyTop + 2 + dy), bx, by, ps, flip, false, true) }
        else if Is("laalaa") && !w.Lunch { DrawAt(g, A("BALL"), 9.5, 9 - Math.Abs(Math.Sin(tt * 3.2)) * 4, bx, by, ps, flip, false, true) }   // 在旁邊拍球（格子窄，靠近一點）
    }
}

// ===== 32_pet_draw.swift =====
// 32_pet_draw.swift — port of DeskPals.cs lines 3981–5406
// (Fr, Pet drawing partial, ShelfForm, Pet shelf-drawing partial)
import Foundation

// ================= 畫（每個角色的姿勢、配件、特效）=================
final class Fr
{
    var Rows: [String] = []
    var Top = 0, Rot = 0          // Top：圖的第一列放在 16 格框的第幾列（可負）；Rot：轉 90° 的次數
    var Fy = false, Acc = true, Tummy = false
    var AccDy = 0                 // 配件（帽子等）要跟著頭上下移多少格
}


extension Pet
{
    static let SCARF = [ "..YYYYYYYY..", "......YY....", "......Y....." ]
    static let BEANIE = [ ".....WW.....", "....PPPP....", "...PPPPPP...", "..WWWWWWWW.." ]
    static let CROWN = [ "...Y.YY.Y...", "...YYYYYY...", "...YPYYPY..." ]
    static let SANTA = [ "........WW..", ".....SSSS...", "....SSSSSS..", "...WWWWWWWW." ]
    static let GLASSES = [ "..P.P..P.P..", "..PPPkkPPP..", "...P....P..." ]
    static let ENVELOPE = [ "SSS", "SYS", "SSS", "SSS" ]
    static let CAKE = [ ".Y..", "PPPP", "WWWW", "PPPP" ]
    static let FLAKE = [ ".B.", "BBB", ".B." ]
    static let STAR = [ ".y.", "yyy", ".y." ]
    static let HEART = [ ".pp.pp.", "ppppppp", "ppppppp", ".ppppp.", "..ppp..", "...p..." ]
    static let ZZ = [ "kkkk", "..k.", ".k..", "kkkk" ]
    static let NOTE = [ "..kk", "..kk", "..k.", "..k.", "kkk.", "kk.." ]
    static let EXCL = [ "SS", "SS", "SS", "..", "SS" ]
    static let QUES = [ ".kkk.", "k...k", "...k.", "..k..", ".....", "..k.." ]
    static let DROP = [ ".B.", "BBB", "BBB", ".B." ]
    static let BADGE = [ "YY" ]
    static let BALLART = [ ".33.", "3433", "3343", ".33." ]
    static let TBALL = [ ".yy.", "yyyy", "yyyy", ".yy." ]
    // 小波的球棒（三個角度）、手套
    static let BAT_UP = [ "..11", "..12", ".12.", ".2..", "k...", "k..." ]
    static let BAT_FWD = [ "k11111122" ]
    static let BAT_FOLLOW = [ "11..", "21..", ".21.", "..2.", "...k", "...k" ]
    static let GLOVE = [ ".55.", "5665", "5565", ".55." ]

    // mac: instance accessors so the C#-style unqualified names work inside Pet methods (any file)
    var SCARF: [String] { return Pet.SCARF }
    var BEANIE: [String] { return Pet.BEANIE }
    var CROWN: [String] { return Pet.CROWN }
    var SANTA: [String] { return Pet.SANTA }
    var GLASSES: [String] { return Pet.GLASSES }
    var ENVELOPE: [String] { return Pet.ENVELOPE }
    var CAKE: [String] { return Pet.CAKE }
    var FLAKE: [String] { return Pet.FLAKE }
    var STAR: [String] { return Pet.STAR }
    var HEART: [String] { return Pet.HEART }
    var ZZ: [String] { return Pet.ZZ }
    var NOTE: [String] { return Pet.NOTE }
    var EXCL: [String] { return Pet.EXCL }
    var QUES: [String] { return Pet.QUES }
    var DROP: [String] { return Pet.DROP }
    var BADGE: [String] { return Pet.BADGE }
    var BALLART: [String] { return Pet.BALLART }
    var TBALL: [String] { return Pet.TBALL }
    var BAT_UP: [String] { return Pet.BAT_UP }
    var BAT_FWD: [String] { return Pet.BAT_FWD }
    var BAT_FOLLOW: [String] { return Pet.BAT_FOLLOW }
    var GLOVE: [String] { return Pet.GLOVE }

    func F(_ rows: [String]) -> Fr { let f = Fr(); f.Rows = rows; return f }
    func A(_ n: String) -> [String] { if P.Art.ContainsKey(n) { return P.Art[n] }; App.Log("missing art " + P.Id + "." + n); return P.Art["BODY"] }

    // mac: replace single ASCII chars in a pixel-art row (C#: ToCharArray / new string)
    static func SetPix(_ s: String, _ i: Int, _ c: UInt8) -> String
    {
        var a = Array(s.utf8)
        if i >= 0 && i < a.count { a[i] = c }
        return String(decoding: a, as: UTF8.self)
    }
    static func PixAt(_ s: String, _ i: Int) -> UInt8
    {
        let u = s.utf8
        if i < 0 || i >= u.count { return 0 }
        return u[u.index(u.startIndex, offsetBy: i)]
    }

    func HeadRows(_ face: String?) -> [String]
    {
        var head = A("HEAD")
        if let face = face, P.Art.ContainsKey(face)
        {
            let fr = A(face)
            var i = 0
            while i < fr.count && P.FaceRow + i < head.count
            {
                if fr[i].utf8.count == head[P.FaceRow + i].utf8.count { head[P.FaceRow + i] = fr[i] }
                i += 1
            }
        }
        else if P.EyeRow >= 0 && state != "glass"
        {
            // 眼睛跟著滑鼠
            let cp = Cursor.Position
            let dx = Double(cp.X) - Cx
            var off = dx < -30 ? -1 : (dx > 30 ? 1 : 0)
            if dir < 0 { off = -off }
            var e = Array(head[P.EyeRow].utf8)
            e[P.EyeL + off] = 107; e[P.EyeR + off] = 107   // 'k'
            head[P.EyeRow] = String(decoding: e, as: UTF8.self)
        }
        return head
    }

    func Step2(_ rate: Double) -> Bool { return Math.Floor(anim * rate) % 2 == 1 }

    func Frame() -> Fr
    {
        switch P.Id
        {
            case "po": return FramePo()
            case "stitch": return FrameStitch()
            case "hangyodon": return FrameHangyodon()
            case "tinky", "dipsy", "laalaa": return FrameTubby()
            default: break
        }
        return FrameSpidey()
    }

    // ---- Spidey（照舊）----
    func FrameSpidey() -> Fr
    {
        let sleep = state == "sleep", hug = state == "hug"
        var armsUp = state == "glass" || state == "kick" || (state == "dance" && Math.Floor(anim * 4) % 2 == 0) || state == "swing" || state == "air" || state == "fling" || state == "climb" || state == "drag" || state == "shoot" || state == "zip"
        armsUp = armsUp || state == "webcatch" || state == "sling" || state == "pose" || state == "stowfly" || (state == "hang" && hangPhase == 0) || (state == "idle" && Bt > 0)
        let step = ((state == "walk" || state == "climb" || state == "goto") && Step2(6))
            || ((state == "seek" || state == "fetch" || state == "hide") && Step2(11))
            || (state == "drag" && Step2(12))
            || (state == "dance" && Math.Floor(anim * 4) % 2 == 1)
        let face: String? = sleep ? "SLEEPY" : (hug ? "HAPPY" : (state == "dizzy" ? "DIZZY" : nil))
        var rows: [String] = HeadRows(face)
        rows += A(hug ? "ARMS_HUG" : (armsUp ? "ARMS_UP" : "BODY"))
        rows += A(step ? "LEGS_B" : "LEGS_A")
        if Night && !hug
        {
            if Pet.PixAt(rows[10], 5) == 107 && Pet.PixAt(rows[10], 6) == 107 { rows[10] = Pet.SetPix(Pet.SetPix(rows[10], 5, 119), 6, 119) }   // k → w
        }
        if !hug && Level() >= 5
        {
            if Pet.PixAt(rows[10], 5) != 114 && Pet.PixAt(rows[10], 6) != 114 { rows[10] = Pet.SetPix(Pet.SetPix(rows[10], 5, 89), 6, 89) }   // != r → Y
        }
        let f = F(rows)
        f.Fy = state == "hang" && hangPhase == 1
        return f
    }

    // ---- 小波 ----
    func FramePo() -> Fr
    {
        if state == "plop" { let pf = F(Pal.Stack(HeadRows(sT < 0.55 ? "DIZZY" : "HAPPY"), A("ARMS_UP"), A("LEGS_SIT"))); pf.Tummy = true; return pf }
        let hug = state == "hug", sleep = state == "sleep"
        let yawn = Night && state == "idle" && (anim % 6) < 1.4
        let face: String? = sleep || yawn ? "SLEEPY" : (hug || state == "spin" || (state == "pose" && poseKind == "homerun") ? "HAPPY" : (state == "dizzy" ? "DIZZY" : (state == "glass" ? "SQUISH" : nil)))
        var armsUp = state == "glass" || state == "catch" || state == "drag" || (state == "air" && !OnScooter()) || (state == "wave" && Step2(4)) || (state == "dance" && Step2(4))
        armsUp = armsUp || (state == "pose" && poseKind != "homerun") || state == "kick" || state == "throw" && t > 0.15
        let body = A(hug ? "ARMS_HUG" : (armsUp ? "ARMS_UP" : "BODY"))
        let f: Fr
        if OnScooter() { f = F(Pal.Stack(HeadRows(face), body, A("LEGS_RIDE"))); f.Top = -4; f.AccDy = -4 }
        else if sleep { f = F(Pal.Stack(HeadRows(face), body, A("LEGS_SIT"))) }
        else
        {
            let step = (state == "walk" || state == "seek" || state == "fetch" || state == "hide" || state == "goto") && Step2(10) || (state == "dance" && Step2(4))
            f = F(Pal.Stack(HeadRows(face), body, A(step ? "LEGS_B" : "LEGS_A")))
        }
        f.Tummy = !hug
        if rolling { f.Rot = CInt(Math.Floor(anim * 14)) % 4; f.Acc = false; f.Tummy = false }
        return f
    }

    // ---- 史迪仔 ----
    func FrameStitch() -> Fr
    {
        let hug = state == "hug"
        if RidingStolen
        {
            // 偷騎小波的滑板車：站在車上
            let rs = F(Pal.Stack(HeadRows("HAPPY"), A("ARMS_UP"), A("LEGS_A"))); rs.Top = -4; rs.AccDy = -4; return rs
        }
        if rolling || state == "curl"
        {
            let b = F(A("BALL")); b.Rot = CInt(Math.Floor(anim * 12)) % 4; b.Acc = false; return b
        }
        if state == "sleep"
        {
            let b = F(A("BALL_SLEEP")); b.Acc = false; return b
        }
        let crawl = state == "walk" || state == "seek" || state == "fetch" || state == "hide" || state == "goto" || (state == "chomp" && w.OutCount() > 1) || state == "ceil"
        let face: String? = hug ? "HAPPY" : (state == "dizzy" ? "DIZZY" : nil)
        var head = HeadRows(face)
        if crawl
        {
            let c = F(Pal.Stack(head, A(Step2(state == "ceil" ? 8 : 12) ? "CRAWL_B" : "CRAWL_A")))
            c.AccDy = 5
            if state == "ceil" { c.Fy = true; c.Acc = false }
            return c
        }
        // 耳朵：發呆時偶爾抖一抖；晚上垂下來
        if Night && (state == "idle" || state == "hug") { let ed = A("EARS_DOWN"); for i in 0..<ed.count { head[i] = ed[i] } }
        else if (state == "idle" || state == "pose") && (anim % 2.2) < 0.5 && Step2(8) { let eu = A("EARS_UP"); for i in 0..<eu.count { head[i] = eu[i] } }
        var armsUp = state == "wall" || state == "catch" || state == "drag" || state == "air" || state == "nudge" || state == "throw"
        armsUp = armsUp || (state == "elvis" && Step2(5)) || (state == "dance" && Step2(4)) || (state == "pose" && poseKind == "photo") || state == "kick"
        let lick = state == "glass" || (state == "pose" && poseKind == "lick"), grin = state == "chomp" || (state == "pose" && poseKind == "grin")
        if lick { ReplaceFace(&head, "LICKF") } else if grin { ReplaceFace(&head, "GRIN") }
        let bodyName = hug || (Night && state == "idle") ? "ARMS_HUG" : (lick ? "LICK" : (armsUp ? "ARMS_UP" : "BODY"))
        let step = (state == "wall" && Step2(8)) || (state == "elvis" && Step2(6)) || (state == "dance" && Step2(4))
        return F(Pal.Stack(head, A(bodyName), A(step ? "LEGS_B" : "LEGS_A")))
    }

    // ---- 人魚漢頓 ----
    func FrameHangyodon() -> Fr
    {
        let hug = state == "hug", sit = state == "sleep"
        let silly = state == "pose" && poseKind == "silly"
        let sleepy = state == "sleep" || (Night && state == "idle" && (anim % 5) < 1.5)
        let face: String? = sleepy ? "SLEEPY" : (hug || (state == "pose" && poseKind == "hero") ? "HAPPY" : (state == "dizzy" || tripT > 0 ? "DIZZY" : (silly ? "SILLY" : nil)))
        let head = HeadRows(face)
        var armsUp = state == "air" || state == "fling" || state == "drag" || state == "header" || state == "capetrip" || state == "swim"
        armsUp = armsUp || (state == "dance" && Step2(3)) || (state == "pose" && poseKind != "silly") || state == "kick"
        let bodyName = hug ? "ARMS_HUG" : (silly || state == "glass" ? "POUT" : (armsUp ? "ARMS_UP" : "BODY"))
        let moving = state == "walk" || state == "seek" || state == "fetch" || state == "hide" || state == "goto"
        let legs = sit ? "LEGS_SIT" : (moving && Step2(4) ? "LEGS_B" : "LEGS_A")
        let f = F(Pal.Stack(head, A(bodyName), A(legs)))
        if tripT > 0 { f.Rot = dir > 0 ? 1 : 3; f.Acc = false }   // 跌個狗吃屎
        if rolling { f.Rot = CInt(Math.Floor(anim * 10)) % 4; f.Acc = false }
        return f
    }

    // 把只往右延伸的圖左邊補空白，讓 12 格的身體留在框的中間
    static func PadCenter(_ rows: [String], _ extra: Int) -> [String]
    {
        let pad = String(repeating: ".", count: Swift.max(0, extra))
        return rows.map { pad + $0 }
    }

    static func Rot90(_ rows: [String], _ r0: Int) -> [String]
    {
        let r = ((r0 % 4) + 4) % 4
        var cur = rows
        var n = 0
        while n < r
        {
            let h = cur.count, wd = cur[0].utf8.count
            var o = [[UInt8]](repeating: [UInt8](repeating: 46, count: h), count: wd)
            for ry in 0..<h
            {
                let row = Array(cur[ry].utf8)
                for rx in 0..<wd { o[rx][h - 1 - ry] = rx < row.count ? row[rx] : 46 }
            }
            cur = o.map { String(decoding: $0, as: UTF8.self) }
            n += 1
        }
        return cur
    }

    func DrawPix(_ g: Graphics, _ rows: [String], _ bx: Int, _ by: Int, _ ps: Int, _ fx: Bool, _ fy: Bool, _ withHalo: Bool)
    {
        let pal = Night ? P.Night : P.Day
        let hw = Math.Max(1, ps / 3)
        let h = rows.count
        let hb = SolidBrush(Night ? P.HaloNight : P.Halo)
        let b = SolidBrush(Color.Magenta)
        // mac: per-call colour lookup table (ASCII art) instead of a Dictionary<char> lookup per pixel
        var lut = [Color?](repeating: nil, count: 128)
        var pass = withHalo ? 0 : 1
        while pass < 2
        {
            var ry = 0
            while ry < h
            {
                let row = rows[ry].utf8
                let len = row.count
                var rx = 0
                for c in row
                {
                    if c != 46
                    {
                        let px = bx + (fx ? len - 1 - rx : rx) * ps, py = by + (fy ? h - 1 - ry : ry) * ps
                        if pass == 0 { g.FillRectangle(hb, px - hw, py - hw, ps + 2 * hw, ps + 2 * hw) }
                        else
                        {
                            let ci = Int(c & 127)
                            var col: Color
                            if let cc = lut[ci] { col = cc }
                            else
                            {
                                let ch = Character(Unicode.Scalar(c))
                                col = pal.ContainsKey(ch) ? pal[ch] : Color.Magenta
                                lut[ci] = col
                            }
                            b.Color = col
                            g.FillRectangle(b, px, py, ps, ps)
                        }
                    }
                    rx += 1
                }
                ry += 1
            }
            pass += 1
        }
    }

    // 12 格框座標放一張小圖（會跟著左右翻）
    func DrawAt(_ g: Graphics, _ art: [String], _ col: Double, _ row: Double, _ bx0: Int, _ by0: Int, _ ps: Int, _ fx: Bool, _ fy: Bool, _ halo: Bool)
    {
        let aw = art[0].utf8.count, ah = art.count
        let c = fx ? 12 - col - Double(aw) : col, r = fy ? 16 - row - Double(ah) : row
        DrawPix(g, art, bx0 + CInt(Math.Round(c * Double(ps))), by0 + CInt(Math.Round(r * Double(ps))), ps, fx, fy, halo)
    }
    // mac: Int overloads (C# promoted int → double implicitly)
    func DrawAt(_ g: Graphics, _ art: [String], _ col: Int, _ row: Int, _ bx0: Int, _ by0: Int, _ ps: Int, _ fx: Bool, _ fy: Bool, _ halo: Bool)
    { DrawAt(g, art, Double(col), Double(row), bx0, by0, ps, fx, fy, halo) }
    func DrawAt(_ g: Graphics, _ art: [String], _ col: Double, _ row: Int, _ bx0: Int, _ by0: Int, _ ps: Int, _ fx: Bool, _ fy: Bool, _ halo: Bool)
    { DrawAt(g, art, col, Double(row), bx0, by0, ps, fx, fy, halo) }
    func DrawAt(_ g: Graphics, _ art: [String], _ col: Int, _ row: Double, _ bx0: Int, _ by0: Int, _ ps: Int, _ fx: Bool, _ fy: Bool, _ halo: Bool)
    { DrawAt(g, art, Double(col), row, bx0, by0, ps, fx, fy, halo) }

    func DrawAccessories(_ g: Graphics, _ bx0: Int, _ by0: Int, _ ps: Int, _ fx: Bool, _ dy: Int, _ normalFace: Bool)
    {
        let lv = Level()
        if lv >= 2 { DrawAt(g, Pet.SCARF, P.HatCol, P.ScarfRow + dy, bx0, by0, ps, fx, false, false) }
        if lv >= 4 && normalFace && !P.NoGlasses { DrawAt(g, Pet.GLASSES, P.HatCol, P.GlassRow + dy, bx0, by0, ps, fx, false, false) }
        if lv >= 5 && !Is("spidey") { DrawAt(g, Pet.BADGE, P.BadgeCol, P.BadgeRow + dy, bx0, by0, ps, fx, false, false) }
        var hat: [String]? = w.SeasonNow == "xmas" ? Pet.SANTA : (lv >= 6 ? Pet.CROWN : (lv >= 3 ? Pet.BEANIE : nil))
        if HatOnHead() || WearHat { hat = nil }      // 迪西：自己的帽子不換（借戴迪西帽子時也一樣）
        if let hat = hat
        {
            DrawAt(g, hat, P.HatCol, P.HatRow + dy - hat.count, bx0, by0, ps, fx, false, true)
            if P.KeepAntenna && P.AntThrough
            {
                // 丁丁：天線從帽子中間穿出來（照原位置重畫，不墊高，櫃子格子才放得下）
                let head = A("HEAD"); let n = head.count - 9
                if n > 0
                {
                    let ant = Array(head[0..<n])
                    DrawAt(g, ant, Double(12 - ant[0].utf8.count) / 2.0, P.HeadTop - n + dy, bx0, by0, ps, fx, false, true)
                }
            }
            else if P.KeepAntenna
            {
                // 小波的天線（圓圈）要露在帽子上面
                let head = A("HEAD"); let an = P.AntRows >= 0 ? P.AntRows : P.TopRows - 1
                if an > 0
                {
                    let ant = Array(head[0..<an])
                    DrawAt(g, ant, Double(12 - ant[0].utf8.count) / 2.0, P.HatRow + dy - hat.count - ant.count + 1, bx0, by0, ps, fx, false, true)
                }
            }
        }
        if w.SeasonNow == "cny" { DrawAt(g, Pet.ENVELOPE, 11, P.SideRow + dy, bx0, by0, ps, fx, false, true) }
        if w.SeasonNow == "birthday" { DrawAt(g, Pet.CAKE, 11, P.SideRow - 1 + dy, bx0, by0, ps, fx, false, true) }
    }

    // ---- Codex／Claude 狀態：小波顯示在肚子螢幕上，其他人在頭旁邊一個小圖示 ----
    static let IC_SUN = [ "y.y.y", ".yyy.", "yyyyy", ".yyy.", "y.y.y" ]
    static let IC_HEART = [ "pp.pp", "ppppp", ".ppp.", "..p.." ]
    static let IC_MOON = [ ".yyy", "yy..", "yy..", "yy..", ".yyy" ]
    static let IC_CHECK = [ "....W", "...W.", "W.W..", ".W..." ]
    static let IC_BANG = [ "S", "S", "S", ".", "S" ]

    func DrawStatusIcon(_ g: Graphics, _ st: String, _ cx: Int, _ cy: Int, _ u: Int, _ onScreen: Bool)
    {
        var art: [String]? = nil
        let pal = Night ? P.Night : P.Day
        if st == "busy"
        {
            // 三個點輪流亮
            let on = CInt(Math.Floor(w.Now * 3)) % 3
            for i in 0..<3
            {
                let b = SolidBrush(i == on ? Color.FromArgb(0x3D, 0x8B, 0xFF) : Color.FromArgb(onScreen ? 0x7A : 0x9A, 0x84, 0x90, 0xA8))
                g.FillRectangle(b, cx - 4 * u + i * 3 * u, cy - u / 2 - (i == on ? u / 2 : 0), 2 * u, 2 * u)
            }
            return
        }
        if st == "done" { art = Pet.IC_CHECK }
        else if st == "stuck" { art = Pet.IC_BANG }
        else if st == "night" { art = Pet.IC_MOON }
        else if st == "heart" { art = Pet.IC_HEART }
        else if st == "sun" { art = Pet.IC_SUN }
        guard let a = art else { return }
        let aw = a[0].utf8.count * u, ah = a.count * u
        let bg = st == "done" ? Color.FromArgb(0x2E, 0xA0, 0x5A) : (st == "stuck" ? Color.FromArgb(0xFF, 0xF1, 0xC2) : Color.Empty)
        if !onScreen && bg != Color.Empty
        { g.FillRectangle(SolidBrush(bg), cx - aw / 2 - u, cy - ah / 2 - u, aw + 2 * u, ah + 2 * u) }
        if onScreen && st == "done"
        { g.FillRectangle(SolidBrush(bg), cx - aw / 2 - u, cy - ah / 2 - u, aw + 2 * u, ah + 2 * u) }
        let b = SolidBrush(Color.White)
        for r in 0..<a.count
        {
            var c = 0
            for chb in a[r].utf8
            {
                if chb != 46
                {
                    let ch = Character(Unicode.Scalar(chb))
                    b.Color = pal.ContainsKey(ch) ? pal[ch] : Color.White
                    g.FillRectangle(b, cx - aw / 2 + c * u, cy - ah / 2 + r * u, u, u)
                }
                c += 1
            }
        }
    }

    func TummyStatus() -> String
    {
        let st = w.Status()
        if st != "" { return st }
        if Night { return "night" }
        return state == "hug" || hearts.Count > 0 ? "heart" : "sun"
    }

    // 小波的滑板車、人魚漢頓的搖椅、隱形船…（畫在身體後面的）
    func DrawBehind(_ g: Graphics, _ f: Fr, _ bx: Int, _ by: Int, _ ps: Int, _ fx: Bool)
    {
        if Is("po") && !scooterLost
        {
            if OnScooter() && !rolling { DrawAt(g, A("SCOOTER"), -1, 7, bx, by, ps, fx, false, true) }
            else if state == "idle" || state == "hug" || state == "wave" || state == "pose" || state == "dizzy" || state == "sleep" || state == "spin" || state == "think" || state == "plop"
            { DrawAt(g, A("SCOOTER"), 7, 7, bx, by, ps, !fx, false, true) } // 停在旁邊（車頭朝外）
        }
        if Is("stitch") && RidingStolen
        {
            let po = Pal.Get("po")
            if po != nil { DrawPixPal(g, po!, po!.Art["SCOOTER"], bx + (fx ? 12 - (-1) - 14 : -1) * ps, by + 7 * ps, ps, fx) }
        }
        if Is("hangyodon") && (caped || state == "capetrip" || (state == "pose" && poseKind == "hero"))
        {
            // 紅披風（飄在背後）
            let flap = Step2(caped ? 10 : 4)
            DrawAt(g, A("CAPE"), flap ? -4 : -3.5, 7, bx, by, ps, fx, false, true)
        }
        if Is("hangyodon") && state == "sleep" { DrawSleepBubble(g, bx, by, ps, false) }
        if P.Tubby { DrawTubbyBehind(g, f, bx, by, ps, fx) }
    }

    // 人魚漢頓睡在泡泡裡（先畫泡泡底，身體畫完再畫亮面）
    func DrawSleepBubble(_ g: Graphics, _ bx: Int, _ by: Int, _ ps: Int, _ front: Bool)
    {
        let dps = Double(ps)
        let cx = Double(bx) + 6 * dps, r = 9.5 * dps
        var cy = Double(by) + 9.5 * dps
        cy += Math.Sin(anim * 1.6) * dps * 0.5
        if !front
        { g.FillEllipse(SolidBrush(Color.FromArgb(Night ? 60 : 45, 170, 225, 255)), cx - r, cy - r, 2 * r, 2 * r) }
        else
        {
            g.DrawEllipse(Pen(Color.FromArgb(150, 200, 240, 255), Math.Max(1.5, dps * 0.45)), cx - r, cy - r, 2 * r, 2 * r)
            g.DrawArc(Pen(Color.FromArgb(200, 255, 255, 255), Math.Max(1.5, dps * 0.5)), cx - r * 0.75, cy - r * 0.75, r * 1.5, r * 1.5, 200.0, 50.0)
        }
    }

    func DrawPixPal(_ g: Graphics, _ pal: Pal, _ rows: [String], _ bx: Int, _ by: Int, _ ps: Int, _ fx: Bool)
    {
        let cols = Night ? pal.Night : pal.Day
        let b = SolidBrush(Color.Magenta)
        for ry in 0..<rows.count
        {
            let row = rows[ry].utf8
            let len = row.count
            var rx = 0
            for c in row
            {
                if c != 46
                {
                    let px = bx + (fx ? len - 1 - rx : rx) * ps
                    let ch = Character(Unicode.Scalar(c))
                    b.Color = cols.ContainsKey(ch) ? cols[ch] : Color.Magenta
                    g.FillRectangle(b, px, by + ry * ps, ps, ps)
                }
                rx += 1
            }
        }
    }

    // 球棒、手套、烏克麗麗、嘴裡的球（畫在身體前面的）
    func DrawFront(_ g: Graphics, _ f: Fr, _ bx: Int, _ by: Int, _ ps: Int, _ fx: Bool)
    {
        if Is("po")
        {
            if state == "bat"
            {
                if batT < 0.2 { DrawAt(g, Pet.BAT_UP, -1, 4, bx, by, ps, fx, false, true) }
                else if batT < 0.34 { DrawAt(g, Pet.BAT_FWD, 9, 10, bx, by, ps, fx, false, true) }
                else { DrawAt(g, Pet.BAT_FOLLOW, 9, 3, bx, by, ps, fx, false, true) }
                if w.Holder === self && batT < 0.22 { DrawAt(g, Pet.BALLART, 13 - batT * 10, 9, bx, by, ps, fx, false, true) }
            }
            if state == "pose" && poseKind == "homerun" { DrawAt(g, Pet.BAT_FOLLOW, 9, 3, bx, by, ps, fx, false, true) }
            if state == "catch" || state == "throw"
            {
                DrawAt(g, Pet.GLOVE, 11, 6, bx, by, ps, fx, false, true)
                if w.Holder === self { DrawAt(g, Pet.BALLART, 11, 5, bx, by, ps, fx, false, true) }
            }
        }
        if Is("stitch")
        {
            let uke = state == "elvis" || (Night && state == "idle") || (state == "pose" && poseKind == "uke")
            if uke { DrawAt(g, A("UKE"), 5, 8, bx, by, ps, fx, false, true) }
            if w.Holder === self && (state == "chomp" || state == "catch" || state == "throw" || state == "walk")
            { DrawAt(g, w.BallKind == "baseball" ? Pet.BALLART : Pet.TBALL, 4, state == "chomp" || state == "walk" ? (f.AccDy > 0 ? 11 : 6) : 3, bx, by, ps, fx, false, true) }
        }
        if Is("hangyodon") && state == "sleep" { DrawSleepBubble(g, bx, by, ps, true) }
        if Is("spidey") && w.Holder === self { DrawAt(g, w.BallKind == "baseball" ? Pet.BALLART : Pet.TBALL, 9, 4, bx, by, ps, fx, false, true) }
        if P.Tubby { DrawTubbyFront(g, f, bx, by, ps, fx) }
        if HoldToast && f.Rot == 0 && !f.Fy { DrawAt(g, Pet.TOAST, Is("po") ? 9.5 : 10.5, P.BodyTop + 1 + f.AccDy, bx, by, ps, fx, false, true) }
    }

    // ================= 一格一格畫到 layered window =================
    func Grow(_ l: inout Double, _ tp: inout Double, _ r: inout Double, _ b: inout Double, _ px: Double, _ py: Double)
    {
        l = Math.Min(l, px); r = Math.Max(r, px); tp = Math.Min(tp, py); b = Math.Max(b, py)
    }
    func SilkVisible() -> Bool { return state == "swing" || state == "hang" || state == "zip" || state == "shoot" || state == "webcatch" || state == "sling" }
    func Bob() -> Double { if P.Tubby { return TubbyBob() }; return state == "dance" || state == "elvis" ? Math.Abs(Math.Sin(anim * 8)) * 6 * k : (Is("hangyodon") && state == "walk" ? (Step2(4) ? k : 0) : 0) }

    func Render()
    {
        if !Out || w.Hidden { HideForms(); return }
        EnsureForms()
        let dS = Double(S), dSW = Double(SW), dSH = Double(SH)
        var l = x - 11 * dS, tp = y - 10 * dS, r = x + dSW + 11 * dS, b = y + dSH + 2 * dS
        if sc > 1 { let cxs = Cx; l = Math.Min(l, cxs - dSW * sc / 2 - 4 * dS); r = Math.Max(r, cxs + dSW * sc / 2 + 4 * dS); tp = Math.Min(tp, y + dSH - dSH * sc - 8 * dS * sc) }
        if SilkVisible() { Grow(&l, &tp, &r, &b, ax, ay) }
        if state == "sleep" { r = Math.Max(r, x + dSW + 26 * k); tp = Math.Min(tp, y - 36 * k) }
        if sense > 0 { l = Math.Min(l, Cx - 50 * k); r = Math.Max(r, Cx + 50 * k) }
        if hearts.Count > 0 || notes.Count > 0 { tp = Math.Min(tp, y - 90 * k) }
        for sp in sparks { Grow(&l, &tp, &r, &b, sp[0], sp[1]) }
        for f in flakes { Grow(&l, &tp, &r, &b, f[0], f[1]) }
        if w.Lead() === self && w.TicketCountdown() != nil { tp = Math.Min(tp, y - Double((P.TopRows + 16) * S)); l = Math.Min(l, Cx - 60 * k); r = Math.Max(r, Cx + 60 * k) }
        if P.Tubby || WearHat || HoldToast { tp = Math.Min(tp, y - Double((P.TopRows + (state == "juggle" || state == "hattoss" || state == "bagdig" ? 16 : 9)) * S)) }
        let pad = 6 + CInt(5 * k)
        let nb = Rectangle.FromLTRB(CInt(Math.Floor(l)) - pad, CInt(Math.Floor(tp)) - pad, CInt(Math.Ceiling(r)) + pad, CInt(Math.Ceiling(b)) + pad)
        if frameBmp == nil || frameBmp.Width != nb.Width || frameBmp.Height != nb.Height
        {
            if frameBmp != nil { frameBmp.Dispose() }
            frameBmp = Bitmap(Math.Max(1, nb.Width), Math.Max(1, nb.Height))
        }
        do
        {
            let g = Graphics.FromImage(frameBmp)
            g.Clear(Color.Transparent)
            PaintPet(g, nb.X, nb.Y)
            g.Dispose()
        }
        W.Present(Form, frameBmp, nb.X, nb.Y)
        if !W.Shown(Form) { Form.Show(); w.Zorder() }
        UpdateBubble()
    }

    func UpdateBubble()
    {
        EnsureForms()
        if Bt <= 0 || string.IsNullOrEmpty(bubble) || w.Hidden { if W.Shown(Bub) { Bub.Hide() }; return }
        let sz = Bub.Measure(bubble, bubbleAlert, Night ? P.NightBubble : 0, bubbleHint)
        var ancX: Double, above: Double
        if Out
        {
            ancX = Cx
            let dSH = Double(SH), dS = Double(S)
            var a = y + dSH - dSH * sc - Double(P.TopRows) * dS * sc
            a -= (state == "sleep" ? 30 * k : 0)
            a -= (hearts.Count > 0 ? 24 * k : 0)
            a -= ((Is("po") && OnScooter()) || RidingPo ? 4 * dS : 0)
            above = a
            if w.Lead() === self && w.TicketCountdown() != nil { above -= 11 * dS }   // 讓出搶票倒數徽章的位置
        }
        else
        {
            // 在櫃子裡：泡泡從格子上方冒出來
            var fxp = 0.0, fyp = 0.0; var ps = 0
            w.ShelfFoot(self, &fxp, &fyp, &ps)
            ancX = fxp; above = fyp - Double((17 + P.TopRows) * ps)
        }
        let wa = w.WA(ancX, above + 20)
        var bx = CInt(ancX - Double(sz.Width) / 2.0), by = CInt(above - Double(sz.Height) - 2)
        if Out && state == "hang" && hangPhase == 1 { by = CInt(y + Double(SH) + 6) }
        if Out && state == "ceil" { by = CInt(y + Double(SH) + 6) }
        bx = Math.Max(wa.Left, Math.Min(wa.Right - sz.Width, bx))
        by = Math.Max(wa.Top, Math.Min(wa.Bottom - sz.Height, by))
        let nb = Rectangle(bx, by, sz.Width, sz.Height)
        if Bub.Bounds != nb { Bub.Bounds = nb }
        if !W.Shown(Bub) { Bub.Show(); W.KeepOnTop(Bub) }
    }

    func PaintPet(_ g: Graphics, _ ox: Int, _ oy: Int)
    {
        g.SmoothingMode = SmoothingMode.AntiAlias
        let dox = Double(ox), doy = Double(oy), dS = Double(S), dSH = Double(SH), dSW = Double(SW)
        let lw = Math.Max(2, CInt(Math.Round(1.5 * k)))
        if SilkVisible()
        {
            var hx = Cx - dox, hy = y + 3 * k - doy, axo = ax - dox, ayo = ay - doy
            if state == "shoot"
            {
                let p = Math.Min(1.0, shootT / 0.18)
                axo = hx + (axo - hx) * p; ayo = hy + (ayo - hy) * p
            }
            if state == "sling" || state == "webcatch" { hy = y + 9 * k - doy; hx = Cx + Double(dir) * 5 * k - dox }
            let silk = Pen(Night ? Color.FromArgb(0x6A, 0x5F, 0x9E) : Color.FromArgb(0x9A, 0xA3, 0xBC), Double(lw))
            let core = Pen(Night ? Color.FromArgb(0x14, 0x14, 0x1C) : Color.FromArgb(0x4A, 0x52, 0x6E), Double(Math.Max(1, lw / 2)))
            g.DrawLine(silk, hx, hy, axo, ayo)
            g.DrawLine(core, hx, hy, axo, ayo)
            if state != "shoot" || shootT >= 0.18
            {
                let s = 5 * k, cxs = axo, cys = ayo
                g.DrawLine(silk, cxs - s, cys, cxs + s, cys)
                g.DrawLine(silk, cxs, cys - s, cxs, cys + s)
                g.DrawLine(silk, cxs - s * 0.7, cys - s * 0.7, cxs + s * 0.7, cys + s * 0.7)
                g.DrawLine(silk, cxs - s * 0.7, cys + s * 0.7, cxs + s * 0.7, cys - s * 0.7)
            }
        }

        let f = Frame()
        var sbx: Int, sby: Int, sps: Int
        if Math.Abs(sc - 1) > 0.001
        {
            sps = Math.Max(1, CInt(Math.Round(dS * sc)))
            let shake = knock > 0 ? -3 * k : 0
            sbx = CInt(Math.Round(Cx - 6 * Double(sps))) - ox; sby = CInt(Math.Round(y + dSH - 16 * Double(sps) + shake)) - oy
        }
        else { sps = S; sbx = CInt(Math.Round(x)) - ox; sby = CInt(Math.Round(y - Bob())) - oy }
        if state == "elvis" { sbx += (Step2(6) ? 1 : -1) * Math.Max(1, sps / 3) }
        let fx = dir < 0
        DrawFigure(g, f, sbx, sby, sps, fx, true)
        let dsps = Double(sps)

        // 原尺寸敲玻璃：手前面一圈小漣漪
        if state == "pose" && poseKind == "tap"
        {
            let ph = (anim * 1.6) % 1
            let rx = Cx - dox, ry = y + dSH * 0.45 - doy, rr = (4 + ph * 14) * k
            let rp = Pen(Color.FromArgb(CInt(170 * (1 - ph)), 255, 255, 255), Math.Max(1.5, k))
            let rp2 = Pen(Color.FromArgb(CInt(90 * (1 - ph)), 120, 150, 200), Math.Max(1.0, k * 0.6))
            g.DrawEllipse(rp2, rx - rr - 1, ry - rr * 0.6 - 1, 2 * rr + 2, rr * 1.2 + 2); g.DrawEllipse(rp, rx - rr, ry - rr * 0.6, 2 * rr, rr * 1.2)
        }
        // 第四面牆：小波臉貼玻璃起霧、史迪仔舔玻璃
        if state == "glass" && sc > 2
        {
            if HasTv
            {
                let fog = SolidBrush(Color.FromArgb(70, 255, 255, 255))
                let fo = (P.HeadTop + 1) * sps   // 小波 0；丁丁頭比較高
                g.FillEllipse(fog, sbx + 3 * sps, sby + 7 * sps + fo, 6 * sps, 3 * sps)
                g.FillEllipse(fog, sbx + 2 * sps, sby + 9 * sps + fo, 8 * sps, 3 * sps)
            }
            if Is("stitch") && gt > 0.8
            {
                let wet = SolidBrush(Color.FromArgb(55, 190, 225, 255))
                let lick = Math.Min(1.0, (gt - 0.8) / 1.2)
                g.FillEllipse(wet, Double(sbx + 3 * sps), Double(sby) + (8 - 6 * lick) * dsps, 5 * dsps, (3 + 6 * lick) * dsps)
            }
            if Is("hangyodon") && gt > 1.0
            {
                let lip = SolidBrush(Color.FromArgb(70, 245, 140, 170))   // 嘴唇印在玻璃上
                g.FillEllipse(lip, Double(sbx) + 1.5 * dsps, Double(sby) + 7.2 * dsps, 9 * dsps, 2.6 * dsps)
            }
        }

        // Codex／Claude 狀態小圖示（小波在肚子上，其他人在頭旁邊）
        if !HasTv && Math.Abs(sc - 1) < 0.001 && w.Lead() === self
        {
            let st = w.Status()
            if st != "" { DrawStatusIcon(g, st, CInt(x + dSW + 2 * dS) - ox, CInt(y - 1 * dS) - oy, Math.Max(1, S / 2), false) }
        }

        DrawTicketBadge(g, ox, oy)
        let fps = Math.Max(1, S / 3)
        for fl in flakes { DrawPix(g, Pet.FLAKE, CInt(fl[0]) - ox - fps, CInt(fl[1]) - oy - fps, fps, false, false, false) }

        if sense > 0 && !f.Fy
        {
            let p = Pen(Night ? Color.FromArgb(0x9B, 0x7B, 0xFF) : Color.FromArgb(0xC9, 0x54, 0x54), 2 * k)
            let cx = Cx - dox, cy = y + 10 * k - doy, wob = Math.Sin(anim * 30) * 1.5 * k
            for s in stride(from: -1, through: 1, by: 2)
            {
                let ds = Double(s)
                for i in 0..<3
                {
                    let di = Double(i)
                    let x1 = cx + ds * (22 + di * 5 + wob) * k, y1 = cy + (-10 + di * 6) * k
                    let x2 = cx + ds * (30 + di * 5 + wob) * k, y2 = cy + (-16 + di * 8) * k
                    g.DrawLine(p, x1, y1, x2, y2)
                }
            }
        }

        if state == "sleep"
        {
            let ps = Math.Max(2, S / 2)
            for i in 0..<3
            {
                let p = (z * 0.6 + Double(i) / 3.0) % 1
                if p > 0.85 { continue }
                DrawPix(g, Pet.ZZ, CInt(x + dSW - 4 * k + p * 16 * k) - ox, CInt(y - 2 * k - p * 30 * k) - oy, ps, false, false, false)
            }
        }

        let hp = Math.Max(2, S / 2)
        let dhp = Double(hp)
        for sp in sparks
        {
            if sp[4] < 0.6 || Math.Floor(sp[4] * 20) % 2 == 0
            { DrawPix(g, Pet.STAR, CInt(sp[0] - 1.5 * dhp) - ox, CInt(sp[1] - 1.5 * dhp) - oy, hp, false, false, false) }
        }
        for h in hearts
        {
            let age = h[1]
            let hx = CInt(Cx + h[0] + Math.Sin(age * 6 + h[0]) * 3 * k - 3.5 * dhp) - ox
            let hy = CInt(y - 8 * k - age * 45 * k - 6 * dhp) - oy
            DrawPix(g, Pet.HEART, hx, hy, hp, false, false, true)
        }
        for n in notes
        {
            let age = n[1]
            if n[2] == 7
            {
                // 史迪仔吃東西掉的屑屑
                let cb = SolidBrush(Color.FromArgb(0xC8, 0x93, 0x4E))
                g.FillRectangle(cb, (Cx + n[0]) - dox, (y + 9 * dS + age * 40 * k) - doy, Double(Math.Max(2, S / 2)), Double(Math.Max(2, S / 2)))
                continue
            }
            if n[2] == 5
            {
                let bxp = (Cx + n[0] * 1.6 + Math.Sin(age * 4 + n[0]) * 3 * k) - dox, byp = (y + 8 * k - age * 50 * k) - doy, rr = (1.6 + age * 1.2) * k
                if age < 1.5
                {
                    let bp = Pen(Color.FromArgb(200, 150, 215, 255), Math.Max(1.0, k * 0.9))
                    let hl = SolidBrush(Color.FromArgb(220, 255, 255, 255))
                    g.DrawEllipse(bp, bxp - rr, byp - rr, 2 * rr, 2 * rr); g.FillRectangle(hl, bxp - rr * 0.5, byp - rr * 0.6, Math.Max(1.0, rr * 0.4), Math.Max(1.0, rr * 0.4))
                }
                continue
            }
            let art = n[2] == 0 ? Pet.NOTE : (n[2] == 1 ? Pet.EXCL : (n[2] == 2 ? Pet.QUES : (n[2] == 3 ? Pet.ZZ : Pet.DROP)))
            let hx = CInt(Cx + n[0] + (n[2] == 0 ? Math.Sin(age * 5) * 6 * k : 0)) - ox
            let hy = CInt(y - 6 * k - age * (n[2] == 0 ? 40 : 18) * k) - oy
            if age < 1.5 || Math.Floor(age * 16) % 2 == 0 { DrawPix(g, art, hx, hy, hp, false, false, true) }
        }
    }

    // 畫一隻（身體＋前後道具＋配件＋肚子螢幕）；櫃子裡也用這個
    func DrawFigure(_ g: Graphics, _ f: Fr, _ sbx: Int, _ sby: Int, _ sps: Int, _ fx: Bool, _ extras: Bool)
    {
        // 圖一律貼齊 16 格框的底（比較高的角色往上長），Top 再額外上下移
        var rows = f.Rows
        var top = f.Top + 16 - rows.count
        var left = -(rows[0].utf8.count - 12) / 2
        if f.Rot != 0
        {
            rows = Pet.Rot90(rows, f.Rot)
            left = -(rows[0].utf8.count - 12) / 2
            top = (16 - rows.count) / 2 + 1
        }
        if extras { DrawBehind(g, f, sbx, sby, sps, fx) }
        DrawPix(g, rows, sbx + left * sps, sby + top * sps, sps, fx, f.Fy, true)
        if f.Acc && !f.Fy
        {
            let normalFace = state != "sleep" && state != "hug" && state != "dizzy"
            DrawAccessories(g, sbx, sby, sps, fx, f.AccDy, normalFace)
        }
        if f.Tummy && f.Rot == 0
        {
            let u = Math.Max(1, sps / 2)
            let scx = sbx + 6 * sps, scy = sby + CInt((P.TummyRow + Double(f.AccDy)) * Double(sps))
            DrawStatusIcon(g, TummyStatus(), scx, scy, u, true)
        }
        if extras { DrawFront(g, f, sbx, sby, sps, fx); DrawLunch(g, f, sbx, sby, sps, fx) }
    }
}

// ================= 公仔櫃 =================
// 右下角的木頭展示櫃：右邊一格高的（最愛）、左邊三格小的。點格子裡的公仔＝放出來／收回去。
final class ShelfForm: OverlayForm
{
    let w: World
    let U: Int, TU: Int           // 小格、高格的像素大小
    let k: Double
    var Hot = false, Over = false, Night = false
    var Tubby = false                   // 天線寶寶一櫃：格子裡是藍天綠山丘，大格有太陽寶寶
    var hover = -1
    var bmp: Bitmap! = nil, bg: Bitmap! = nil
    var bgKey = ""
    var area = Rectangle(0, 0, 0, 0)    // 螢幕座標
    var Area: Rectangle { return area }
    var cells = [Rectangle](repeating: Rectangle(0, 0, 0, 0), count: 4) // 本地座標（含名牌那條）
    var bW = 0, crown = 0, baseH = 0, div = 0, plateH = 0
    // ---- 收合成蛋 ----
    var Collapsed = false
    var fold = 0.0, gulp = 0.0, wobT = 0.0, nextWob = 4.0    // fold：0 櫃子 → 1 蛋
    var Attention = 0                     // 蛋上的小紅點（存著的通知、快到的提醒）
    var Lunch = false
    static let EGG = [
        "......kkkkkk......",
        ".....kccccssk.....",
        "....kchhYccssk....",
        "....khcYYYossk....",
        "...kchccYcccssk...",
        "...kccccccccssk...",
        "..kcccccccrrcssk..",
        "..kcccccccrrcssk..",
        "..kccccooccccssk..",
        ".kcccccoocccccssk.",
        ".kccbbccccccccssk.",
        ".kccbbcccccccossk.",
        ".kccccccccccccssk.",
        "..kcccccccggcssk..",
        "..kcccccccggcssk..",
        "..kcccrccccccssk..",
        "...kccccccccssk...",
        "...kccccccccssk...",
        "....kkkkkkkkkk...." ]
    var Animating: Bool { return (Collapsed ? fold < 1 : fold > 0) || gulp > 0 || wobT > 0 }
    var EggPs: Int { return TU }
    func EggLocal() -> Rectangle { let ps = EggPs; let ew = 18 * ps, eh = 19 * ps; return Rectangle(Area.Width - ew - 4, Area.Height - eh - 2, ew, eh) }
    func EggScreen() -> Rectangle { let r = EggLocal(); return Rectangle(r.X + Area.X, r.Y + Area.Y, r.Width, r.Height) }
    func TabLocal() -> Rectangle { let s = 5 * U; return Rectangle(Area.Width - s - 3 * U, 0, s, CInt(Double(crown) * 0.8)) }
    func Gulp() { gulp = 0.5; wobT = 0.7 }
    func SnapFold() { fold = Collapsed ? 1 : 0 }
    func Step(_ dt: Double)
    {
        let target: Double = Collapsed ? 1 : 0
        if fold < target { fold = Math.Min(target, fold + dt / 0.7) } else if fold > target { fold = Math.Max(target, fold - dt / 0.8) }
        if gulp > 0 { gulp -= dt }
        if wobT > 0 { wobT -= dt }
        if Collapsed && fold >= 1
        {
            nextWob -= dt
            if nextWob <= 0 { wobT = Attention > 0 ? 0.9 : 0.6; nextWob = Attention > 0 ? 2.5 : 6 + Random().NextDouble() * 6 }
        }
    }
    // 蛋的腳（公仔收進蛋裡的位置）
    func EggFoot() -> Point { let r = EggScreen(); return Point(r.X + r.Width / 2, r.Y + r.Height * 2 / 3) }

    init(_ w: World, _ S: Int)
    {
        self.w = w
        U = Math.Max(2, S * 3 / 4); TU = S
        k = Double(S) / 3.0
        super.init(false, true)
        Cursor = Cursors.Hand
    }

    override func OnPaint(_ e: PaintEventArgs) { }
    override func OnPaintBackground(_ e: PaintEventArgs) { }

    func Place(_ wa: Rectangle)
    {
        bW = 3 * U; crown = 5 * U; baseH = 5 * U; div = 2 * U; plateH = 5 * U
        let smallW = 24 * U, smallH = 33 * U, tallW = 24 * TU, tallH = 3 * smallH + 2 * div
        let W = bW * 2 + smallW + div + tallW, H = crown + tallH + baseH
        area = Rectangle(wa.Right - W - 6, wa.Bottom - H, W, H)
        cells[0] = Rectangle(bW + smallW + div, crown, tallW, tallH)
        for i in 0..<3 { cells[i + 1] = Rectangle(bW, crown + i * (smallH + div), smallW, smallH) }
    }

    func CellPs(_ i: Int) -> Int { return i == 0 ? TU : U }
    // 依公仔實際高度（天線、耳朵、頭鰭、帽子、晃動）縮放，保證離格子頂端至少 2px
    func FitPs(_ i: Int, _ p: Pet?) -> Int
    {
        var ps = CellPs(i)
        guard let p = p else { return ps }
        let avail = cells[i].Height - plateH - U - (i == 0 ? PedH() : 0) - 2 - 2
        let rows = p.ShelfRows()
        while ps > 2 && rows * ps > avail { ps -= 1 }
        return ps
    }
    func CellScreen(_ i: Int) -> Rectangle { let c = cells[i]; return Rectangle(c.X + Area.X, c.Y + Area.Y, c.Width, c.Height) }
    // 公仔腳踩的位置（螢幕座標）
    func Foot(_ i: Int) -> Point { let c = CellScreen(i); return Point(c.X + c.Width / 2, c.Bottom - plateH - U - (i == 0 ? PedH() : 0)) }
    func PedH() -> Int { return CInt(Double(cells[0].Height - plateH) * 0.2) }

    func CellAt(_ screen: Point) -> Int
    {
        if Collapsed { return -1 }
        for i in 0..<4 { if CellScreen(i).Contains(screen) { return i } }
        return -1
    }

    override func OnMouseDown(_ e: MouseEventArgs)
    {
        super.OnMouseDown(e)
        if e.Button == MouseButtons.Left { ClickAt(ShelfForm.CursorPos(), e.Button) }
    }
    override func OnMouseUp(_ e: MouseEventArgs)
    {
        super.OnMouseUp(e)
        if e.Button == MouseButtons.Right { let cp = ShelfForm.CursorPos(); App.LogAlways("menu: right-up on shelf at {X=\(cp.X),Y=\(cp.Y)} collapsed=\(Collapsed ? "True" : "False")"); ClickAt(cp, e.Button) }   // 右鍵放開才叫選單
    }
    // mac: inside a Form, `Cursor` names the instance property; reach the static Cursor.Position here
    static func CursorPos() -> Point { return CursorT.Position }

    // 點櫃子（真的滑鼠或測試用 act click 都走這裡）
    func ClickAt(_ screen: Point, _ b: MouseButtons)
    {
        let p = Point(screen.X - Area.X, screen.Y - Area.Y)
        if Collapsed
        {
            if !EggLocal().Contains(p) { return }
            if b == MouseButtons.Left { w.ToggleEgg(false) } else if b == MouseButtons.Right { w.ShelfMenu(-1, self) }
            return
        }
        if b == MouseButtons.Left && TabLocal().Contains(p) { w.ToggleEgg(true); return }
        let c = CellAt(screen)
        if c < 0 { return }
        if b == MouseButtons.Left { w.ShelfClick(c) }
        else if b == MouseButtons.Right { w.ShelfMenu(c, self) }
    }
    override func OnMouseMove(_ e: MouseEventArgs) { super.OnMouseMove(e); hover = CellAt(ShelfForm.CursorPos()) }
    override func OnMouseLeave(_ e: EventArgs) { super.OnMouseLeave(e); hover = -1 }

    static func C(_ rgb: Int) -> Color { return Color.FromArgb((rgb >> 16) & 255, (rgb >> 8) & 255, rgb & 255) }
    static func Mix(_ a: Color, _ b: Color, _ f: Double) -> Color
    {
        let r = CInt(Double(a.R) + Double(b.R - a.R) * f), gg = CInt(Double(a.G) + Double(b.G - a.G) * f), bb = CInt(Double(a.B) + Double(b.B - a.B) * f)
        return Color.FromArgb(r, gg, bb)
    }
    func C(_ rgb: Int) -> Color { return ShelfForm.C(rgb) }
    func Mix(_ a: Color, _ b: Color, _ f: Double) -> Color { return ShelfForm.Mix(a, b, f) }

    static func RoundRect(_ r: RectangleF, _ rad: Double) -> GraphicsPath
    {
        let p = GraphicsPath()
        let d = rad * 2
        p.AddArc(r.X, r.Y, d, d, 180, 90)
        p.AddArc(r.Right - d, r.Y, d, d, 270, 90)
        p.AddArc(r.Right - d, r.Bottom - d, d, d, 0, 90)
        p.AddArc(r.X, r.Bottom - d, d, d, 90, 90)
        p.CloseFigure()
        return p
    }
    func RoundRect(_ r: RectangleF, _ rad: Double) -> GraphicsPath { return ShelfForm.RoundRect(r, rad) }

    // 櫃子本體（不會動的部分）先畫好存起來
    func BuildBg(_ who: [Pet?], _ outNow: [Bool])
    {
        let W = Area.Width, H = Area.Height
        let dW = Double(W), dH = Double(H), dU = Double(U), dcrown = Double(crown), dplateH = Double(plateH)
        if bg == nil || bg.Width != W || bg.Height != H { if bg != nil { bg.Dispose() }; bg = Bitmap(W, H) }
        let g = Graphics.FromImage(bg)
        defer { g.Dispose() }
        g.Clear(Color.Transparent)
        g.SmoothingMode = SmoothingMode.AntiAlias
        let w1 = Night ? C(0x5C3B24) : C(0x9A6338), w2 = Night ? C(0x3C2617) : C(0x6B4024), w3 = Night ? C(0x74503A) : C(0xB97F4E)
        // 影子
        g.FillPath(SolidBrush(Color.FromArgb(60, 0, 0, 0)), RoundRect(RectangleF(3, 4, dW - 4, dH - 4), 5 * dU))
        // 櫃身
        let body = RectangleF(1, dcrown * 0.35, dW - 3, dH - dcrown * 0.35 - 2)
        g.FillPath(LinearGradientBrush(body, w1, w2, 90.0), RoundRect(body, 3 * dU))
        // 木紋
        let r = Random(5)
        do
        {
            let grain = Pen(Color.FromArgb(Night ? 26 : 34, 40, 20, 8), Math.Max(1.0, dU * 0.35))
            for _ in 0..<14
            {
                let gx = r.NextDouble() * dW, gy = dcrown + r.NextDouble() * (dH - dcrown * 2)
                g.DrawBezier(grain, gx, gy, gx + 6 * dU, gy - dU, gx + 12 * dU, gy + dU, gx + 18 * dU, gy)
            }
        }
        // 頂蓋（冠線）
        let top = RectangleF(0, 0, dW - 1, dcrown)
        g.FillPath(LinearGradientBrush(top, w3, w1, 90.0), RoundRect(top, 2 * dU))
        g.DrawLine(Pen(Color.FromArgb(Night ? 50 : 90, 255, 230, 200), Math.Max(1.0, dU * 0.5)), 3 * dU, dU, dW - 3 * dU, dU)
        g.DrawLine(Pen(Color.FromArgb(120, 30, 15, 5), Math.Max(1.0, dU * 0.5)), dU, dcrown - dU * 0.3, dW - dU, dcrown - dU * 0.3)
        // 底座＋小腳
        let bas = RectangleF(0, dH - Double(baseH) - 1, dW - 1, Double(baseH - U))
        g.FillPath(LinearGradientBrush(bas, w3, w2, 90.0), RoundRect(bas, 1.5 * dU))
        do
        {
            let ft = SolidBrush(w2)
            g.FillRectangle(ft, 3 * U, H - 2 * U, 4 * U, 2 * U)
            g.FillRectangle(ft, W - 7 * U, H - 2 * U, 4 * U, 2 * U)
        }
        // 每一格
        for i in 0..<4
        {
            let c = cells[i]
            let pet = who[i]
            var panel = pet != nil ? pet!.P.Panel : C(0xEDE6DA)
            if Night { panel = Mix(panel, C(0x2A2238), 0.55) }
            let inner = RectangleF(Double(c.X), Double(c.Y), Double(c.Width), Double(c.Height - plateH))
            g.FillRectangle(LinearGradientBrush(inner, Mix(panel, Color.White, 0.35), Mix(panel, C(0x6B4A30), 0.25), 90.0), inner)
            if Tubby { DrawHills(g, inner, i == 0) }
            // 頂上的展示燈
            do
            {
                let gp = GraphicsPath()
                let glow = RectangleF(inner.X - inner.Width * 0.2, inner.Y - inner.Height * 0.25, inner.Width * 1.4, inner.Height * 0.75)
                gp.AddEllipse(glow)
                let pg = PathGradientBrush(gp)
                pg.CenterColor = Night ? Color.FromArgb(120, 255, 214, 150) : Color.FromArgb(110, 255, 250, 235)
                pg.SurroundColors = [ Color.FromArgb(0, 255, 240, 220) ]
                g.SetClip(inner)
                g.FillPath(pg, gp)
                g.ResetClip()
            }
            // 內側陰影（凹進去的感覺）
            g.FillRectangle(LinearGradientBrush(RectangleF(inner.X, inner.Y, inner.Width, 3 * dU + 1), Color.FromArgb(90, 40, 20, 5), Color.FromArgb(0, 40, 20, 5), 90.0), inner.X, inner.Y, inner.Width, 3 * dU)
            g.FillRectangle(LinearGradientBrush(RectangleF(inner.X, inner.Y, 2 * dU + 1, inner.Height), Color.FromArgb(70, 40, 20, 5), Color.FromArgb(0, 40, 20, 5), 0.0), inner.X, inner.Y, 2 * dU, inner.Height)
            if i == 0 { DrawPedestal(g, c, panel) }
            // 層板（公仔站的地方）＋名牌那條
            let board = RectangleF(Double(c.X - U), Double(c.Bottom - plateH), Double(c.Width + 2 * U), dplateH)
            g.FillRectangle(LinearGradientBrush(board, w3, w1, 90.0), board)
            g.DrawLine(Pen(Color.FromArgb(Night ? 60 : 110, 255, 235, 205), Math.Max(1.0, dU * 0.4)), board.X, board.Y + 0.5, board.Right, board.Y + 0.5)
            // 名牌
            let name = pet == nil ? "？" : (i == 0 ? "★ " + pet!.P.Name : pet!.P.Name)
            do
            {
                let f = Font("Microsoft JhengHei UI", Math.Max(9.0, 6.6 * k), FontStyle.Bold, GraphicsUnit.Pixel)
                let ts = g.MeasureString(name, f)
                let pw = Math.Min(Double(c.Width) - 2 * dU, ts.Width + 3 * dU), ph = dplateH - 1.6 * dU
                let pr = RectangleF(Double(c.X) + (Double(c.Width) - pw) / 2, Double(c.Bottom - plateH) + 0.9 * dU, pw, ph)
                let pp = RoundRect(pr, dU * 0.8)
                let brass = LinearGradientBrush(pr, i == 0 ? C(0xF6D77A) : C(0xEBCB7E), i == 0 ? C(0xC08A2C) : C(0xB48A45), 90.0)
                let rim = Pen(Color.FromArgb(160, 90, 60, 15), 1.0)
                g.FillPath(brass, pp)
                g.DrawPath(rim, pp)
                g.TextRenderingHint = TextRenderingHint.AntiAlias
                let sf = StringFormat()
                let tb = SolidBrush(C(0x4A3010))
                sf.Alignment = StringAlignment.Center; sf.LineAlignment = StringAlignment.Center; sf.Trimming = StringTrimming.None
                g.DrawString(name, f, tb, RectangleF(pr.X - 4, pr.Y + 0.5, pr.Width + 8, pr.Height), sf)
            }
        }
        // 左右小格和高格之間的隔板線
        let dk = Pen(Color.FromArgb(90, 30, 15, 5), 1.0)
        g.DrawLine(dk, Double(cells[0].X) - Double(div) / 2, dcrown, Double(cells[0].X) - Double(div) / 2, Double(H - baseH))
    }


    // ---- 天線寶寶一櫃的格子：藍天、綠色小山丘、小花；大格有太陽寶寶（晚上下山）----
    func HillTop(_ inner: RectangleF, _ tall: Bool) -> Double { return inner.Bottom - inner.Height * (tall ? 0.30 : 0.27) }
    func DrawHills(_ g: Graphics, _ inner: RectangleF, _ tall: Bool)
    {
        let st = g.Save()
        g.SetClip(inner)
        let sky1 = Night ? C(0x4A3A6A) : C(0xB8E0FF), sky2 = Night ? C(0xA8707A) : C(0xEEF8FF)
        g.FillRectangle(LinearGradientBrush(inner, sky1, sky2, 90.0), inner)
        let hy = HillTop(inner, tall)
        let h1 = Night ? C(0x557E4C) : C(0x92D46C), h2 = Night ? C(0x3A5C36) : C(0x66B248), rim = Night ? C(0x74A066) : C(0xC0EC98)
        // 後面一座淡淡的
        g.FillEllipse(SolidBrush(Mix(h1, sky2, 0.5)), inner.X - inner.Width * 0.55, hy - inner.Height * 0.07, inner.Width * 1.25, inner.Height * 0.5)
        let hill = RectangleF(inner.X - inner.Width * 0.25, hy, inner.Width * 1.5, inner.Height * 0.62)
        g.FillEllipse(LinearGradientBrush(RectangleF(hill.X, hill.Y - 1, hill.Width, hill.Height + 2), h1, h2, 90.0), hill)
        g.DrawArc(Pen(rim, Math.Max(1.0, Double(U) * 0.5)), hill, 215, 110)
        // 小花（像素點）
        let r = Random(tall ? 3 : 11)
        let fl = [ Color.White, C(0xFFD84A), C(0xFF8FB0), C(0xE8E0FF) ]
        let u = Math.Max(1.0, Double(U) * 0.6), a = hill.Width / 2, bb = hill.Height / 2, cxh = hill.X + a, cyh = hill.Y + bb
        let n = tall ? 7 : 4
        for i in 0..<n
        {
            let fx = inner.X + (0.08 + 0.84 * (Double(i) + r.NextDouble() * 0.8) / Double(n)) * inner.Width
            let q = (fx - cxh) / a; if Math.Abs(q) >= 1 { continue }
            let top = cyh - bb * Math.Sqrt(1 - q * q)
            let fy = top + (0.25 + r.NextDouble() * 0.55) * (inner.Bottom - top)
            let c0 = fl[r.Next(fl.count)]
            let pb = SolidBrush(Night ? Mix(c0, C(0x3A3050), 0.45) : c0)
            g.FillRectangle(pb, fx - u, fy, u, u); g.FillRectangle(pb, fx + u, fy, u, u)
            g.FillRectangle(pb, fx, fy - u, u, u); g.FillRectangle(pb, fx, fy + u, u, u)
            g.FillRectangle(SolidBrush(Night ? C(0xB08A3C) : C(0xF5A623)), fx, fy, u, u)
        }
        g.Restore(st)
    }

    // 太陽寶寶：白天在天上笑，晚上一半沉到山丘後面
    func DrawSunBaby(_ g: Graphics, _ c: Rectangle, _ cx0: Double, _ sy: Double, _ sr: Double)
    {
        var cx = cx0
        let inner = RectangleF(Double(c.X), Double(c.Y), Double(c.Width), Double(c.Height - plateH))
        let hy = HillTop(inner, true)
        let r = sr * 0.5, y0 = Night ? hy - r * 0.15 : sy
        if Night { cx -= Double(c.Width) * 0.24 }   // 晚上在山丘邊慢慢下山（不要躲在圓台後面）
        let st = g.Save()
        g.SetClip(RectangleF(inner.X, inner.Y, inner.Width, hy + 1 - inner.Y))
        let ray = Night ? Color.FromArgb(150, 255, 150, 90) : Color.FromArgb(170, 255, 214, 74)
        let rp = Pen(ray, Math.Max(1.5, Double(U) * 0.9))
        for i in 0..<12
        {
            let ang = Double(i) * Math.PI / 6 + 0.13
            g.DrawLine(rp, cx + Math.Cos(ang) * r * 1.25, y0 + Math.Sin(ang) * r * 1.25, cx + Math.Cos(ang) * r * 1.65, y0 + Math.Sin(ang) * r * 1.65)
        }
        g.FillEllipse(SolidBrush(Night ? C(0xF0965A) : C(0xFFD84A)), cx - r, y0 - r, 2 * r, 2 * r)
        let fr = r * 0.66
        g.FillEllipse(SolidBrush(Night ? C(0xE8B892) : C(0xFBE3C6)), cx - fr, y0 - fr, 2 * fr, 2 * fr)
        let e = Math.Max(1.5, fr * 0.16)
        let kb = SolidBrush(C(0x5A3A2A))
        if Night
        {
            let sp = Pen(C(0x5A3A2A), Math.Max(1.0, e * 0.6))
            g.DrawLine(sp, cx - fr * 0.5, y0 - fr * 0.15, cx - fr * 0.2, y0 - fr * 0.15); g.DrawLine(sp, cx + fr * 0.2, y0 - fr * 0.15, cx + fr * 0.5, y0 - fr * 0.15)
        }
        else { g.FillEllipse(kb, cx - fr * 0.42 - e / 2, y0 - fr * 0.25, e, e * 1.2); g.FillEllipse(kb, cx + fr * 0.42 - e / 2, y0 - fr * 0.25, e, e * 1.2) }
        g.DrawArc(Pen(C(0xC0504A), Math.Max(1.0, e * 0.6)), cx - fr * 0.35, y0 - fr * 0.05, fr * 0.7, fr * 0.55, 20.0, 140.0)
        let pk = SolidBrush(Color.FromArgb(110, 255, 130, 130))
        g.FillEllipse(pk, cx - fr * 0.78, y0 + fr * 0.1, fr * 0.3, fr * 0.2); g.FillEllipse(pk, cx + fr * 0.48, y0 + fr * 0.1, fr * 0.3, fr * 0.2)
        g.Restore(st)
    }

    // 高格：最愛站的小圓台＋背板上淡淡的大星星
    func DrawPedestal(_ g: Graphics, _ c: Rectangle, _ panel: Color)
    {
        let dU = Double(U)
        let cx = Double(c.X) + Double(c.Width) / 2, ph = Double(PedH()), floor = Double(c.Bottom - plateH), top = floor - ph
        let pw = Double(c.Width) * 0.62, eh = 4 * dU
        // 星星
        var star = [PointF]()
        let sr = Double(c.Width) * 0.36, sy = Double(c.Y) + (top - Double(c.Y)) * 0.42
        for i in 0..<10
        {
            let a = -Math.PI / 2 + Double(i) * Math.PI / 5, rr = i % 2 == 0 ? sr : sr * 0.45
            star.append(PointF(cx + Math.Cos(a) * rr, sy + Math.Sin(a) * rr))
        }
        if Tubby { DrawSunBaby(g, c, cx, sy, sr) }
        else
        { g.FillPolygon(SolidBrush(Night ? Color.FromArgb(40, 255, 220, 150) : Color.FromArgb(70, 255, 236, 180)), star) }
        // 圓台
        let m1 = Night ? C(0x8A7A70) : C(0xFFF6E8), m2 = Night ? C(0x4E443F) : C(0xD9C7AE)
        let bodyR = RectangleF(cx - pw / 2, top, pw, ph - dU * 0.5)
        do
        {
            let lb = LinearGradientBrush(RectangleF(bodyR.X - 1, bodyR.Y, bodyR.Width + 2, bodyR.Height), m2, m1, 0.0)
            let cb = ColorBlend()
            cb.Colors = [ m2, m1, m1, m2 ]
            cb.Positions = [ 0.0, 0.35, 0.55, 1.0 ]
            lb.InterpolationColors = cb
            g.FillRectangle(lb, bodyR)
            g.FillEllipse(lb, bodyR.X, bodyR.Bottom - eh / 2, bodyR.Width, eh)
        }
        g.FillRectangle(SolidBrush(Night ? C(0xB08A3C) : C(0xE2B550)), bodyR.X, top + eh * 0.45, bodyR.Width, dU * 0.9)
        g.FillEllipse(SolidBrush(Night ? C(0x9C8B80) : C(0xFFFBF3)), bodyR.X, top - eh / 2, bodyR.Width, eh)
        g.DrawEllipse(Pen(Night ? C(0xB08A3C) : C(0xD9A944), Math.Max(1.0, dU * 0.5)), bodyR.X, top - eh / 2, bodyR.Width, eh)
    }

    // 每 0.1 秒左右重畫（公仔會呼吸、眨眼、晃一下）
    func Render(_ who: [Pet?], _ outNow: [Bool], _ t: Double)
    {
        let b = Snapshot(who, outNow, t)
        W.Present(self, b, Area.X, Area.Y)
    }

    var cab: Bitmap! = nil
    @discardableResult
    func Snapshot(_ who: [Pet?], _ outNow: [Bool], _ t: Double) -> Bitmap
    {
        if fold <= 0.001 { let b0 = Cabinet(who, outNow, t); DrawTab(b0); return b0 }
        let full = Cabinet(who, outNow, t)
        if cab == nil || cab.Width != full.Width || cab.Height != full.Height { if cab != nil { cab.Dispose() }; cab = Bitmap(full.Width, full.Height) }
        let g = Graphics.FromImage(cab)
        defer { g.Dispose() }
        g.Clear(Color.Transparent)
        let e = fold * fold * (3 - 2 * fold)
        // 櫃子往下折、變淡
        if e < 0.999
        {
            let h = CInt(Math.Round(Double(full.Height) * (1 - e)))
            if h > 0
            {
                let cm = ColorMatrix(); cm.Matrix33 = 1 - e
                let ia = ImageAttributes()
                ia.SetColorMatrix(cm)
                g.InterpolationMode = InterpolationMode.NearestNeighbor
                g.DrawImage(full, Rectangle(0, full.Height - h, full.Width, h), 0, 0, full.Width, full.Height, GraphicsUnit.Pixel, ia)
            }
        }
        // 蛋：慢慢出現、上半部蓋下來
        DrawEgg(g, t, e)
        return cab
    }

    // 收合鈕「－」（櫃子頂上右邊的小牌子）
    func DrawTab(_ b: Bitmap)
    {
        let g = Graphics.FromImage(b)
        defer { g.Dispose() }
        g.SmoothingMode = SmoothingMode.AntiAlias
        let r = TabLocal()
        let p = RoundRect(RectangleF(Double(r.X), Double(r.Y + 1), Double(r.Width), Double(r.Height - 2)), Double(U))
        g.FillPath(SolidBrush(Color.FromArgb(220, 255, 246, 226)), p); g.DrawPath(Pen(Color.FromArgb(160, 120, 80, 40), 1.0), p)
        let mp = Pen(Color.FromArgb(0x8A, 0x5A, 0x2A), Math.Max(1.5, Double(U) * 0.6))
        g.DrawLine(mp, Double(r.X) + Double(r.Width) * 0.28, Double(r.Y) + Double(r.Height) / 2, Double(r.X) + Double(r.Width) * 0.72, Double(r.Y) + Double(r.Height) / 2)
    }

    func DrawEgg(_ g: Graphics, _ t: Double, _ appear: Double)
    {
        if appear <= 0.02 { return }
        let ps = EggPs
        let dps = Double(ps), dU = Double(U)
        let er = EggLocal()
        // 搖一搖（有通知存著時搖比較大）
        var ang = 0.0
        if wobT > 0 { ang = Math.Sin(wobT * 26) * Double(Attention > 0 ? 11 : 6) * Math.Min(1.0, wobT * 2) }
        // 打開的程度：收合動畫的頭尾、吞公仔時裂開
        var open = Math.Max(Math.Max(0.0, 1 - appear) * 1.6, gulp > 0 ? Math.Sin(gulp / 0.5 * Math.PI) * 0.6 : 0)
        open = Math.Min(1.0, open)
        let st = g.Save()
        g.TranslateTransform(Double(er.X) + Double(er.Width) / 2, Double(er.Bottom))
        g.RotateTransform(ang)
        g.TranslateTransform(-Double(er.Width) / 2, -Double(er.Height))
        let crack = 8
        var pal = [Character: Color]()
        pal["k"] = Color.FromArgb(0x6B, 0x4A, 0x2E); pal["c"] = Night ? Color.FromArgb(0xE6, 0xDA, 0xC4) : Color.FromArgb(0xFF, 0xF4, 0xDC)
        pal["s"] = Night ? Color.FromArgb(0xC2, 0xAE, 0x92) : Color.FromArgb(0xE8, 0xD3, 0xB0); pal["h"] = Color.White
        pal["r"] = Color.FromArgb(0xD8, 0x4A, 0x4A); pal["o"] = Color.FromArgb(0xE7, 0x83, 0x6A); pal["b"] = Color.FromArgb(0x3D, 0x6B, 0xB3)
        pal["g"] = Color.FromArgb(0x25, 0xB3, 0xBA); pal["Y"] = Color.FromArgb(0xF5, 0xC8, 0x42)
        let alpha = CInt(255 * Math.Min(1.0, appear * 1.4))
        // 下半部
        for r in crack..<ShelfForm.EGG.count { DrawEggRow(g, r, 0, 0, ps, pal, alpha) }
        // 上半部：打開時往上抬、往旁邊歪
        let lift = open * 7 * dps, tilt = open * 4 * dps
        for r in 0..<crack { DrawEggRow(g, r, -tilt, -lift, ps, pal, alpha) }
        // 裂痕
        if open > 0.05 || appear < 0.95
        {
            let cp = Pen(Color.FromArgb(alpha, 0x6B, 0x4A, 0x2E), Math.Max(1.5, dps * 0.45))
            var z = [PointF]()
            for i in 0..<8 { z.append(PointF(Double(2 * ps + i * 2 * ps), (Double(crack) + (i % 2 == 0 ? 0 : 0.7)) * dps)) }
            g.DrawLines(cp, z)
        }
        // 午餐時間：小餐巾
        if Lunch
        {
            let nb = SolidBrush(Color.FromArgb(alpha, 255, 255, 255))
            let ck = SolidBrush(Color.FromArgb(alpha, 0xE2, 0x4A, 0x4A))
            let tri = [ PointF(5 * dps, 9 * dps), PointF(13 * dps, 9 * dps), PointF(9 * dps, 14 * dps) ]
            g.FillPolygon(nb, tri)
            g.DrawPolygon(Pen(Color.FromArgb(alpha, 0xB8, 0xA8, 0x90), Math.Max(1.0, dps * 0.3)), tri)
            for i in 0..<4 { g.FillRectangle(ck, (6 + i * 2) * ps, 9 * ps, ps, ps) }
            g.FillRectangle(ck, 8 * ps, 11 * ps, ps, ps); g.FillRectangle(ck, 10 * ps, 11 * ps, ps, ps)
        }
        g.Restore(st)
        // 小紅點：有存著的通知／快到的提醒
        if Attention > 0 && appear > 0.9
        {
            let d = 6 * dU, bx = Double(er.Right) - d * 0.8, by = Double(er.Y) + d * 0.2
            g.FillEllipse(SolidBrush(Color.FromArgb(0xE2, 0x3B, 0x3B)), bx, by, d, d)
            g.DrawEllipse(Pen(Color.White, 1.5), bx, by, d, d)
            let f = Font("Arial", d * 0.62, FontStyle.Bold, GraphicsUnit.Pixel)
            let sf = StringFormat()
            sf.Alignment = StringAlignment.Center; sf.LineAlignment = StringAlignment.Center
            g.TextRenderingHint = TextRenderingHint.AntiAlias
            g.DrawString(Attention > 9 ? "9+" : String(Attention), f, Brushes.White, RectangleF(bx, by + 0.5, d, d), sf)
        }
        if Hot && appear > 0.9
        {
            let hp = Pen(Over ? Color.FromArgb(230, 255, 120, 165) : Color.FromArgb(170, 255, 200, 120), Math.Max(2.0, dU))
            g.DrawEllipse(hp, Double(er.X - 2 * U), Double(er.Y - 2 * U), Double(er.Width + 4 * U), Double(er.Height + 4 * U))
        }
        // 番茄／安靜徽章掛在蛋上面
        let left = w.FocusLeft(), qleft = w.QuietLeft()
        let bcx = Double(er.X) + Double(er.Width) / 2, bcy = Double(er.Y) - 3 * dU
        if left >= 0 && qleft >= 0 { DrawBadgeAt(g, qleft, true, bcx, bcy); DrawBadgeAt(g, left, false, bcx, bcy - 8 * dU) }
        else if left >= 0 { DrawBadgeAt(g, left, false, bcx, bcy) }
        else if qleft >= 0 { DrawBadgeAt(g, qleft, true, bcx, bcy) }
    }

    func DrawEggRow(_ g: Graphics, _ r: Int, _ dx: Double, _ dy: Double, _ ps: Int, _ pal: [Character: Color], _ alpha: Int)
    {
        let row = ShelfForm.EGG[r]
        let dps = Double(ps)
        let b = SolidBrush(Color.White)
        var c = 0
        for ch in row
        {
            if ch != "."
            {
                let col = pal[ch]!
                b.Color = Color.FromArgb(alpha, col)
                g.FillRectangle(b, dx + Double(c) * dps, dy + Double(r) * dps, dps, dps)
            }
            c += 1
        }
    }

    func Cabinet(_ who: [Pet?], _ outNow: [Bool], _ t: Double) -> Bitmap
    {
        var key = "\(Night)|\(Tubby)|\(Area.Width)x\(Area.Height)"
        for i in 0..<4 { key += "|" + (who[i] == nil ? "-" : who[i]!.P.Id) }
        if key != bgKey || bg == nil { bgKey = key; BuildBg(who, outNow) }
        if bmp == nil || bmp.Width != bg.Width || bmp.Height != bg.Height { if bmp != nil { bmp.Dispose() }; bmp = Bitmap(bg.Width, bg.Height) }
        let g = Graphics.FromImage(bmp)
        defer { g.Dispose() }
        let dU = Double(U)
        g.Clear(Color.Transparent)
        g.DrawImageUnscaled(bg, 0, 0)
        g.SmoothingMode = SmoothingMode.AntiAlias
        for i in 0..<4
        {
            let c = cells[i]
            let pet = who[i]
            let ps = FitPs(i, pet)
            let fx = c.X + c.Width / 2, fy = c.Bottom - plateH - U - (i == 0 ? PedH() : 0)
            g.SetClip(Rectangle(c.X, c.Y, c.Width, c.Height - plateH))
            if pet == nil { DrawUnknown(g, fx, fy, ps) }
            else if outNow[i] { pet!.DrawGhost(g, fx, fy, ps, Night); DrawAway(g, c, ps) }
            else { pet!.DrawOnShelf(g, fx, fy, ps, c, t) }
            g.ResetClip()
            if hover == i && pet != nil
            {
                let hp = Pen(Color.FromArgb(150, 255, 236, 160), Math.Max(2.0, dU * 0.7))
                g.DrawRectangle(hp, c.X + 1, c.Y + 1, c.Width - 3, c.Height - plateH - 2)
            }
        }
        // 玻璃門的反光
        do
        {
            let gl = Pen(Color.FromArgb(Night ? 14 : 26, 255, 255, 255), 3 * dU)
            for i in 0..<4
            {
                let c = cells[i]
                g.SetClip(Rectangle(c.X, c.Y, c.Width, c.Height - plateH))
                g.DrawLine(gl, Double(c.X) + Double(c.Width) * 0.15, Double(c.Bottom), Double(c.X) + Double(c.Width) * 0.95, Double(c.Y) - Double(c.Width) * 0.2)
                g.ResetClip()
            }
        }
        let left = w.FocusLeft(), qleft = w.QuietLeft()
        if left >= 0 && qleft >= 0 { DrawBadge(g, left, false, -1); DrawBadge(g, qleft, true, 1) }
        else if left >= 0 { DrawBadge(g, left, false, 0) }
        else if qleft >= 0 { DrawBadge(g, qleft, true, 0) }
        if Hot
        {
            let hp = Pen(Over ? Color.FromArgb(230, 255, 120, 165) : Color.FromArgb(170, 255, 200, 120), Math.Max(2.0, dU))
            let p = RoundRect(RectangleF(dU * 0.5, dU * 0.5, Double(Area.Width - U - 2), Double(Area.Height - U - 2)), 3 * dU)
            g.DrawPath(hp, p)
        }
        return bmp
    }

    func DrawBadge(_ g: Graphics, _ left: Int, _ quiet: Bool, _ side: Int)
    {
        let cxb = side == 0 ? Double(Area.Width) / 2 : (side < 0 ? Double(Area.Width) * 0.28 : Double(Area.Width) * 0.72)
        DrawBadgeAt(g, left, quiet, cxb, Double(crown) * 0.5)
    }

    static let TOM_QUIET = [ "..yyy...", ".yy..zzz", "yy....z.", "yy...zzz", "yy......", ".yy.....", "..yyy...", "........" ]
    static let TOM_FOCUS = [ "...gg...", "..gggg..", ".rrrrrr.", "rrhrrrrr", "rhrrrrrr", "rrrrrrrr", ".rrrrrr.", "..rrrr.." ]
    // 小徽章：番茄（專注）或月亮＋zz（安靜）＋剩幾分鐘，中心在 (cxb, cyb)
    func DrawBadgeAt(_ g: Graphics, _ left: Int, _ quiet: Bool, _ cxb: Double, _ cyb: Double)
    {
        let tom = quiet ? ShelfForm.TOM_QUIET : ShelfForm.TOM_FOCUS
        let ps = Math.Max(2, U * 2 / 3)
        let dps = Double(ps), dU = Double(U)
        let txt = String(left) + " 分"
        let f = Font("Microsoft JhengHei UI", Math.Max(10.0, 7.5 * k), FontStyle.Bold, GraphicsUnit.Pixel)
        let ts = g.MeasureString(txt, f)
        let bw = 8 * dps + ts.Width + 3 * dU, bh = Math.Max(8 * dps, ts.Height) + dU
        let br = RectangleF(cxb - bw / 2, cyb - bh / 2, bw, bh)
        let p = RoundRect(br, bh / 2)
        g.FillPath(SolidBrush(quiet ? Color.FromArgb(235, 44, 48, 78) : Color.FromArgb(235, 255, 248, 236)), p)
        g.DrawPath(Pen(quiet ? Color.FromArgb(180, 150, 160, 230) : Color.FromArgb(180, 200, 80, 60), 1.0), p)
        let b = SolidBrush(Color.White)
        for r in 0..<8
        {
            var c = 0
            for ch in tom[r]
            {
                if ch != "."
                {
                    b.Color = ch == "g" ? Color.FromArgb(0x3C, 0xA0, 0x48) : (ch == "h" ? Color.FromArgb(0xFF, 0x9A, 0x8A) : (ch == "y" ? Color.FromArgb(0xFF, 0xDB, 0x6E) : (ch == "z" ? Color.FromArgb(0xC8, 0xD0, 0xFF) : Color.FromArgb(0xE2, 0x3B, 0x2E))))
                    g.FillRectangle(b, br.X + dU + Double(c) * dps, br.Y + (bh - 8 * dps) / 2 + Double(r) * dps, dps, dps)
                }
                c += 1
            }
        }
        g.DrawString(txt, f, SolidBrush(quiet ? Color.FromArgb(0xE6, 0xE8, 0xFF) : Color.FromArgb(0x8A, 0x2A, 0x1E)), br.X + dU * 1.5 + 8 * dps, br.Y + (bh - ts.Height) / 2)
    }

    static let SIL = [ "...kkkkkk...", "..kkkkkkkk..", ".kkkkkkkkkk.", ".kkkkkkkkkk.", ".kkkkkkkkkk.", ".kkkkkkkkkk.", "..kkkkkkkk..", "...kkkkkk...",
        "...kkkkkk...", "..kkkkkkkk..", ".kkkkkkkkkk.", ".kkkkkkkkkk.", "..kkkkkkkk..", "..kkk..kkk..", "..kkk..kkk..", "..kkk..kkk.." ]
    // 空格：淡淡的問號剪影
    func DrawUnknown(_ g: Graphics, _ fx: Int, _ fy: Int, _ ps: Int)
    {
        let b = SolidBrush(Color.FromArgb(Night ? 40 : 34, 60, 40, 20))
        for r in 0..<16
        {
            var c = 0
            for ch in ShelfForm.SIL[r].utf8
            {
                if ch != 46 { g.FillRectangle(b, fx - 6 * ps + c * ps, fy - 16 * ps + r * ps, ps, ps) }
                c += 1
            }
        }
        let f = Font("Arial", Double(7 * ps), FontStyle.Bold, GraphicsUnit.Pixel)
        let b2 = SolidBrush(Color.FromArgb(Night ? 70 : 80, 255, 255, 255))
        let sf = StringFormat()
        sf.Alignment = StringAlignment.Center; sf.LineAlignment = StringAlignment.Center
        g.DrawString("?", f, b2, RectangleF(Double(fx - 6 * ps), Double(fy - 16 * ps), Double(12 * ps), Double(9 * ps)), sf)
    }

    // 外出中：空的展示台＋掛著的小牌子
    func DrawAway(_ g: Graphics, _ c: Rectangle, _ ps: Int)
    {
        let fx = c.X + c.Width / 2, fy = c.Bottom - plateH - U
        let dps = Double(ps), dU = Double(U), dfx = Double(fx)
        g.FillEllipse(SolidBrush(Color.FromArgb(70, 80, 50, 25)), fx - 5 * ps, fy - ps, 10 * ps, 2 * ps)
        let tagW = Math.Max(13 * dps * 0.9, 15 * dU), tagH = Math.Max(4.6 * dps, 5.2 * dU), ty = Double(c.Y) + Double(c.Height) * 0.32
        let str = Pen(Color.FromArgb(150, 110, 80, 50), 1.0)
        g.DrawLine(str, dfx - tagW * 0.3, Double(c.Y + 2), dfx - tagW * 0.25, ty)
        g.DrawLine(str, dfx + tagW * 0.3, Double(c.Y + 2), dfx + tagW * 0.25, ty)
        let tr = RectangleF(dfx - tagW / 2, ty, tagW, tagH)
        let p = RoundRect(tr, dps)
        g.FillPath(SolidBrush(Night ? Color.FromArgb(235, 70, 58, 80) : Color.FromArgb(240, 255, 250, 238)), p)
        g.DrawPath(Pen(Color.FromArgb(160, 150, 110, 70), 1.0), p)
        let f = Font("Microsoft JhengHei UI", Math.Max(10.0, 2.7 * dps), FontStyle.Bold, GraphicsUnit.Pixel)
        let tb = SolidBrush(Night ? Color.FromArgb(0xFF, 0xE6, 0xC8) : Color.FromArgb(0x8A, 0x5A, 0x2A))
        let sf = StringFormat()
        sf.Alignment = StringAlignment.Center; sf.LineAlignment = StringAlignment.Center
        g.TextRenderingHint = TextRenderingHint.AntiAlias
        g.DrawString("外出中", f, tb, RectangleF(tr.X - 6, tr.Y, tr.Width + 12, tr.Height), sf)
    }
}

extension Pet
{
    var ShelfSeed: Int { return P.Id.utf8.count * 7 + Int(P.Id.utf8.first ?? 0) }

    // 在櫃子格子裡：小小地動（呼吸、眨眼、各自的招牌小動作）
    func DrawOnShelf(_ g: Graphics, _ fx: Int, _ fy: Int, _ ps: Int, _ cell: Rectangle, _ t: Double)
    {
        let tt = t + Double(ShelfSeed) * 0.37
        let blink = (tt % 4.3) < 0.14
        let breathe = (tt * 0.8 % 1) < 0.5 ? 0 : 1
        let bx = fx - 6 * ps, by = fy - 16 * ps + breathe
        let flip = (Math.Floor(tt / 9) % 2) == 1
        let dps = Double(ps)
        var head = A("HEAD")
        switch P.Id
        {
            case "spidey":
                // 從格子頂端垂一條絲倒吊著晃；偶爾跳下來擺個噴絲姿勢
                let dangle = (tt % 11) < 8
                if blink { ReplaceFace(&head, "SLEEPY") }
                var rows = Pal.Stack(head, A(dangle ? "BODY" : "ARMS_UP"), A("LEGS_A"))   // Spidey 剛好 16 列
                if Night { if Pet.PixAt(rows[10], 5) == 107 && Pet.PixAt(rows[10], 6) == 107 { rows[10] = Pet.SetPix(Pet.SetPix(rows[10], 5, 119), 6, 119) } }
                if dangle
                {
                    let sway = CInt(Math.Round(Math.Sin(tt * 1.3) * dps * 0.8))
                    let topY = Math.Max(cell.Y + 3 * ps, fy - 19 * ps) + CInt(Math.Round(Math.Sin(tt * 2.1) * dps * 0.7))
                    let silk = Pen(Night ? Color.FromArgb(200, 150, 140, 210) : Color.FromArgb(220, 255, 255, 255), Math.Max(1.0, dps * 0.4))
                    g.DrawLine(silk, Double(fx), Double(cell.Y), Double(fx + sway), Double(topY + 2))
                    DrawPix(g, rows, bx + sway, topY, ps, flip, true, true)
                }
                else
                {
                    DrawPix(g, rows, bx, by, ps, flip, false, true)
                    let silk = Pen(Color.FromArgb(200, 255, 255, 255), Math.Max(1.0, dps * 0.4))
                    g.DrawLine(silk, Double(bx + (flip ? 1 : 11) * ps), Double(by + 8 * ps), Double(flip ? cell.X + 2 : cell.Right - 2), Double(cell.Y + 4))
                    DrawAccessories(g, bx, by, ps, flip, 0, true)
                }
                DrawShelfWeb(g, cell, ps)
            case "po":
                // 扶著停在旁邊的滑板車，跟車子一起前後搖
                if blink || Night && (tt % 5) < 2 { ReplaceFace(&head, "SLEEPY") }
                let f = F(Pal.Stack(head, A("BODY"), A("LEGS_A"))); f.Tummy = true
                let rock = CInt(Math.Round(Math.Sin(tt * 2.2) * dps * 0.6))
                DrawAt(g, A("SCOOTER"), 3, 7, bx + rock, by - breathe, ps, !flip, false, true)
                DrawPix(g, f.Rows, bx + rock - (f.Rows[0].utf8.count - 12) / 2 * ps, by + (16 - f.Rows.count) * ps, ps, flip, false, true)
                DrawAccessories(g, bx + rock, by, ps, flip, f.AccDy, true)
                DrawStatusIcon(g, TummyStatus(), bx + rock + 6 * ps, by + CInt((10.5 + Double(f.AccDy)) * dps), Math.Max(1, ps / 2), true)
            case "stitch":
                // 耳朵抖抖、壞壞地笑；晚上耳朵垂下來抱著烏克麗麗
                var body = "BODY"
                if Night { let ed = A("EARS_DOWN"); for i in 0..<ed.count { head[i] = ed[i] }; body = "ARMS_HUG"; if (tt % 6) < 3 { ReplaceFace(&head, "SLEEPY") } }
                else
                {
                    if (tt % 1.7) < 0.35 { let eu = A("EARS_UP"); for i in 0..<eu.count { head[i] = eu[i] } }
                    if (tt % 7) < 3 { ReplaceFace(&head, "GRIN") }
                    if blink { ReplaceFace(&head, "SLEEPY") }
                }
                let rows = Pal.Stack(head, A(body), A("LEGS_A"))
                DrawPix(g, rows, bx - (rows[0].utf8.count - 12) / 2 * ps, by + (16 - rows.count) * ps, ps, flip, false, true)
                DrawAccessories(g, bx, by, ps, flip, 0, true)
                if Night { DrawAt(g, A("UKE"), 5, 8, bx, by, ps, flip, false, true) }
            case "hangyodon":
                // 像海草一樣在水裡輕輕搖、吐泡泡；晚上睡在泡泡裡
                if Night || blink { ReplaceFace(&head, "SLEEPY") }
                let rows = Pal.Stack(head, A(Night ? "BODY" : ((tt % 6) < 1.2 ? "POUT" : "BODY")), A(Night ? "LEGS_SIT" : "LEGS_A"))
                let sway = CInt(Math.Round(Math.Sin(tt * 1.4) * dps * 0.8))
                let lx = bx - (rows[0].utf8.count - 12) / 2 * ps + sway
                if Night { DrawSleepBubble(g, bx, by, ps, false) }
                DrawPix(g, rows, lx, by + (16 - rows.count) * ps, ps, flip, false, true)
                DrawAccessories(g, bx + sway, by, ps, flip, 0, !Night)
                if Night { DrawSleepBubble(g, bx, by, ps, true) }
                // 泡泡從嘴巴冒上去
                let bp = Pen(Color.FromArgb(190, 150, 215, 255), Math.Max(1.0, dps * 0.35))
                for i in 0..<3
                {
                    let ph = (tt * 0.45 + Double(i) / 3.0) % 1
                    let r = dps * (0.5 + ph * 0.9)
                    let px = Double(fx + sway) + Math.Sin(ph * 9 + Double(i)) * dps + Double((flip ? -3 : 3) * ps)
                    let py = Double(by + 8 * ps) - ph * 9 * dps
                    if py > Double(cell.Y) + r { g.DrawEllipse(bp, px - r, py - r, 2 * r, 2 * r) }
                }
            case "tinky", "dipsy", "laalaa":
                DrawTubbyShelf(g, head, fx, bx, by, ps, flip, tt, blink)
            default:
                if blink { ReplaceFace(&head, "SLEEPY") }
                do { let rows = Pal.Stack(head, A("BODY"), A("LEGS_A")); DrawPix(g, rows, bx - (rows[0].utf8.count - 12) / 2 * ps, by + (16 - rows.count) * ps, ps, flip, false, true) }
                DrawAccessories(g, bx, by, ps, flip, 0, true)
        }
        // 午餐時間：櫃子裡的公仔也拿著午餐
        if w.Lunch && !(Is("spidey") && (tt % 11) < 8) { DrawLunchShelf(g, bx, by, ps, flip) }
        // 剛回櫃子：一圈小星星
        if ShelfFx < 1
        {
            let sp = Math.Max(1, ps / 2)
            for i in 0..<6
            {
                let a = Double(i) * Math.PI / 3 + ShelfFx * 2, rr = (4 + ShelfFx * 7) * dps
                if Math.Floor(ShelfFx * 18 + Double(i)) % 2 == 0
                { DrawPix(g, Pet.STAR, CInt(Double(fx) + Math.Cos(a) * rr) - sp, CInt(Double(fy) - 8 * dps + Math.Sin(a) * rr * 0.8) - sp, sp, false, false, false) }
            }
        }
    }

    // mac: C# mutated the array in place → inout (call as ReplaceFace(&head, "SLEEPY"))
    func ReplaceFace(_ head: inout [String], _ face: String)
    {
        if !P.Art.ContainsKey(face) { return }
        let fr = A(face)
        var i = 0
        while i < fr.count && P.FaceRow + i < head.count
        {
            if fr[i].utf8.count == head[P.FaceRow + i].utf8.count { head[P.FaceRow + i] = fr[i] }
            i += 1
        }
    }

    // Spidey 回櫃子時在格子左上角織一張小圓網（ShelfFx 0→1 織完）
    func DrawShelfWeb(_ g: Graphics, _ cell: Rectangle, _ ps: Int)
    {
        let prog = Math.Min(1.0, ShelfFx * 1.3)
        let cx = Double(cell.X + 1), cy = Double(cell.Y + 1), R0 = 11 * Double(ps)
        let spokes = 6
        let sh = Pen(Color.FromArgb(70, 40, 30, 60), Math.Max(1.6, Double(ps) * 0.55))
        let silk = Pen(Night ? Color.FromArgb(220, 214, 204, 255) : Color.FromArgb(235, 255, 255, 255), Math.Max(1.0, Double(ps) * 0.35))
        let pens = [ sh, silk ]
        for p in pens
        {
            for i in 0..<spokes
            {
                let a = Math.PI / 2 * Double(i) / Double(spokes - 1)
                g.DrawLine(p, cx, cy, cx + Math.Cos(a) * R0 * Math.Min(1.0, prog * 2), cy + Math.Sin(a) * R0 * Math.Min(1.0, prog * 2))
            }
            let rings = 4, shown = CInt(Math.Floor(Double(rings) * Math.Max(0.0, prog * 2 - 1) + 0.001))
            var r = 0
            while r < shown
            {
                let rr = R0 * (0.3 + 0.7 * Double(r + 1) / Double(rings))
                var i = 0
                while i + 1 < spokes
                {
                    let a1 = Math.PI / 2 * Double(i) / Double(spokes - 1), a2 = Math.PI / 2 * Double(i + 1) / Double(spokes - 1), am = (a1 + a2) / 2
                    let p1 = PointF(cx + Math.Cos(a1) * rr, cy + Math.Sin(a1) * rr)
                    let p2 = PointF(cx + Math.Cos(a2) * rr, cy + Math.Sin(a2) * rr)
                    let pm = PointF(cx + Math.Cos(am) * rr * 0.9, cy + Math.Sin(am) * rr * 0.9)
                    g.DrawLine(p, p1, pm); g.DrawLine(p, pm, p2)
                    i += 1
                }
                r += 1
            }
        }
    }
}

